window.TAILIEU_CARDS = [{"id": 1, "cat": "c1", "q": "Theo tài liệu tóm tắt Chương 1, từ nửa sau thế kỷ XIX, chủ nghĩa tư bản chuyển sang giai đoạn nào?", "options": ["A. Giai đoạn kinh tế tri thức", "B. Giai đoạn hậu công nghiệp", "C. Giai đoạn đế quốc chủ nghĩa", "D. Chủ nghĩa tư bản tự do cạnh tranh"], "answer": "C. Giai đoạn đế quốc chủ nghĩa", "letter": "C"}, {"id": 2, "cat": "c1", "q": "Hai cuộc khai thác thuộc địa của thực dân Pháp ở Việt Nam được tiến hành trong các khoảng thời gian nào?", "options": ["A. 1895–1910 và 1919–1935", "B. 1884–1896 và 1914–1918", "C. 1897–1914 và 1919–1929", "D. 1900–1918 và 1920–1930"], "answer": "C. 1897–1914 và 1919–1929", "letter": "C"}, {"id": 3, "cat": "c1", "q": "Dưới tác động của chính sách \"chia để trị\" và hai cuộc khai thác thuộc địa của Pháp, mâu thuẫn nào trở thành mâu thuẫn cơ bản, gay gắt nhất trong xã hội Việt Nam?", "options": ["A. Mâu thuẫn giữa toàn thể dân tộc Việt Nam với thực dân Pháp", "B. Mâu thuẫn giữa nông dân với địa chủ phong kiến", "C. Mâu thuẫn giữa tiểu tư sản với chế độ phong kiến", "D. Mâu thuẫn giữa tư sản dân tộc với tư sản mại bản"], "answer": "A. Mâu thuẫn giữa toàn thể dân tộc Việt Nam với thực dân Pháp", "letter": "A"}, {"id": 4, "cat": "c1", "q": "Nguyên nhân cốt lõi dẫn đến sự thất bại của các phong trào yêu nước theo khuynh hướng phong kiến (Cần Vương) và dân chủ tư sản đầu thế kỷ XX là gì?", "options": ["A. Thực dân Pháp nhận được viện trợ quân sự từ Mỹ", "B. Nhân dân không ủng hộ phong trào yêu nước", "C. Các sĩ phu yêu nước không có tinh thần đấu tranh kiên quyết", "D. Thiếu đường lối chính trị đúng đắn, chưa có giai cấp tiên phong lãnh đạo và phương pháp cách mạng chưa phù hợp"], "answer": "D. Thiếu đường lối chính trị đúng đắn, chưa có giai cấp tiên phong lãnh đạo và phương pháp cách mạng chưa phù hợp", "letter": "D"}, {"id": 5, "cat": "c1", "q": "Sự kiện nào vào tháng 12/1920 đánh dấu bước ngoặt tư tưởng đưa Nguyễn Ái Quốc trở thành người cộng sản Việt Nam đầu tiên?", "options": ["A. Ra đi tìm đường cứu nước tại bến Nhà Rồng", "B. Thành lập Hội Việt Nam Cách mạng Thanh niên tại Quảng Châu", "C. Bỏ phiếu tán thành gia nhập Quốc tế Cộng sản tại Đại hội Tours và tham gia sáng lập Đảng Cộng sản Pháp", "D. Gửi bản Yêu sách của nhân dân An Nam đến Hội nghị Vécxây"], "answer": "C. Bỏ phiếu tán thành gia nhập Quốc tế Cộng sản tại Đại hội Tours và tham gia sáng lập Đảng Cộng sản Pháp", "letter": "C"}, {"id": 6, "cat": "c1", "q": "Tác phẩm \"Bản án chế độ thực dân Pháp\" được Nguyễn Ái Quốc xuất bản vào năm nào?", "options": ["A. Năm 1927", "B. Năm 1925", "C. Năm 1922", "D. Năm 1920"], "answer": "B. Năm 1925", "letter": "B"}, {"id": 7, "cat": "c1", "q": "Tác phẩm \"Đường Kách mệnh\" được Nguyễn Ái Quốc biên soạn vào năm nào để truyền bá chủ nghĩa Mác – Lênin về nước?", "options": ["A. Năm 1927", "B. Năm 1925", "C. Năm 1929", "D. Năm 1924"], "answer": "A. Năm 1927", "letter": "A"}, {"id": 8, "cat": "c1", "q": "Theo tài liệu tóm tắt Chương 1, thứ tự thời gian ra đời của ba tổ chức cộng sản tại Việt Nam năm 1929 là gì?", "options": ["A. Đông Dương Cộng sản Đảng (6/1929), Đông Dương Cộng sản Liên đoàn (9/1929), An Nam Cộng sản Đảng (11/1929)", "B. Đông Dương Cộng sản Đảng (3/1929), An Nam Cộng sản Đảng (8/1929), Đông Dương Cộng sản Liên đoàn (12/1929)", "C. Đông Dương Cộng sản Liên đoàn (6/1929), Đông Dương Cộng sản Đảng (9/1929), An Nam Cộng sản Đảng (11/1929)", "D. An Nam Cộng sản Đảng (6/1929), Đông Dương Cộng sản Đảng (9/1929), Đông Dương Cộng sản Liên đoàn (11/1929)"], "answer": "A. Đông Dương Cộng sản Đảng (6/1929), Đông Dương Cộng sản Liên đoàn (9/1929), An Nam Cộng sản Đảng (11/1929)", "letter": "A"}, {"id": 9, "cat": "c1", "q": "Hội nghị hợp nhất thành lập Đảng Cộng sản Việt Nam tại Cửu Long (Hương Cảng, Trung Quốc) diễn ra trong khoảng thời gian nào?", "options": ["A. Từ ngày 6/1 đến 7/2/1930", "B. Từ ngày 1/2 đến 8/2/1930", "C. Từ ngày 3/1 đến 3/2/1930", "D. Từ ngày 10/1 đến 15/2/1930"], "answer": "A. Từ ngày 6/1 đến 7/2/1930", "letter": "A"}, {"id": 10, "cat": "c1", "q": "Nguyễn Ái Quốc chủ trì Hội nghị hợp nhất thành lập Đảng Cộng sản Việt Nam đầu năm 1930 với tư cách gì?", "options": ["A. Tổng Bí thư lâm thời của Đảng", "B. Phái viên của Quốc tế Cộng sản", "C. Chủ tịch Hội Việt Nam Cách mạng Thanh niên", "D. Đại biểu của Đông Dương Cộng sản Đảng"], "answer": "B. Phái viên của Quốc tế Cộng sản", "letter": "B"}, {"id": 11, "cat": "c1", "q": "Bốn văn kiện do Nguyễn Ái Quốc soạn thảo được thông qua tại Hội nghị thành lập Đảng Cộng sản Việt Nam (2/1930) là gì?", "options": ["A. Luận cương chính trị, Chánh cương vắn tắt, Điều lệ tóm tắt, Lời kêu gọi", "B. Đường Kách mệnh, Chánh cương vắn tắt, Sách lược vắn tắt, Điều lệ Đảng", "C. Chánh cương vắn tắt, Luận cương chính trị, Sách lược vắn tắt, Chương trình hành động", "D. Chánh cương vắn tắt, Sách lược vắn tắt, Chương trình tóm tắt, Điều lệ vắn tắt"], "answer": "D. Chánh cương vắn tắt, Sách lược vắn tắt, Chương trình tóm tắt, Điều lệ vắn tắt", "letter": "D"}, {"id": 12, "cat": "c1", "q": "Về nhiệm vụ kinh tế, Cương lĩnh chính trị đầu tiên của Đảng (2/1930) chủ trương nội dung nào sau đây?", "options": ["A. Phát triển kinh tế thị trường nhiều thành phần định hướng xã hội chủ nghĩa", "B. Tịch thu sản nghiệp lớn của đế quốc, chia ruộng đất cho dân cày nghèo, bỏ sưu thuế", "C. Chỉ cải cách giảm tô, giảm tức mà không tịch thu sản nghiệp đế quốc", "D. Quốc hữu hóa toàn bộ ruộng đất của cả nông dân và địa chủ"], "answer": "B. Tịch thu sản nghiệp lớn của đế quốc, chia ruộng đất cho dân cày nghèo, bỏ sưu thuế", "letter": "B"}, {"id": 13, "cat": "c1", "q": "Về nhiệm vụ xã hội, Cương lĩnh chính trị đầu tiên của Đảng (2/1930) xác định chủ trương nào?", "options": ["A. Nam nữ bình quyền, phổ thông giáo dục theo công nông hóa", "B. Chỉ mở trường học cho con em giai cấp công nhân", "C. Xây dựng nền văn hóa tiên tiến, đậm đà bản sắc dân tộc", "D. Phát triển giáo dục đại học và khoa học công nghệ làm quốc sách hàng đầu"], "answer": "A. Nam nữ bình quyền, phổ thông giáo dục theo công nông hóa", "letter": "A"}, {"id": 14, "cat": "c1", "q": "Trong Cương lĩnh chính trị đầu tiên (2/1930), Đảng chủ trương đối sách như thế nào đối với phú nông, trung – tiểu địa chủ và tư bản An Nam?", "options": ["A. Đánh đổ hoàn toàn như đế quốc xâm lược", "B. Xác định họ là lực lượng lãnh đạo cách mạng", "C. Đứng ngoài mặt trận dân tộc thống nhất và không tiếp xúc", "D. Lợi dụng hoặc trung lập"], "answer": "D. Lợi dụng hoặc trung lập", "letter": "D"}, {"id": 15, "cat": "c1", "q": "Phương pháp cách mạng được xác định trong Cương lĩnh chính trị đầu tiên của Đảng (2/1930) là gì?", "options": ["A. Thương lượng từng bước với chính quyền thực dân Pháp", "B. Bạo lực cách mạng của quần chúng, không bao giờ thỏa hiệp", "C. Chỉ sử dụng đấu tranh ngoại giao nhờ sự giúp đỡ của quốc tế", "D. Đấu tranh nghị trường và cải cách hòa bình"], "answer": "B. Bạo lực cách mạng của quần chúng, không bao giờ thỏa hiệp", "letter": "B"}, {"id": 16, "cat": "c1", "q": "Vai trò lãnh đạo của Đảng được nêu trong Cương lĩnh chính trị đầu tiên (2/1930) là gì?", "options": ["A. Đảng là tổ chức liên minh giữa tư sản dân tộc và địa chủ yêu nước", "B. Đảng là cơ quan hành chính tối cao của Nhà nước", "C. Đảng là đội tiên phong của vô sản giai cấp, phải làm cho giai cấp mình lãnh đạo được dân chúng", "D. Đảng chỉ đại diện cho lợi ích riêng của tầng lớp trí thức"], "answer": "C. Đảng là đội tiên phong của vô sản giai cấp, phải làm cho giai cấp mình lãnh đạo được dân chúng", "letter": "C"}, {"id": 17, "cat": "c1", "q": "Theo tài liệu Chương 1, nguyên nhân nào dẫn đến những hạn chế trong Luận cương chính trị tháng 10/1930?", "options": ["A. Do chịu ảnh hưởng của khuynh hướng dân chủ tư sản", "B. Do chịu ảnh hưởng của tư tưởng \"tả\" khuynh", "C. Do thiếu sự tham gia của giai cấp công nhân", "D. Do Đảng chưa có hệ thống tổ chức ở địa phương"], "answer": "B. Do chịu ảnh hưởng của tư tưởng \"tả\" khuynh", "letter": "B"}, {"id": 18, "cat": "c1", "q": "Chính quyền Xô viết được thành lập tại một số xã ở Nghệ An và Hà Tĩnh trong cao trào 1930–1931 mang ý nghĩa lịch sử gì?", "options": ["A. Hình thức chính quyền liên hiệp với tư sản dân tộc đầu tiên ở Việt Nam", "B. Chính quyền tự trị thuộc khối Liên hiệp Pháp", "C. Chính phủ lâm thời của nước Việt Nam Dân chủ Cộng hòa", "D. Hình thức chính quyền công nông đầu tiên ở Việt Nam"], "answer": "D. Hình thức chính quyền công nông đầu tiên ở Việt Nam", "letter": "D"}, {"id": 19, "cat": "c1", "q": "Để từng bước khôi phục hệ thống tổ chức và phong trào quần chúng sau khủng bố trắng, năm 1932 Đảng đã công bố văn kiện nào?", "options": ["A. Đề cương về văn hóa Việt Nam", "B. Luận cương chính trị", "C. Chương trình hành động của Đảng", "D. Chỉ thị Kháng chiến kiến quốc"], "answer": "C. Chương trình hành động của Đảng", "letter": "C"}, {"id": 20, "cat": "dh1_12", "q": "Đại hội đại biểu toàn quốc lần thứ I của Đảng (3/1935) được tổ chức tại đâu và có ý nghĩa gì?", "options": ["A. Tại Ma Cao (Trung Quốc) — đánh dấu sự phục hồi hệ thống tổ chức của Đảng và phong trào quần chúng", "B. Tại Cửu Long (Hương Cảng) — thông qua Cương lĩnh đầu tiên", "C. Tại Chiêm Hóa (Tuyên Quang) — đưa Đảng ra hoạt động công khai", "D. Tại Pác Bó (Cao Bằng) — hoàn chỉnh chuyển hướng chiến lược giải phóng dân tộc"], "answer": "A. Tại Ma Cao (Trung Quốc) — đánh dấu sự phục hồi hệ thống tổ chức của Đảng và phong trào quần chúng", "letter": "A"}, {"id": 21, "cat": "c1", "q": "Trong phong trào dân chủ 1936–1939, Đảng chủ trương tạm gác hai khẩu hiệu nào?", "options": ["A. \"Độc lập dân tộc\" và \"Cách mạng ruộng đất\"", "B. \"Tự do dân chủ\" và \"Cơm áo hòa bình\"", "C. \"Đoàn kết công nông\" và \"Đấu tranh báo chí\"", "D. \"Chống phát xít\" và \"Chống chiến tranh\""], "answer": "A. \"Độc lập dân tộc\" và \"Cách mạng ruộng đất\"", "letter": "A"}, {"id": 22, "cat": "c1", "q": "Ý nghĩa lịch sử của phong trào dân chủ 1936–1939 đối với Cách mạng Tháng Tám 1945 là gì?", "options": ["A. Là cuộc tổng diễn tập thứ hai chuẩn bị cho Cách mạng Tháng Tám; tôi luyện cán bộ, mở rộng ảnh hưởng quần chúng", "B. Đánh đổ hoàn toàn chế độ thực dân Pháp ở Đông Dương", "C. Là cuộc tổng diễn tập đầu tiên chuẩn bị cho Cách mạng Tháng Tám", "D. Thành lập chính quyền Xô viết trên phạm vi cả nước"], "answer": "A. Là cuộc tổng diễn tập thứ hai chuẩn bị cho Cách mạng Tháng Tám; tôi luyện cán bộ, mở rộng ảnh hưởng quần chúng", "letter": "A"}, {"id": 23, "cat": "c1", "q": "Sự kiện nào vào tháng 9/1940 đẩy nhân dân Việt Nam vào cảnh \"một cổ hai tròng\"?", "options": ["A. Nhật đảo chính Pháp độc chiếm Đông Dương", "B. Quân Trung Hoa Dân quốc kéo vào miền Bắc Việt Nam", "C. Phát xít Nhật tiến vào Đông Dương", "D. Chiến tranh thế giới thứ hai bùng nổ ở châu Âu"], "answer": "C. Phát xít Nhật tiến vào Đông Dương", "letter": "C"}, {"id": 24, "cat": "c1", "q": "Mặt trận Việt Nam Độc lập Đồng minh (Mặt trận Việt Minh) được thành lập vào ngày tháng năm nào?", "options": ["A. Ngày 13/8/1945", "B. Ngày 22/12/1944", "C. Ngày 19/5/1941", "D. Ngày 12/3/1941"], "answer": "C. Ngày 19/5/1941", "letter": "C"}, {"id": 25, "cat": "c1", "q": "Hội nghị Trung ương 8 (5/1941) do lãnh tụ Nguyễn Ái Quốc chủ trì được tổ chức tại địa điểm nào?", "options": ["A. Tân Trào (Tuyên Quang)", "B. Pác Bó (Cao Bằng)", "C. Đình Bảng (Bắc Ninh)", "D. Bà Điểm (Hóc Môn, Gia Định)"], "answer": "B. Pác Bó (Cao Bằng)", "letter": "B"}, {"id": 26, "cat": "c1", "q": "Ngày 22/12/1944 gắn với sự kiện lịch sử trọng đại nào?", "options": ["A. Thành lập Đội Việt Nam Tuyên truyền Giải phóng quân — tiền thân của Quân đội nhân dân Việt Nam", "B. Ban hành Đề cương về văn hóa Việt Nam", "C. Phát động cao trào kháng Nhật cứu nước", "D. Thành lập Ủy ban Khởi nghĩa toàn quốc"], "answer": "A. Thành lập Đội Việt Nam Tuyên truyền Giải phóng quân — tiền thân của Quân đội nhân dân Việt Nam", "letter": "A"}, {"id": 27, "cat": "c1", "q": "Chỉ thị \"Nhật – Pháp bắn nhau và hành động của chúng ta\" (12/3/1945) của Ban Thường vụ Trung ương Đảng đã phát động phong trào nào?", "options": ["A. Phong trào Đồng khởi", "B. Cao trào kháng Nhật cứu nước", "C. Phong trào Bình dân học vụ", "D. Phong trào Đông Dương Đại hội"], "answer": "B. Cao trào kháng Nhật cứu nước", "letter": "B"}, {"id": 28, "cat": "c1", "q": "Ngày 13/8/1945, Ủy ban Khởi nghĩa toàn quốc được thành lập và đến 23 giờ cùng ngày đã ban bố văn kiện nào?", "options": ["A. Quân lệnh số 1 phát lệnh Tổng khởi nghĩa", "B. Chỉ thị Kháng chiến kiến quốc", "C. Tuyên ngôn Độc lập", "D. Lời kêu gọi toàn quốc kháng chiến"], "answer": "A. Quân lệnh số 1 phát lệnh Tổng khởi nghĩa", "letter": "A"}, {"id": 29, "cat": "c1", "q": "Hội nghị toàn quốc của Đảng và Đại hội Quốc dân Tân Trào quyết định phát động Tổng khởi nghĩa tháng Tám năm 1945 diễn ra vào thời gian nào?", "options": ["A. Ngày 17–18/8/1945 và ngày 19/8/1945", "B. Ngày 20–22/8/1945 và ngày 25/8/1945", "C. Ngày 9–12/8/1945 và ngày 13/8/1945", "D. Ngày 14–15/8/1945 và ngày 16/8/1945"], "answer": "D. Ngày 14–15/8/1945 và ngày 16/8/1945", "letter": "D"}, {"id": 30, "cat": "c1", "q": "Theo tài liệu Chương 1, tính chất của Cách mạng Tháng Tám năm 1945 là gì?", "options": ["A. Cuộc cách mạng giải phóng dân tộc điển hình, mang tính chất dân chủ mới, do giai cấp công nhân lãnh đạo, dựa trên lực lượng toàn dân và mang tính nhân dân sâu sắc", "B. Cuộc đảo chính quân sự giành chính quyền từ tay phát xít Nhật", "C. Cuộc cách mạng tư sản dân quyền cũ do giai cấp tư sản lãnh đạo", "D. Cuộc cách mạng xã hội chủ nghĩa thuần túy ở vùng nông thôn"], "answer": "A. Cuộc cách mạng giải phóng dân tộc điển hình, mang tính chất dân chủ mới, do giai cấp công nhân lãnh đạo, dựa trên lực lượng toàn dân và mang tính nhân dân sâu sắc", "letter": "A"}, {"id": 31, "cat": "c2", "q": "Ngay sau Cách mạng Tháng Tám 1945, lực lượng quân đội nước ngoài nào đã kéo vào miền Bắc Việt Nam kèm theo các tổ chức phản động Việt Quốc, Việt Cách?", "options": ["A. 20 vạn quân Pháp", "B. 20 vạn quân Trung Hoa Dân quốc (quân Tưởng)", "C. 15 vạn quân Mỹ", "D. 10 vạn quân Anh"], "answer": "B. 20 vạn quân Trung Hoa Dân quốc (quân Tưởng)", "letter": "B"}, {"id": 32, "cat": "c2", "q": "Chỉ thị \"Kháng chiến kiến quốc\" ngày 25/11/1945 của Ban Chấp hành Trung ương Đảng đề ra 4 nhiệm vụ trước mắt là gì?", "options": ["A. Cải cách ruộng đất, công nghiệp hóa, quốc hữu hóa và hợp tác xã hóa", "B. Xây dựng kinh tế thị trường, mở cửa đối ngoại, gia nhập Liên Hợp Quốc, xóa mù chữ", "C. Củng cố chính quyền, chống thực dân Pháp xâm lược, bài trừ nội phản, cải thiện đời sống nhân dân", "D. Đánh đuổi quân Tưởng, đánh đuổi quân Anh, mở chiến dịch Điện Biên Phủ, ký Hiệp định Giơnevơ"], "answer": "C. Củng cố chính quyền, chống thực dân Pháp xâm lược, bài trừ nội phản, cải thiện đời sống nhân dân", "letter": "C"}, {"id": 33, "cat": "c2", "q": "Để chống \"giặc đói\" ngay sau Cách mạng Tháng Tám 1945, Đảng và Chính phủ đã phát động phong trào nào?", "options": ["A. \"Bình dân học vụ\" và \"Tuần lễ vàng\"", "B. \"Khoán 100\" và \"Khoán 10\"", "C. \"Ba sẵn sàng\" và \"Ba đảm đang\"", "D. \"Tăng gia sản xuất ngay, tăng gia sản xuất nữa\", \"Hũ gạo tiết kiệm\", \"Ngày đồng tâm\""], "answer": "D. \"Tăng gia sản xuất ngay, tăng gia sản xuất nữa\", \"Hũ gạo tiết kiệm\", \"Ngày đồng tâm\"", "letter": "D"}, {"id": 34, "cat": "c2", "q": "Để giải quyết khó khăn về tài chính sau Cách mạng Tháng Tám 1945, Chính phủ đã thành lập \"Quỹ Độc lập\" và tổ chức \"Tuần lễ vàng\" vào thời gian nào?", "options": ["A. Quỹ Độc lập (23/9/1945) và Tuần lễ vàng (1–7/10/1945)", "B. Quỹ Độc lập (11/11/1945) và Tuần lễ vàng (25/11–2/12/1945)", "C. Quỹ Độc lập (4/9/1945) và Tuần lễ vàng (17–24/9/1945)", "D. Quỹ Độc lập (2/9/1945) và Tuần lễ vàng (5–12/9/1945)"], "answer": "C. Quỹ Độc lập (4/9/1945) và Tuần lễ vàng (17–24/9/1945)", "letter": "C"}, {"id": 35, "cat": "c2", "q": "Kết quả của phong trào \"Bình dân học vụ\" tính đến cuối năm 1946 là gì?", "options": ["A. Có hơn 2,5 triệu người biết đọc, biết viết", "B. Xóa mù chữ hoàn toàn 100% dân số cả nước", "C. Có hơn 10 triệu người tốt nghiệp tiểu học", "D. Có hơn 500 nghìn người biết đọc, biết viết"], "answer": "A. Có hơn 2,5 triệu người biết đọc, biết viết", "letter": "A"}, {"id": 36, "cat": "c2", "q": "Cuộc Tổng tuyển cử bầu Quốc hội khóa I và việc thông qua bản Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa diễn ra vào thời gian nào?", "options": ["A. Tổng tuyển cử 19/5/1946 và Hiến pháp tháng 9/1946", "B. Tổng tuyển cử 6/1/1946 và Hiến pháp tháng 11/1946", "C. Tổng tuyển cử 2/9/1945 và Hiến pháp tháng 3/1946", "D. Tổng tuyển cử 6/3/1946 và Hiến pháp tháng 12/1946"], "answer": "B. Tổng tuyển cử 6/1/1946 và Hiến pháp tháng 11/1946", "letter": "B"}, {"id": 37, "cat": "c2", "q": "Mục đích chiến lược của việc Chính phủ ta ký Hiệp định Sơ bộ (6/3/1946) và Tạm ước (14/9/1946) với thực dân Pháp là gì?", "options": ["A. Xin gia nhập khối Liên hiệp Pháp để nhận viện trợ kinh tế", "B. Chấm dứt hoàn toàn chiến tranh và tiến hành tổng tuyển cử thống nhất đất nước", "C. Công nhận nền thống trị lâu dài của thực dân Pháp trên toàn cõi Đông Dương", "D. Đuổi quân Tưởng về nước, tránh cùng lúc đối phó nhiều kẻ thù và tranh thủ thời gian hòa bình chuẩn bị lực lượng kháng chiến lâu dài"], "answer": "D. Đuổi quân Tưởng về nước, tránh cùng lúc đối phó nhiều kẻ thù và tranh thủ thời gian hòa bình chuẩn bị lực lượng kháng chiến lâu dài", "letter": "D"}, {"id": 38, "cat": "c2", "q": "Trong xây dựng căn cứ địa và hậu phương kháng chiến chống Pháp (1946–1950), Đảng thực hiện chủ trương nào để làm thất bại âm mưu lấy chiến tranh nuôi chiến tranh của địch?", "options": ["A. Tạm dừng sản xuất nông nghiệp để tập trung toàn bộ cho quân sự", "B. \"Tiêu thổ kháng chiến\", rút các cơ quan Trung ương lên chiến khu Việt Bắc", "C. \"Vườn không nhà trống\" chỉ ở các đô thị miền Nam", "D. \"Chiến tranh chớp nhoáng\""], "answer": "B. \"Tiêu thổ kháng chiến\", rút các cơ quan Trung ương lên chiến khu Việt Bắc", "letter": "B"}, {"id": 39, "cat": "c2", "q": "Lực lượng vũ trang \"ba thứ quân\" được Đảng ta xây dựng trong cuộc kháng chiến chống Pháp gồm những lực lượng nào?", "options": ["A. Quân chính quy, thanh niên xung phong, dân công hỏa tuyến", "B. Bộ đội chủ lực, bộ đội địa phương, dân quân du kích", "C. Công an nhân dân, bộ đội biên phòng, tự vệ đô thị", "D. Lục quân, hải quân, không quân"], "answer": "B. Bộ đội chủ lực, bộ đội địa phương, dân quân du kích", "letter": "B"}, {"id": 40, "cat": "c2", "q": "Chiến thắng Biên giới Thu – Đông năm 1950 có ý nghĩa chiến lược quan trọng nào đối với cuộc kháng chiến chống Pháp?", "options": ["A. Khai thông đường liên lạc quốc tế và giành quyền chủ động chiến lược trên chiến trường chính Bắc Bộ", "B. Buộc thực dân Pháp phải ký Hiệp định Giơnevơ", "C. Đánh bại hoàn toàn kế hoạch \"đánh nhanh thắng nhanh\" của Pháp", "D. Đập tan hoàn toàn kế hoạch quân sự Nava"], "answer": "A. Khai thông đường liên lạc quốc tế và giành quyền chủ động chiến lược trên chiến trường chính Bắc Bộ", "letter": "A"}, {"id": 41, "cat": "c2", "q": "Từ cuối năm 1950 đến giữa năm 1953, quân và dân ta liên tiếp mở các chiến dịch nào để giữ vững và phát triển quyền chủ động chiến lược trên chiến trường chính Bắc Bộ?", "options": ["A. Trung Du, Đường 18, Hà Nam Ninh, Hòa Bình, Tây Bắc, Thượng Lào", "B. Việt Bắc, Biên giới, Đồng Khởi, Mậu Thân", "C. Tây Nguyên, Huế – Đà Nẵng, Phước Long, Hồ Chí Minh", "D. Ấp Bắc, Bình Giã, Vạn Tường, Plâyme"], "answer": "A. Trung Du, Đường 18, Hà Nam Ninh, Hòa Bình, Tây Bắc, Thượng Lào", "letter": "A"}, {"id": 42, "cat": "c2", "q": "Chiến dịch Điện Biên Phủ diễn ra trong khoảng thời gian nào và trải qua mấy đợt tiến công liên tục?", "options": ["A. Từ 19/12/1953 đến 1/5/1954, trải qua 2 đợt", "B. Từ 7/3 đến 21/7/1954, trải qua 3 đợt tiến công", "C. Từ 13/3 đến 7/5/1954, trải qua 3 đợt tiến công liên tục", "D. Từ 1/3 đến 19/5/1954, trải qua 4 đợt tiến công"], "answer": "C. Từ 13/3 đến 7/5/1954, trải qua 3 đợt tiến công liên tục", "letter": "C"}, {"id": 43, "cat": "c2", "q": "Hiệp định Genève về chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương được ký kết vào ngày tháng năm nào?", "options": ["A. Ngày 27/1/1954", "B. Ngày 7/5/1954", "C. Ngày 21/7/1954", "D. Ngày 8/5/1954"], "answer": "C. Ngày 21/7/1954", "letter": "C"}, {"id": 44, "cat": "c2", "q": "Theo nội dung Hiệp định Genève (21/7/1954), vĩ tuyến 17 được quy định với tính chất như thế nào?", "options": ["A. Là biên giới chính trị và lãnh thổ vĩnh viễn chia cắt hai quốc gia", "B. Là giới tuyến quân sự tạm thời để hai bên tập kết, chuyển quân; hoàn toàn không phải là biên giới chính trị hay lãnh thổ", "C. Là khu vực do quân đội Liên Hợp Quốc quản lý lâu dài", "D. Là ranh giới hành chính giữa miền Bắc và miền Trung"], "answer": "B. Là giới tuyến quân sự tạm thời để hai bên tập kết, chuyển quân; hoàn toàn không phải là biên giới chính trị hay lãnh thổ", "letter": "B"}, {"id": 45, "cat": "c1", "q": "Ý nghĩa quốc tế lớn lao của thắng lợi cuộc kháng chiến chống thực dân Pháp (1945–1954) là gì?", "options": ["A. Giáng đòn mạnh vào hệ thống thuộc địa của chủ nghĩa đế quốc, cổ vũ mạnh mẽ phong trào giải phóng dân tộc trên thế giới, nhất là ở châu Á, châu Phi", "B. Thành lập hệ thống xã hội chủ nghĩa trên toàn châu Á", "C. Chấm dứt hoàn toàn sự tồn tại của chủ nghĩa tư bản ở châu Âu", "D. Buộc Mỹ phải rút quân khỏi toàn bộ khu vực Đông Nam Á"], "answer": "A. Giáng đòn mạnh vào hệ thống thuộc địa của chủ nghĩa đế quốc, cổ vũ mạnh mẽ phong trào giải phóng dân tộc trên thế giới, nhất là ở châu Á, châu Phi", "letter": "A"}, {"id": 46, "cat": "c2", "q": "Trong các năm 1956–1957, cùng với khôi phục kinh tế, miền Bắc đã kiên quyết thực hiện nhiệm vụ gì trong lĩnh vực nông nghiệp?", "options": ["A. Thực hiện Khoán 100 và Khoán 10", "B. Hoàn thành cải cách ruộng đất đồng thời kiên quyết sửa chữa những sai lầm trong cải cách ruộng đất", "C. Xóa bỏ hoàn toàn sở hữu ruộng đất của nông dân", "D. Bắt đầu xuất khẩu gạo ra thị trường thế giới"], "answer": "B. Hoàn thành cải cách ruộng đất đồng thời kiên quyết sửa chữa những sai lầm trong cải cách ruộng đất", "letter": "B"}, {"id": 47, "cat": "c2", "q": "Phong trào Đồng khởi ở miền Nam (1959–1960) đạt đỉnh cao với cuộc Đồng khởi Bến Tre nổ ra vào ngày tháng năm nào?", "options": ["A. Ngày 1/1/1959", "B. Ngày 17/1/1960", "C. Ngày 20/12/1960", "D. Ngày 10/5/1959"], "answer": "B. Ngày 17/1/1960", "letter": "B"}, {"id": 48, "cat": "c2", "q": "Mặt trận Dân tộc Giải phóng miền Nam Việt Nam chính thức ra đời vào ngày tháng năm nào?", "options": ["A. Ngày 20/12/1960", "B. Ngày 2/9/1960", "C. Ngày 5/9/1960", "D. Ngày 17/1/1960"], "answer": "A. Ngày 20/12/1960", "letter": "A"}, {"id": 49, "cat": "c2", "q": "Hai chiến thắng tiêu biểu nào góp phần đánh bại chiến lược \"Chiến tranh đặc biệt\" (1961–1965) của đế quốc Mỹ ở miền Nam?", "options": ["A. Ấp Bắc (1963) và Bình Giã (1964–1965)", "B. Việt Bắc (1947) và Biên giới (1950)", "C. Phước Long (1975) và Buôn Ma Thuột (1975)", "D. Vạn Tường (1965) và Plâyme (1965)"], "answer": "A. Ấp Bắc (1963) và Bình Giã (1964–1965)", "letter": "A"}, {"id": 50, "cat": "c2", "q": "Hai tuyến chi viện chiến lược huyết mạch từ hậu phương miền Bắc vào tiền tuyến miền Nam được thành lập vào những năm nào?", "options": ["A. Đường Trường Sơn (Đường 559) năm 1955 và Đường vận tải biển (Đường 759) năm 1959", "B. Đường Trường Sơn (Đường 559) năm 1960 và Đường vận tải biển (Đường 759) năm 1965", "C. Đường Trường Sơn (Đường 559) năm 1959 và Đường vận tải biển (Đường 759) năm 1961", "D. Đường Trường Sơn (Đường 559) năm 1961 và Đường vận tải biển (Đường 759) năm 1963"], "answer": "C. Đường Trường Sơn (Đường 559) năm 1959 và Đường vận tải biển (Đường 759) năm 1961", "letter": "C"}, {"id": 51, "cat": "c2", "q": "Hai chiến thắng tiêu biểu nào của quân dân miền Nam trong giai đoạn đánh bại chiến lược \"Chiến tranh cục bộ\" (1965–1968) của Mỹ?", "options": ["A. Phước Long và Xuân Lộc", "B. Đông Khê và Thất Khê", "C. Vạn Tường và Plâyme", "D. Ấp Bắc và Bình Giã"], "answer": "C. Vạn Tường và Plâyme", "letter": "C"}, {"id": 52, "cat": "c2", "q": "Ở hậu phương miền Bắc trong thời kỳ chống Mỹ (1965–1975), phong trào thi đua \"Ba sẵn sàng\" và \"Ba đảm đang\" được phát động tương ứng trong lực lượng nào?", "options": ["A. \"Ba sẵn sàng\" trong trí thức, \"Ba đảm đang\" trong bộ đội", "B. \"Ba sẵn sàng\" trong thanh niên, \"Ba đảm đang\" trong phụ nữ", "C. \"Ba sẵn sàng\" trong phụ nữ, \"Ba đảm đang\" trong thanh niên", "D. \"Ba sẵn sàng\" trong công nhân, \"Ba đảm đang\" trong nông dân"], "answer": "B. \"Ba sẵn sàng\" trong thanh niên, \"Ba đảm đang\" trong phụ nữ", "letter": "B"}, {"id": 53, "cat": "c2", "q": "Các phong trào \"Tay cày tay súng\", \"Tay búa tay súng\" ở miền Bắc giai đoạn 1965–1975 thể hiện tinh thần gì?", "options": ["A. Đấu tranh nghị trường và báo chí công khai", "B. Vừa đẩy mạnh sản xuất, vừa sẵn sàng chiến đấu và chi viện tiền tuyến", "C. Tạm dừng sản xuất để toàn dân nhập ngũ", "D. Tập trung xây dựng công nghiệp nặng tại vùng giải phóng miền Nam"], "answer": "B. Vừa đẩy mạnh sản xuất, vừa sẵn sàng chiến đấu và chi viện tiền tuyến", "letter": "B"}, {"id": 54, "cat": "c2", "q": "Cuộc Tổng tiến công và nổi dậy Tết Mậu Thân 1968 đã tạo ra bước ngoặt nào trên mặt trận quân sự và ngoại giao?", "options": ["A. Giải phóng hoàn toàn miền Nam, chấm dứt chiến tranh ngay trong năm 1968", "B. Làm phá sản chiến lược \"Chiến tranh đơn phương\" của Mỹ – Diệm", "C. Giáng đòn quyết định vào ý chí xâm lược của Mỹ, buộc Mỹ xuống thang chiến tranh, chấm dứt ném bom miền Bắc, ngồi vào bàn đàm phán bốn bên tại Paris (1968) và chuyển sang \"Việt Nam hóa chiến tranh\"", "D. Buộc Pháp rút quân hoàn toàn khỏi Đông Dương"], "answer": "C. Giáng đòn quyết định vào ý chí xâm lược của Mỹ, buộc Mỹ xuống thang chiến tranh, chấm dứt ném bom miền Bắc, ngồi vào bàn đàm phán bốn bên tại Paris (1968) và chuyển sang \"Việt Nam hóa chiến tranh\"", "letter": "C"}, {"id": 55, "cat": "c2", "q": "Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam được thành lập vào thời gian nào?", "options": ["A. Tháng 1/1968", "B. Tháng 12/1960", "C. Tháng 1/1973", "D. Tháng 6/1969"], "answer": "D. Tháng 6/1969", "letter": "D"}, {"id": 56, "cat": "c2", "q": "Thắng lợi nào vào tháng 12/1972 đã đánh bại cuộc tập kích chiến lược bằng máy bay B-52 của Mỹ vào Hà Nội, Hải Phòng, buộc Mỹ phải ký Hiệp định Paris?", "options": ["A. Chiến thắng Vạn Tường", "B. Chiến dịch Đường 9 – Nam Lào", "C. Chiến thắng \"Điện Biên Phủ trên không\"", "D. Chiến dịch Tây Nguyên"], "answer": "C. Chiến thắng \"Điện Biên Phủ trên không\"", "letter": "C"}, {"id": 57, "cat": "c2", "q": "Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được ký kết vào ngày tháng năm nào?", "options": ["A. Ngày 27/1/1973", "B. Ngày 21/7/1972", "C. Ngày 30/4/1973", "D. Ngày 29/12/1972"], "answer": "A. Ngày 27/1/1973", "letter": "A"}, {"id": 58, "cat": "c2", "q": "Sau Hiệp định Paris (1/1973), Nghị quyết Hội nghị Trung ương 21 (7/1973) khẳng định con đường cách mạng miền Nam vẫn là gì?", "options": ["A. Con đường bạo lực cách mạng", "B. Đấu tranh hòa bình, nghị trường bằng mọi giá", "C. Chờ đợi sự can thiệp của Hội đồng Bảo an Liên Hợp Quốc", "D. Tạm gác đấu tranh vũ trang để khôi phục kinh tế"], "answer": "A. Con đường bạo lực cách mạng", "letter": "A"}, {"id": 59, "cat": "c2", "q": "Cuộc Tổng tiến công và nổi dậy mùa Xuân năm 1975 diễn ra qua ba chiến dịch lớn theo trình tự nào?", "options": ["A. Tây Nguyên → Huế – Đà Nẵng → Chiến dịch Hồ Chí Minh", "B. Đường 9 – Nam Lào → Huế – Đà Nẵng → Chiến dịch Hồ Chí Minh", "C. Phước Long → Tây Nguyên → Hồ Chí Minh", "D. Huế – Đà Nẵng → Tây Nguyên → Chiến dịch Hồ Chí Minh"], "answer": "A. Tây Nguyên → Huế – Đà Nẵng → Chiến dịch Hồ Chí Minh", "letter": "A"}, {"id": 60, "cat": "c2", "q": "Chiến dịch Tây Nguyên mở màn cho cuộc Tổng tiến công và nổi dậy mùa Xuân 1975 bắt đầu bằng trận đánh then chốt nào?", "options": ["A. Trận Phước Long (6/1/1975)", "B. Trận Pleiku (15/3/1975)", "C. Trận Buôn Ma Thuột (10/3/1975)", "D. Trận Xuân Lộc (9/4/1975)"], "answer": "C. Trận Buôn Ma Thuột (10/3/1975)", "letter": "C"}, {"id": 61, "cat": "c2", "q": "Chiến dịch Hồ Chí Minh lịch sử giải phóng hoàn toàn miền Nam diễn ra trong khoảng thời gian nào?", "options": ["A. Từ ngày 10/3 đến 30/4/1975", "B. Từ ngày 26/4 đến 30/4/1975", "C. Từ ngày 18/3 đến 30/4/1975", "D. Từ ngày 1/4 đến 30/4/1975"], "answer": "B. Từ ngày 26/4 đến 30/4/1975", "letter": "B"}, {"id": 62, "cat": "c2", "q": "Thắng lợi ngày 30/4/1975 đã kết thúc bao nhiêu năm kháng chiến chống Mỹ, cứu nước và bao nhiêu năm chiến tranh giải phóng dân tộc (tính từ 1945)?", "options": ["A. 20 năm chống Mỹ và 35 năm chiến tranh giải phóng dân tộc", "B. 15 năm chống Mỹ và 25 năm chiến tranh giải phóng dân tộc", "C. 21 năm chống Mỹ và 30 năm chiến tranh giải phóng dân tộc", "D. 30 năm chống Mỹ và 45 năm chiến tranh giải phóng dân tộc"], "answer": "C. 21 năm chống Mỹ và 30 năm chiến tranh giải phóng dân tộc", "letter": "C"}, {"id": 63, "cat": "c3", "q": "Cuộc Tổng tuyển cử bầu Quốc hội chung của cả nước Việt Nam thống nhất diễn ra vào ngày tháng năm nào?", "options": ["A. Ngày 21/11/1975", "B. Ngày 14/12/1976", "C. Ngày 2/7/1976", "D. Ngày 25/4/1976"], "answer": "D. Ngày 25/4/1976", "letter": "D"}, {"id": 64, "cat": "c3", "q": "Tại kỳ họp đầu tiên (7/1976), bên cạnh việc quyết định đặt tên nước là Cộng hòa xã hội chủ nghĩa Việt Nam, Quốc hội khóa VI còn quyết định đổi tên thành phố nào?", "options": ["A. Đổi tên Đà Nẵng thành thành phố trực thuộc Trung ương", "B. Đổi tên Hải Phòng thành thành phố cảng Trung ương", "C. Đổi tên Thăng Long thành Hà Nội", "D. Đổi tên Sài Gòn – Gia Định thành Thành phố Hồ Chí Minh"], "answer": "D. Đổi tên Sài Gòn – Gia Định thành Thành phố Hồ Chí Minh", "letter": "D"}, {"id": 65, "cat": "dh1_12", "q": "Đường lối công nghiệp hóa xã hội chủ nghĩa do Đại hội IV của Đảng (12/1976) đề ra có nội dung nào sau đây?", "options": ["A. Chỉ phát triển dịch vụ, du lịch và thương mại tư nhân", "B. Xóa bỏ toàn bộ công nghiệp nặng để tập trung 100% cho nông nghiệp", "C. Ưu tiên phát triển công nghiệp nặng một cách hợp lý, đồng thời ra sức phát triển nông nghiệp và công nghiệp nhẹ", "D. Chuyển ngay sang nền kinh tế thị trường mở cửa thu hút vốn FDI"], "answer": "C. Ưu tiên phát triển công nghiệp nặng một cách hợp lý, đồng thời ra sức phát triển nông nghiệp và công nghiệp nhẹ", "letter": "C"}, {"id": 66, "cat": "c3", "q": "Cuộc chiến tranh bảo vệ biên giới Tây Nam chống tập đoàn phản động Pôn Pốt diễn ra trong khoảng thời gian nào?", "options": ["A. Từ năm 1975 đến năm 1979", "B. Từ năm 1973 đến năm 1975", "C. Từ năm 1979 đến năm 1986", "D. Từ năm 1981 đến năm 1989"], "answer": "A. Từ năm 1975 đến năm 1979", "letter": "A"}, {"id": 67, "cat": "c3", "q": "Việt Nam thực hiện nghĩa vụ quốc tế cao cả, giúp lực lượng cách mạng và nhân dân Campuchia lật đổ chế độ diệt chủng Pôn Pốt vào thời gian nào?", "options": ["A. Tháng 4/1975", "B. Tháng 2/1982", "C. Tháng 12/1976", "D. Tháng 1/1979"], "answer": "D. Tháng 1/1979", "letter": "D"}, {"id": 68, "cat": "c1", "q": "Những nguyên nhân chính khiến nước ta lâm vào khủng hoảng kinh tế – xã hội nghiêm trọng vào cuối những năm 1970, đầu những năm 1980 là gì?", "options": ["A. Do nền kinh tế mở cửa quá sớm và cạnh tranh toàn cầu", "B. Do thiên tai liên tiếp và không có viện trợ từ bất kỳ nước nào", "C. Do thực hiện Khoán 10 quá nhanh trong nông nghiệp", "D. Do hậu quả nặng nề của chiến tranh, cơ chế quản lý tập trung quan liêu bao cấp kéo dài và sự bao vây, cấm vận của các thế lực thù địch"], "answer": "D. Do hậu quả nặng nề của chiến tranh, cơ chế quản lý tập trung quan liêu bao cấp kéo dài và sự bao vây, cấm vận của các thế lực thù địch", "letter": "D"}, {"id": 69, "cat": "c3", "q": "Chỉ thị số 100-CT/TW (1/1981) của Ban Bí thư — thường gọi là \"Khoán 100\" — quy định nội dung đột phá nào trong nông nghiệp?", "options": ["A. Giao quyền sử dụng đất vĩnh viễn cho doanh nghiệp nước ngoài", "B. Tự do hóa hoàn toàn giá nông sản theo thị trường thế giới", "C. Xóa bỏ hoàn toàn hợp tác xã nông nghiệp", "D. Khoán sản phẩm đến nhóm và người lao động trong hợp tác xã nông nghiệp"], "answer": "D. Khoán sản phẩm đến nhóm và người lao động trong hợp tác xã nông nghiệp", "letter": "D"}, {"id": 70, "cat": "c3", "q": "Các Quyết định 25-CP và 26-CP (1/1981) của Chính phủ nhằm giải quyết vấn đề gì trong lĩnh vực công nghiệp?", "options": ["A. Sáp nhập tất cả xí nghiệp quốc doanh vào hợp tác xã thủ công nghiệp", "B. Mở rộng quyền tự chủ sản xuất, kinh doanh cho các xí nghiệp quốc doanh", "C. Cấm các địa phương tự tìm nguồn nguyên liệu sản xuất", "D. Tư nhân hóa toàn bộ các nhà máy quốc doanh"], "answer": "B. Mở rộng quyền tự chủ sản xuất, kinh doanh cho các xí nghiệp quốc doanh", "letter": "B"}, {"id": 71, "cat": "c3", "q": "Hiện tượng nhiều địa phương, cơ sở sản xuất chủ động tìm cách tháo gỡ khó khăn vượt ra khỏi khuôn khổ cơ chế bao cấp cũ trong giai đoạn 1979–1985 được gọi là gì?", "options": ["A. \"Bao cấp mở rộng\"", "B. \"Kinh tế tri thức\"", "C. \"Xé rào\"", "D. \"Cải cách hành chính\""], "answer": "C. \"Xé rào\"", "letter": "C"}, {"id": 72, "cat": "c3", "q": "Hội nghị Trung ương 8 khóa V (6/1985) chủ trương xóa bỏ cơ chế tập trung quan liêu bao cấp thông qua bước đột phá nào?", "options": ["A. Thực hiện cải cách giá – lương – tiền", "B. Thành lập thị trường chứng khoán", "C. Ban hành Nghị quyết Khoán 10", "D. Ban hành Luật Đầu tư nước ngoài"], "answer": "A. Thực hiện cải cách giá – lương – tiền", "letter": "A"}, {"id": 73, "cat": "c3", "q": "Cuộc cải cách giá – lương – tiền (1985) có kết quả và ý nghĩa lịch sử như thế nào?", "options": ["A. Đưa Việt Nam trở thành nước xuất khẩu gạo ngay trong năm 1985", "B. Không thành công, gây ra những xáo trộn lớn về kinh tế – xã hội, nhưng để lại bài học sâu sắc thúc đẩy Đảng quyết tâm đổi mới toàn diện, triệt để hơn", "C. Thành công rực rỡ, đưa nước ta thoát ngay khỏi khủng hoảng năm 1985", "D. Chấm dứt hoàn toàn lạm phát xuống dưới 5%"], "answer": "B. Không thành công, gây ra những xáo trộn lớn về kinh tế – xã hội, nhưng để lại bài học sâu sắc thúc đẩy Đảng quyết tâm đổi mới toàn diện, triệt để hơn", "letter": "B"}, {"id": 74, "cat": "c3", "q": "Kết luận của Bộ Chính trị tháng 8/1986 tạo bước đột phá trực tiếp về mặt lý luận cho Đại hội VI khi tập trung làm rõ ba vấn đề lớn nào?", "options": ["A. Cơ cấu sản xuất, cải tạo xã hội chủ nghĩa và cơ chế quản lý kinh tế", "B. Quốc phòng, an ninh và đối ngoại đa phương", "C. Giáo dục, y tế và an sinh xã hội", "D. Văn hóa, khoa học công nghệ và bảo vệ môi trường"], "answer": "A. Cơ cấu sản xuất, cải tạo xã hội chủ nghĩa và cơ chế quản lý kinh tế", "letter": "A"}, {"id": 75, "cat": "dh1_12", "q": "Tinh thần cốt lõi mở đầu công cuộc Đổi mới tại Đại hội đại biểu toàn quốc lần thứ VI (12/1986) là gì?", "options": ["A. Giữ nguyên cơ chế bao cấp nhưng tăng cường kỷ luật hành chính", "B. Nhìn thẳng vào sự thật, đánh giá đúng sự thật, khởi xướng đường lối đổi mới toàn diện, trước hết là đổi mới tư duy kinh tế", "C. Thay đổi mục tiêu chủ nghĩa xã hội sang kinh tế tư bản chủ nghĩa", "D. Chỉ đổi mới chính trị mà không thay đổi cơ chế quản lý kinh tế"], "answer": "B. Nhìn thẳng vào sự thật, đánh giá đúng sự thật, khởi xướng đường lối đổi mới toàn diện, trước hết là đổi mới tư duy kinh tế", "letter": "B"}, {"id": 76, "cat": "c3", "q": "Nghị quyết số 10-NQ/TW (4/1988) của Bộ Chính trị — còn gọi là \"Khoán 10\" — xác lập vai trò nào trong nông nghiệp?", "options": ["A. Hợp tác xã giữ toàn quyền phân phối theo công điểm", "B. Nhà nước trực tiếp quản lý từng thửa ruộng của nông dân", "C. Hộ nông dân là đơn vị kinh tế tự chủ, được giao quyền sử dụng đất lâu dài", "D. Chỉ cho phép trang trại quốc doanh sản xuất lương thực"], "answer": "C. Hộ nông dân là đơn vị kinh tế tự chủ, được giao quyền sử dụng đất lâu dài", "letter": "C"}, {"id": 77, "cat": "c3", "q": "Nhờ \"cú hích\" từ Nghị quyết 10 (Khoán 10, 4/1988), Việt Nam đã chuyển từ nước thiếu lương thực trở thành nước xuất khẩu gạo từ năm nào?", "options": ["A. Từ năm 1995", "B. Từ năm 1989", "C. Từ năm 1986", "D. Từ năm 1988"], "answer": "B. Từ năm 1989", "letter": "B"}, {"id": 78, "cat": "dh1_12", "q": "Ngoài Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên CNXH (Cương lĩnh 1991), Đại hội VII (6/1991) còn thông qua văn kiện chiến lược nào?", "options": ["A. Chiến lược phát triển kinh tế biển đến năm 2030", "B. Chiến lược phát triển kinh tế – xã hội 2011–2020", "C. Chiến lược ổn định và phát triển kinh tế – xã hội đến năm 2000", "D. Chiến lược bảo vệ Tổ quốc trong tình hình mới"], "answer": "C. Chiến lược ổn định và phát triển kinh tế – xã hội đến năm 2000", "letter": "C"}, {"id": 79, "cat": "c3", "q": "Kết quả nổi bật nhất sau 10 năm đầu thực hiện công cuộc Đổi mới tính đến năm 1996 là gì?", "options": ["A. Đưa đất nước ra khỏi khủng hoảng kinh tế – xã hội kéo dài, tạo tiền đề chuyển sang thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa", "B. Đạt quy mô GDP trên 500 tỷ USD", "C. Đưa Việt Nam trở thành nước công nghiệp hiện đại, thu nhập cao", "D. Chính thức gia nhập Tổ chức Thương mại Thế giới (WTO)"], "answer": "A. Đưa đất nước ra khỏi khủng hoảng kinh tế – xã hội kéo dài, tạo tiền đề chuyển sang thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa", "letter": "A"}, {"id": 80, "cat": "dh1_12", "q": "Điểm chuyển biến trong đường lối đối ngoại tại Đại hội IX (4/2001) so với Đại hội VII (6/1991) là gì?", "options": ["A. Chuyển từ \"đa phương hóa\" sang \"song phương hóa\"", "B. Chuyển từ \"muốn là bạn\" sang \"sẵn sàng là bạn, là đối tác tin cậy\" của các nước trong cộng đồng quốc tế", "C. Từ \"chỉ quan hệ với các nước XHCN\" sang \"mở cửa với ASEAN\"", "D. Chuyển từ \"hội nhập kinh tế\" sang \"tự cung tự cấp\""], "answer": "B. Chuyển từ \"muốn là bạn\" sang \"sẵn sàng là bạn, là đối tác tin cậy\" của các nước trong cộng đồng quốc tế", "letter": "B"}, {"id": 81, "cat": "c3", "q": "Việt Nam ký Nghị định thư gia nhập WTO vào ngày nào và chính thức có hiệu lực thành viên đầy đủ thứ 150 vào ngày nào?", "options": ["A. Ký ngày 11/11/2007, hiệu lực đầy đủ ngày 1/1/2008", "B. Ký ngày 7/11/2006, hiệu lực đầy đủ ngày 11/1/2007", "C. Ký ngày 1/1/2006, hiệu lực ngày 11/11/2006", "D. Ký ngày 25/4/2006, hiệu lực đầy đủ ngày 1/1/2007"], "answer": "B. Ký ngày 7/11/2006, hiệu lực đầy đủ ngày 11/1/2007", "letter": "B"}, {"id": 82, "cat": "dh1_12", "q": "Đại hội XII (1/2016) của Đảng đã đẩy mạnh phong trào lớn nào gắn với công tác xây dựng, chỉnh đốn Đảng?", "options": ["A. Phong trào học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh", "B. Phong trào \"Khoán 100\"", "C. Phong trào \"Bình dân học vụ\"", "D. Phong trào \"Ba sẵn sàng\" và \"Ba đảm đang\""], "answer": "A. Phong trào học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh", "letter": "A"}, {"id": 83, "cat": "c3", "q": "Quan điểm nhất quán của Đảng trong công tác đấu tranh phòng, chống tham nhũng, tiêu cực, lãng phí là gì?", "options": ["A. Xử lý nội bộ, ưu tiên nhắc nhở đối với cán bộ cấp cao", "B. Tạm hoãn xử lý để ưu tiên tăng trưởng kinh tế", "C. Chỉ xử lý khi gây thiệt hại trên mức quy định", "D. \"Không có vùng cấm, không có ngoại lệ\""], "answer": "D. \"Không có vùng cấm, không có ngoại lệ\"", "letter": "D"}, {"id": 84, "cat": "c3", "q": "Theo tài liệu Chương 3, hạn chế nổi bật còn tồn tại bên cạnh những thành tựu to lớn của công cuộc Đổi mới là gì?", "options": ["A. Quan hệ đối ngoại bị cô lập hoàn toàn với các nước lớn", "B. Vẫn còn một bộ phận cán bộ, đảng viên suy thoái về tư tưởng chính trị, đạo đức, lối sống; tham nhũng, lãng phí, tiêu cực chưa bị ngăn chặn triệt để; nguy cơ tụt hậu kinh tế vẫn hiện hữu", "C. Chưa thiết lập được mô hình kinh tế nhiều thành phần", "D. Việt Nam vẫn chưa thoát khỏi tình trạng thiếu lương thực"], "answer": "B. Vẫn còn một bộ phận cán bộ, đảng viên suy thoái về tư tưởng chính trị, đạo đức, lối sống; tham nhũng, lãng phí, tiêu cực chưa bị ngăn chặn triệt để; nguy cơ tụt hậu kinh tế vẫn hiện hữu", "letter": "B"}, {"id": 85, "cat": "c3", "q": "Theo bài học kinh nghiệm của công cuộc Đổi mới trong tài liệu Chương 3, mối quan hệ giữa đổi mới kinh tế và đổi mới chính trị được xử lý như thế nào?", "options": ["A. Đổi mới chính trị trước rồi mới đổi mới kinh tế", "B. Chỉ đổi mới kinh tế, tuyệt đối không đổi mới chính trị", "C. Đổi mới kinh tế đi trước một bước gắn với đổi mới từng bước về chính trị", "D. Tiến hành xóa bỏ toàn bộ hệ thống chính trị cũ trước khi cải cách kinh tế"], "answer": "C. Đổi mới kinh tế đi trước một bước gắn với đổi mới từng bước về chính trị", "letter": "C"}, {"id": 86, "cat": "dh13", "q": "Đại hội đại biểu toàn quốc lần thứ XIII của Đảng diễn ra trong thời gian nào và tại đâu?", "options": ["A. Từ ngày 20–28/1/2016 tại Hà Nội", "B. Từ ngày 19–23/1/2026 tại Hà Nội", "C. Từ ngày 12–19/1/2011 tại Hà Nội", "D. Từ ngày 25/1–1/2/2021 tại Hà Nội"], "answer": "D. Từ ngày 25/1–1/2/2021 tại Hà Nội", "letter": "D"}, {"id": 87, "cat": "dh13", "q": "Đại hội XIII của Đảng có bao nhiêu đại biểu tham dự, đại diện cho hơn 5 triệu đảng viên?", "options": ["A. 1.510 đại biểu", "B. 1.600 đại biểu", "C. 1.587 đại biểu", "D. 1.586 đại biểu"], "answer": "C. 1.587 đại biểu", "letter": "C"}, {"id": 88, "cat": "dh13", "q": "Cơ cấu nhân sự do Đại hội XIII của Đảng bầu ra gồm bao nhiêu Ủy viên Ban Chấp hành Trung ương và Ủy viên Bộ Chính trị?", "options": ["A. 220 Ủy viên BCH Trung ương (200 chính thức, 20 dự khuyết) và 18 Ủy viên Bộ Chính trị", "B. 200 Ủy viên BCH Trung ương (180 chính thức, 20 dự khuyết) và 19 Ủy viên Bộ Chính trị", "C. 180 Ủy viên BCH Trung ương (160 chính thức, 20 dự khuyết) và 16 Ủy viên Bộ Chính trị", "D. 200 Ủy viên BCH Trung ương (180 chính thức, 20 dự khuyết) và 18 Ủy viên Bộ Chính trị"], "answer": "D. 200 Ủy viên BCH Trung ương (180 chính thức, 20 dự khuyết) và 18 Ủy viên Bộ Chính trị", "letter": "D"}, {"id": 89, "cat": "dh1_12", "q": "Ai được bầu giữ chức Tổng Bí thư tại Đại hội đại biểu toàn quốc lần thứ XIII của Đảng (2021)?", "options": ["A. Đồng chí Phạm Minh Chính", "B. Đồng chí Nguyễn Xuân Phúc", "C. Đồng chí Tô Lâm", "D. Đồng chí Nguyễn Phú Trọng"], "answer": "D. Đồng chí Nguyễn Phú Trọng", "letter": "D"}, {"id": 90, "cat": "dh13", "q": "Phương châm của Đại hội đại biểu toàn quốc lần thứ XIII của Đảng là gì?", "options": ["A. \"Đoàn kết – Dân chủ – Kỷ cương – Sáng tạo – Phát triển\"", "B. \"Đoàn kết – Kỷ cương – Hội nhập – Phát triển\"", "C. \"Đoàn kết – Dân chủ – Kỷ cương – Đột phá – Phát triển\"", "D. \"Đoàn kết – Dân chủ – Kỷ cương – Đổi mới\""], "answer": "A. \"Đoàn kết – Dân chủ – Kỷ cương – Sáng tạo – Phát triển\"", "letter": "A"}, {"id": 91, "cat": "dh13", "q": "Bối cảnh thế giới nổi bật tác động mạnh mẽ khi diễn ra Đại hội XIII (1/2021) là gì?", "options": ["A. Nền kinh tế toàn cầu tăng trưởng ổn định không có dịch bệnh", "B. Kinh tế thế giới suy thoái nghiêm trọng do đại dịch Covid-19, cạnh tranh nước lớn gia tăng và Cách mạng công nghiệp lần thứ tư", "C. Chiến tranh lạnh mới vừa kết thúc và Liên Xô vừa tan rã", "D. Khủng hoảng tài chính châu Á 1997 lan rộng"], "answer": "B. Kinh tế thế giới suy thoái nghiêm trọng do đại dịch Covid-19, cạnh tranh nước lớn gia tăng và Cách mạng công nghiệp lần thứ tư", "letter": "B"}, {"id": 92, "cat": "dh13", "q": "\"Bốn nguy cơ\" mà Đảng đã chỉ ra và nhận định vẫn còn tồn tại tại Đại hội XIII là gì?", "options": ["A. Thiên tai, dịch bệnh, già hóa dân số, biến đổi khí hậu", "B. Tụt hậu kinh tế, chệch hướng XHCN, tham nhũng – quan liêu, \"diễn biến hòa bình\"", "C. Lạm phát cao, thiếu lương thực, thất nghiệp, nợ công", "D. Xung đột biên giới, cấm vận kinh tế, chia rẽ khu vực, thiếu nhân lực"], "answer": "B. Tụt hậu kinh tế, chệch hướng XHCN, tham nhũng – quan liêu, \"diễn biến hòa bình\"", "letter": "B"}, {"id": 93, "cat": "dh13", "q": "Chủ đề của Đại hội XIII xoay quanh mấy trụ cột lớn?", "options": ["A. 3 trụ cột", "B. 5 trụ cột", "C. 4 trụ cột", "D. 6 trụ cột"], "answer": "B. 5 trụ cột", "letter": "B"}, {"id": 94, "cat": "dh13", "q": "Theo báo cáo tại Đại hội XIII, tăng trưởng GDP bình quân giai đoạn nhiệm kỳ XII (2016–2020) và riêng năm 2020 đạt mức nào?", "options": ["A. Bình quân ~6,2%/năm; riêng năm 2020 đạt 8,02%", "B. Bình quân ~7%/năm; riêng năm 2020 đạt 5,0%", "C. Bình quân ~5%/năm; riêng năm 2020 tăng trưởng âm 1,5%", "D. Bình quân ~6%/năm; riêng năm 2020 đạt 2,91% — thuộc nhóm cao nhất thế giới giữa đại dịch"], "answer": "D. Bình quân ~6%/năm; riêng năm 2020 đạt 2,91% — thuộc nhóm cao nhất thế giới giữa đại dịch", "letter": "D"}, {"id": 95, "cat": "dh13", "q": "Theo thông tin Đại hội XIII, cuối nhiệm kỳ XII (2020), quy mô GDP và GDP bình quân đầu người của Việt Nam đạt bao nhiêu?", "options": ["A. GDP đạt 271,2 tỷ USD, bình quân đầu người 2.779 USD", "B. GDP đạt 400 tỷ USD, bình quân đầu người 4.100 USD", "C. GDP đạt 514 tỷ USD, bình quân đầu người 5.026 USD", "D. GDP đạt 150 tỷ USD, bình quân đầu người 1.800 USD"], "answer": "A. GDP đạt 271,2 tỷ USD, bình quân đầu người 2.779 USD", "letter": "A"}, {"id": 96, "cat": "dh13", "q": "Tốc độ tăng năng suất lao động của Việt Nam trong nhiệm kỳ XII (2016–2020) tăng từ mức nào (giai đoạn 2011–2015) lên mức nào?", "options": ["A. Từ 5,0%/năm lên 7,5%/năm", "B. Từ 3,0%/năm lên 4,5%/năm", "C. Từ 4,3%/năm lên 5,9%/năm", "D. Từ 2,9%/năm lên 6,2%/năm"], "answer": "C. Từ 4,3%/năm lên 5,9%/năm", "letter": "C"}, {"id": 97, "cat": "dh13", "q": "Trong kết quả nổi bật nhiệm kỳ Đại hội XII (2016–2020), chương trình xây dựng nông thôn mới đạt thành tích gì?", "options": ["A. Hoàn thành sớm gần 2 năm so với kế hoạch, làm thay đổi rõ nét bộ mặt nông thôn", "B. Hoàn thành chậm 1 năm do ảnh hưởng của dịch bệnh", "C. Mới chỉ triển khai thí điểm ở đồng bằng sông Hồng", "D. Hoàn thành đúng thời hạn 100% ở các tỉnh miền núi"], "answer": "A. Hoàn thành sớm gần 2 năm so với kế hoạch, làm thay đổi rõ nét bộ mặt nông thôn", "letter": "A"}, {"id": 98, "cat": "dh13", "q": "Theo thống kê tổng kết nhiệm kỳ XII tại Đại hội XIII, tỉ lệ hộ nghèo đa chiều và tỉ lệ bao phủ bảo hiểm y tế của nước ta đạt mức nào?", "options": ["A. Hộ nghèo đa chiều giảm còn dưới 5%; BHYT bao phủ trên 80% dân số", "B. Hộ nghèo đa chiều giảm còn dưới 1%; BHYT bao phủ 100% dân số", "C. Hộ nghèo đa chiều giảm còn 1,3%; BHYT bao phủ 95,2% dân số", "D. Hộ nghèo đa chiều giảm còn dưới 3%; BHYT bao phủ trên 90% dân số"], "answer": "D. Hộ nghèo đa chiều giảm còn dưới 3%; BHYT bao phủ trên 90% dân số", "letter": "D"}, {"id": 99, "cat": "dh13", "q": "Thành tựu nổi bật về giáo dục được nêu trong kết quả nhiệm kỳ XII tại Đại hội XIII là gì?", "options": ["A. Phổ cập giáo dục mầm non cho trẻ 5 tuổi", "B. Đưa 100% trường học chuyển sang học trực tuyến", "C. Miễn học phí toàn bộ bậc đại học công lập", "D. Phổ cập giáo dục trung học phổ thông toàn quốc"], "answer": "A. Phổ cập giáo dục mầm non cho trẻ 5 tuổi", "letter": "A"}, {"id": 100, "cat": "dh13", "q": "Mốc mục tiêu cụ thể đến năm 2025 (kỷ niệm 50 năm giải phóng hoàn toàn miền Nam, thống nhất đất nước) do Đại hội XIII đề ra là gì?", "options": ["A. Trở thành nước phát triển, thu nhập cao", "B. Là nước đang phát triển, có công nghiệp hiện đại, thu nhập trung bình cao", "C. Cơ bản hoàn thành giai đoạn tiền đề công nghiệp hóa", "D. Là nước đang phát triển, có công nghiệp theo hướng hiện đại, vượt qua mức thu nhập trung bình thấp"], "answer": "D. Là nước đang phát triển, có công nghiệp theo hướng hiện đại, vượt qua mức thu nhập trung bình thấp", "letter": "D"}, {"id": 101, "cat": "dh13", "q": "Mốc mục tiêu đến năm 2030 (kỷ niệm 100 năm thành lập Đảng) được Đại hội XIII xác định là gì?", "options": ["A. Trở thành nước phát triển, thu nhập cao", "B. Là nước đang phát triển, có công nghiệp hiện đại, thu nhập trung bình cao", "C. Là nước đang phát triển, vượt qua mức thu nhập trung bình thấp", "D. Cơ bản xóa bỏ hoàn toàn nông nghiệp truyền thống"], "answer": "B. Là nước đang phát triển, có công nghiệp hiện đại, thu nhập trung bình cao", "letter": "B"}, {"id": 102, "cat": "dh13", "q": "Mốc mục tiêu đến năm 2045 (kỷ niệm 100 năm thành lập nước) được Đại hội XIII xác định là gì?", "options": ["A. Đạt thu nhập trung bình cao trong khu vực Đông Nam Á", "B. Trở thành nước phát triển, thu nhập cao", "C. Vượt qua mức thu nhập trung bình thấp", "D. Nước đang phát triển có công nghiệp hiện đại"], "answer": "B. Trở thành nước phát triển, thu nhập cao", "letter": "B"}, {"id": 103, "cat": "dh13", "q": "Ba đột phá chiến lược được Đại hội XIII của Đảng xác định gồm những lĩnh vực nào?", "options": ["A. Nông nghiệp, công nghiệp nặng và thương mại quốc tế", "B. Giáo dục phổ thông, y tế dự phòng và du lịch sinh thái", "C. Cải cách tiền lương, xuất khẩu gạo và mở rộng khu công nghiệp", "D. Thể chế; Nguồn nhân lực & KHCN, đổi mới sáng tạo; Hạ tầng đồng bộ (ưu tiên giao thông, năng lượng, hạ tầng số)"], "answer": "D. Thể chế; Nguồn nhân lực & KHCN, đổi mới sáng tạo; Hạ tầng đồng bộ (ưu tiên giao thông, năng lượng, hạ tầng số)", "letter": "D"}, {"id": 104, "cat": "dh13", "q": "Trong đột phá về \"Hạ tầng đồng bộ\" của Đại hội XIII, những lĩnh vực nào được ưu tiên?", "options": ["A. Nhà ở thương mại và bất động sản nghỉ dưỡng", "B. Giao thông, năng lượng và hạ tầng số", "C. Du lịch, giải trí và bán lẻ", "D. Thủy lợi, lâm nghiệp và ngư nghiệp"], "answer": "B. Giao thông, năng lượng và hạ tầng số", "letter": "B"}, {"id": 105, "cat": "dh13", "q": "Đại hội XIII của Đảng đề ra bao nhiêu nhiệm vụ trọng tâm cho nhiệm kỳ mới?", "options": ["A. 3 nhiệm vụ trọng tâm", "B. 4 nhiệm vụ trọng tâm", "C. 5 nhiệm vụ trọng tâm", "D. 6 nhiệm vụ trọng tâm"], "answer": "D. 6 nhiệm vụ trọng tâm", "letter": "D"}, {"id": 106, "cat": "dh13", "q": "Nội dung \"Kiểm soát dịch bệnh, phục hồi và phát triển kinh tế – xã hội; đổi mới mô hình tăng trưởng; đẩy mạnh chuyển đổi số quốc gia\" thuộc phần nào của Đại hội XIII?", "options": ["A. Sáu nhiệm vụ trọng tâm nhiệm kỳ Đại hội XIII", "B. Kết quả nhiệm kỳ XII", "C. Bốn nguy cơ còn tồn tại", "D. Ba mốc mục tiêu chiến lược"], "answer": "A. Sáu nhiệm vụ trọng tâm nhiệm kỳ Đại hội XIII", "letter": "A"}, {"id": 107, "cat": "dh14", "q": "Đại hội đại biểu toàn quốc lần thứ XIV của Đảng diễn ra vào thời gian nào và tại đâu?", "options": ["A. Từ ngày 25/1–1/2/2021 tại Hà Nội", "B. Từ ngày 10–18/1/2026 tại TP. Hồ Chí Minh", "C. Từ ngày 19–23/1/2026 tại Hà Nội", "D. Từ ngày 1–5/2/2026 tại Hà Nội"], "answer": "C. Từ ngày 19–23/1/2026 tại Hà Nội", "letter": "C"}, {"id": 108, "cat": "dh14", "q": "Đại hội XIV của Đảng có bao nhiêu đại biểu tham dự và bầu ra bao nhiêu Ủy viên Bộ Chính trị?", "options": ["A. 1.587 đại biểu và 18 Ủy viên Bộ Chính trị", "B. 1.586 đại biểu và 19 Ủy viên Bộ Chính trị", "C. 1.586 đại biểu và 18 Ủy viên Bộ Chính trị", "D. 1.600 đại biểu và 20 Ủy viên Bộ Chính trị"], "answer": "B. 1.586 đại biểu và 19 Ủy viên Bộ Chính trị", "letter": "B"}, {"id": 109, "cat": "dh14", "q": "Ai được bầu giữ chức Tổng Bí thư Ban Chấp hành Trung ương Đảng khóa XIV (1/2026)?", "options": ["A. Đồng chí Trần Thanh Mẫn", "B. Đồng chí Tô Lâm", "C. Đồng chí Nguyễn Phú Trọng", "D. Đồng chí Phạm Minh Chính"], "answer": "B. Đồng chí Tô Lâm", "letter": "B"}, {"id": 110, "cat": "dh14", "q": "Số lượng Ủy viên Ban Chấp hành Trung ương khóa XIV được bầu tại Đại hội XIV là bao nhiêu?", "options": ["A. 200 Ủy viên (175 chính thức, 25 dự khuyết)", "B. 210 Ủy viên (190 chính thức, 20 dự khuyết)", "C. 180 Ủy viên (160 chính thức, 20 dự khuyết)", "D. 200 Ủy viên (180 chính thức, 20 dự khuyết)"], "answer": "D. 200 Ủy viên (180 chính thức, 20 dự khuyết)", "letter": "D"}, {"id": 111, "cat": "dh1_12", "q": "Phương châm của Đại hội đại biểu toàn quốc lần thứ XIV của Đảng là gì?", "options": ["A. \"Đoàn kết – Dân chủ – Kỷ cương – Đổi mới\"", "B. \"Đoàn kết – Dân chủ – Kỷ cương – Sáng tạo – Phát triển\"", "C. \"Đoàn kết – Dân chủ – Kỷ cương – Đột phá – Phát triển\"", "D. \"Đoàn kết – Tự cường – Đột phá – Hội nhập – Phát triển\""], "answer": "C. \"Đoàn kết – Dân chủ – Kỷ cương – Đột phá – Phát triển\"", "letter": "C"}, {"id": 112, "cat": "dh14", "q": "So với phương châm Đại hội XIII, phương châm Đại hội XIV thay từ nào để nhấn mạnh yêu cầu hành động mạnh mẽ trong kỷ nguyên mới?", "options": ["A. Thay \"Dân chủ\" bằng \"Tự chủ\"", "B. Thay \"Phát triển\" bằng \"Thịnh vượng\"", "C. Thay \"Kỷ cương\" bằng \"Hội nhập\"", "D. Thay \"Sáng tạo\" bằng \"Đột phá\""], "answer": "D. Thay \"Sáng tạo\" bằng \"Đột phá\"", "letter": "D"}, {"id": 113, "cat": "dh14", "q": "Đại hội XIV được xác định là đại hội khởi đầu cho kỷ nguyên nào của dân tộc Việt Nam?", "options": ["A. Kỷ nguyên phát triển mới của dân tộc — kỷ nguyên vươn mình", "B. Kỷ nguyên đổi mới và mở cửa", "C. Kỷ nguyên kinh tế nông nghiệp hiện đại", "D. Kỷ nguyên độc lập, thống nhất"], "answer": "A. Kỷ nguyên phát triển mới của dân tộc — kỷ nguyên vươn mình", "letter": "A"}, {"id": 114, "cat": "dh14", "q": "Tại Đại hội XIV (sau 40 năm đổi mới), Đảng nhận định nguy cơ bao trùm đối với đất nước ta hiện nay là gì?", "options": ["A. Nguy cơ tụt hậu, nhất là về công nghệ, và rơi vào bẫy thu nhập trung bình", "B. Nguy cơ thiếu lương thực và đói nghèo lan rộng", "C. Nguy cơ chiến tranh thế giới trực tiếp tại Đông Nam Á", "D. Nguy cơ chưa được gia nhập các tổ chức kinh tế quốc tế"], "answer": "A. Nguy cơ tụt hậu, nhất là về công nghệ, và rơi vào bẫy thu nhập trung bình", "letter": "A"}, {"id": 115, "cat": "dh14", "q": "Trong bối cảnh thế giới tại Đại hội XIV, những công nghệ mũi nhọn nào của Cách mạng công nghiệp lần thứ tư được nhấn mạnh tạo biến đổi mang tính thời đại?", "options": ["A. Vận tải đường sắt hơi nước và điện báo", "B. Cơ khí hóa, điện khí hóa và tự động hóa dây chuyền cũ", "C. Trí tuệ nhân tạo, công nghệ số, công nghệ lượng tử", "D. Năng lượng than đá và luyện kim truyền thống"], "answer": "C. Trí tuệ nhân tạo, công nghệ số, công nghệ lượng tử", "letter": "C"}, {"id": 116, "cat": "dh14", "q": "Theo tổng kết nhiệm kỳ Đại hội XIII (2021–2026) tại Đại hội XIV, tăng trưởng GDP bình quân giai đoạn 2021–2025 và riêng năm 2025 đạt bao nhiêu?", "options": ["A. Bình quân ~5,5%/năm; riêng năm 2025 đạt 6,8%", "B. Bình quân ~6,2%/năm; riêng năm 2025 đạt 8,02%", "C. Bình quân ~8%/năm; riêng năm 2025 đạt 10,5%", "D. Bình quân ~6%/năm; riêng năm 2025 đạt 2,91%"], "answer": "B. Bình quân ~6,2%/năm; riêng năm 2025 đạt 8,02%", "letter": "B"}, {"id": 117, "cat": "dh14", "q": "Theo thông tin Đại hội XIV, quy mô GDP của Việt Nam cuối nhiệm kỳ XIII đạt mức nào và xếp thứ mấy trên thế giới?", "options": ["A. Đạt 350 tỷ USD, xếp thứ 40 thế giới", "B. Đạt 271,2 tỷ USD, xếp thứ 45 thế giới", "C. Vượt 800 tỷ USD, xếp thứ 20 thế giới", "D. Vượt 514 tỷ USD (gấp 1,48 lần năm 2020), xếp thứ 32 thế giới"], "answer": "D. Vượt 514 tỷ USD (gấp 1,48 lần năm 2020), xếp thứ 32 thế giới", "letter": "D"}, {"id": 118, "cat": "dh14", "q": "Theo báo cáo tại Đại hội XIV, GDP bình quân đầu người của Việt Nam cuối nhiệm kỳ XIII đạt bao nhiêu và đánh dấu cột mốc gì?", "options": ["A. 8.500 USD — gia nhập nhóm thu nhập cao", "B. 2.779 USD — vượt mức thu nhập thấp", "C. 5.026 USD — gia nhập nhóm thu nhập trung bình cao", "D. 3.800 USD — mức thu nhập trung bình thấp"], "answer": "C. 5.026 USD — gia nhập nhóm thu nhập trung bình cao", "letter": "C"}, {"id": 119, "cat": "dh14", "q": "Trong nhiệm kỳ Đại hội XIII (2021–2026), tỉ lệ hộ nghèo đa chiều và tỉ lệ bao phủ bảo hiểm y tế đạt kết quả nổi bật nào?", "options": ["A. Hộ nghèo đa chiều giảm còn 0%; BHYT đạt 100%", "B. Hộ nghèo đa chiều giảm từ 10% xuống 5%; BHYT đạt 85%", "C. Hộ nghèo đa chiều giảm từ 4,2% (2022) xuống 1,3% (2025); hoàn thành xóa nhà tạm, nhà dột nát cả nước; BHYT tăng lên 95,2% dân số", "D. Hộ nghèo đa chiều giảm dưới 3%; BHYT đạt trên 90%"], "answer": "C. Hộ nghèo đa chiều giảm từ 4,2% (2022) xuống 1,3% (2025); hoàn thành xóa nhà tạm, nhà dột nát cả nước; BHYT tăng lên 95,2% dân số", "letter": "C"}, {"id": 120, "cat": "dh14", "q": "Theo kết quả nhiệm kỳ XIII được nêu tại Đại hội XIV, Chỉ số phát triển con người (HDI) và Chỉ số hạnh phúc của Việt Nam biến chuyển như thế nào?", "options": ["A. HDI tăng 14 bậc đạt 0,766 điểm; chỉ số hạnh phúc tăng 33 bậc, xếp thứ 46/143 quốc gia (2025)", "B. HDI giữ nguyên ở 0,680; chỉ số hạnh phúc tăng 12 bậc", "C. HDI tăng 20 bậc đạt 0,850; chỉ số hạnh phúc xếp thứ 15/143 quốc gia", "D. HDI tăng 5 bậc đạt 0,700; chỉ số hạnh phúc tăng 10 bậc xếp thứ 70/143"], "answer": "A. HDI tăng 14 bậc đạt 0,766 điểm; chỉ số hạnh phúc tăng 33 bậc, xếp thứ 46/143 quốc gia (2025)", "letter": "A"}, {"id": 121, "cat": "dh14", "q": "Về phòng chống đại dịch Covid-19 trong nhiệm kỳ XIII, Đại hội XIV đánh giá Việt Nam đã thực hiện thành công điều gì?", "options": ["A. Ngoại giao vắc-xin, tiêm chủng miễn phí toàn quốc, thực hiện thành công \"mục tiêu kép\" — vừa chống dịch vừa phục hồi kinh tế", "B. Tự sản xuất 100% vắc-xin xuất khẩu ra toàn cầu từ năm 2021", "C. Chỉ tập trung chống dịch và tạm dừng toàn bộ hoạt động kinh tế", "D. Đóng cửa hoàn toàn biên giới trong suốt 5 năm"], "answer": "A. Ngoại giao vắc-xin, tiêm chủng miễn phí toàn quốc, thực hiện thành công \"mục tiêu kép\" — vừa chống dịch vừa phục hồi kinh tế", "letter": "A"}, {"id": 122, "cat": "dh14", "q": "Đại hội XIV đề ra mục tiêu tốc độ tăng trưởng GDP bình quân giai đoạn 2026–2030 và GDP bình quân đầu người đến năm 2030 đạt mức nào?", "options": ["A. GDP tăng 12%/năm; bình quân đầu người khoảng 12.000 USD", "B. GDP tăng 6–7%/năm; bình quân đầu người khoảng 6.000 USD", "C. GDP tăng từ 10%/năm trở lên; bình quân đầu người đạt khoảng 8.500 USD", "D. GDP tăng 8%/năm; bình quân đầu người khoảng 7.000 USD"], "answer": "C. GDP tăng từ 10%/năm trở lên; bình quân đầu người đạt khoảng 8.500 USD", "letter": "C"}, {"id": 123, "cat": "dh14", "q": "Hai mốc mục tiêu chiến lược 100 năm mà Đại hội XIV hướng tới thực hiện thành công là gì?", "options": ["A. 100 năm thành lập Đảng (1930–2030) và 100 năm thành lập nước (1945–2045)", "B. 100 năm thống nhất đất nước (1975–2075) và 100 năm Đổi mới (1986–2086)", "C. 100 năm ngày sinh Chủ tịch Hồ Chí Minh và 100 năm Chiến thắng Điện Biên Phủ", "D. 100 năm gia nhập ASEAN và 100 năm gia nhập WTO"], "answer": "A. 100 năm thành lập Đảng (1930–2030) và 100 năm thành lập nước (1945–2045)", "letter": "A"}, {"id": 124, "cat": "dh14", "q": "Trong Sáu nhiệm vụ trọng tâm của Đại hội XIV, thành phần kinh tế nào được khẳng định là \"động lực quan trọng nhất\"?", "options": ["A. Kinh tế có vốn đầu tư nước ngoài", "B. Kinh tế tư nhân", "C. Kinh tế tập thể", "D. Kinh tế hộ gia đình"], "answer": "B. Kinh tế tư nhân", "letter": "B"}, {"id": 125, "cat": "dh14", "q": "Trong nhiệm vụ cơ cấu lại nền kinh tế, đẩy mạnh CNH–HĐH tại Đại hội XIV, những yếu tố nào được xác định làm động lực chính?", "options": ["A. Khoa học công nghệ, đổi mới sáng tạo, chuyển đổi số", "B. Vay vốn nước ngoài và mở rộng diện tích nông nghiệp", "C. Xuất khẩu nguyên liệu thô và gia công giản đơn", "D. Tài nguyên thiên nhiên và lao động giá rẻ"], "answer": "A. Khoa học công nghệ, đổi mới sáng tạo, chuyển đổi số", "letter": "A"}, {"id": 126, "cat": "dh14", "q": "Trong nhiệm vụ xây dựng đồng bộ thể chế phát triển tại Đại hội XIV, yêu cầu cấp bách nào được nhấn mạnh để khơi thông mọi nguồn lực?", "options": ["A. Hạn chế sự tham gia của khu vực tư nhân vào đầu tư hạ tầng", "B. Giữ nguyên hệ thống thủ tục cũ để đảm bảo ổn định", "C. Tháo gỡ kịp thời, dứt điểm các điểm nghẽn, nút thắt", "D. Mở rộng quy mô bộ máy hành chính nhà nước"], "answer": "C. Tháo gỡ kịp thời, dứt điểm các điểm nghẽn, nút thắt", "letter": "C"}, {"id": 127, "cat": "dh14", "q": "Phương châm \"4 an\" bảo đảm cho Nhân dân trong nhiệm vụ phát triển nguồn lực con người, văn hóa tại Đại hội XIV là gì?", "options": ["A. An sinh, an toàn, an nghiệp, an quốc", "B. An cư, an lạc, an tâm, an toàn", "C. An ninh, an sinh, an toàn, an dân", "D. An bình, an khang, an định, an toàn"], "answer": "C. An ninh, an sinh, an toàn, an dân", "letter": "C"}, {"id": 128, "cat": "dh14", "q": "Nhiệm vụ quốc phòng – an ninh được Đại hội XIV xác định đối với Quân đội và Công an là xây dựng lực lượng theo định hướng nào?", "options": ["A. Tự vệ nhân dân kết hợp dân quân tại chỗ", "B. Chuyên biệt về kinh tế và ngoại giao", "C. Cách mạng, chính quy, tinh nhuệ, hiện đại", "D. Bán chuyên nghiệp, linh hoạt, quy mô nhỏ"], "answer": "C. Cách mạng, chính quy, tinh nhuệ, hiện đại", "letter": "C"}, {"id": 129, "cat": "dh14", "q": "Điểm mới nổi bật trong đột phá chiến lược về \"Kết cấu hạ tầng đồng bộ\" tại Đại hội XIV so với Đại hội XIII là nhấn mạnh bổ sung yếu tố nào?", "options": ["A. Hạ tầng giao thông đa phương thức, hạ tầng công nghệ, chuyển đổi số, chuyển đổi xanh", "B. Hạ tầng kho bãi bao cấp", "C. Hạ tầng nông nghiệp truyền thống", "D. Hạ tầng cảng cá ven biển đơn thuần"], "answer": "A. Hạ tầng giao thông đa phương thức, hạ tầng công nghệ, chuyển đổi số, chuyển đổi xanh", "letter": "A"}, {"id": 130, "cat": "dh14", "q": "Trong đột phá chiến lược về \"Nguồn nhân lực chất lượng cao\" tại Đại hội XIV, giải pháp nào được nhấn mạnh đặc biệt?", "options": ["A. Chuyển đổi cơ cấu, nâng cao chất lượng nguồn nhân lực trình độ cao; thu hút, trọng dụng nhân tài", "B. Giảm quy mô đào tạo đại học và sau đại học", "C. Chỉ đào tạo lao động phổ thông xuất khẩu", "D. Chỉ sử dụng nguồn nhân lực từ khu vực doanh nghiệp nhà nước"], "answer": "A. Chuyển đổi cơ cấu, nâng cao chất lượng nguồn nhân lực trình độ cao; thu hút, trọng dụng nhân tài", "letter": "A"}, {"id": 131, "cat": "dh14", "q": "Đặc trưng mục tiêu xây dựng đất nước trong mục tiêu tổng quát của Đại hội XIV hướng tới một nước Việt Nam xã hội chủ nghĩa như thế nào?", "options": ["A. Hòa bình, độc lập, dân chủ, giàu mạnh, phồn vinh, văn minh, hạnh phúc", "B. Tự cấp, tự túc, ổn định lâu dài", "C. Độc lập, tự do, cơm áo, hòa bình", "D. Dân giàu, nước mạnh, xã hội công bằng, văn minh"], "answer": "A. Hòa bình, độc lập, dân chủ, giàu mạnh, phồn vinh, văn minh, hạnh phúc", "letter": "A"}, {"id": 132, "cat": "dh14", "q": "Trong đột phá về \"Thể chế phát triển\" tại Đại hội XIV, nội dung cốt lõi cần nâng cao là gì?", "options": ["A. Tăng thêm số lượng văn bản quản lý hành chính trung gian", "B. Nâng cao năng lực hoạch định và tổ chức thực hiện chủ trương, đường lối của Đảng, chính sách, pháp luật của Nhà nước", "C. Thu hẹp quyền tự chủ của các địa phương và doanh nghiệp", "D. Tái lập cơ chế kế hoạch hóa tập trung trong các ngành mũi nhọn"], "answer": "B. Nâng cao năng lực hoạch định và tổ chức thực hiện chủ trương, đường lối của Đảng, chính sách, pháp luật của Nhà nước", "letter": "B"}, {"id": 133, "cat": "dh14", "q": "Điểm giống nhau trong cơ cấu Ban Chấp hành Trung ương khóa XIII và khóa XIV là gì?", "options": ["A. Đều gồm 200 Ủy viên BCH Trung ương (180 chính thức, 20 dự khuyết)", "B. Đều có 1.587 đại biểu tham dự Đại hội", "C. Đều có 18 Ủy viên Bộ Chính trị", "D. Đều đặt mục tiêu tăng trưởng GDP bình quân từ 10%/năm trở lên"], "answer": "A. Đều gồm 200 Ủy viên BCH Trung ương (180 chính thức, 20 dự khuyết)", "letter": "A"}, {"id": 134, "cat": "dh14", "q": "Điểm khác biệt về số lượng Ủy viên Bộ Chính trị giữa Đại hội XIII (2021) và Đại hội XIV (2026) là gì?", "options": ["A. Đại hội XIII bầu 17 Ủy viên, Đại hội XIV bầu 20 Ủy viên", "B. Đại hội XIII bầu 18 Ủy viên, Đại hội XIV bầu 19 Ủy viên", "C. Cả hai Đại hội đều bầu 19 Ủy viên Bộ Chính trị", "D. Đại hội XIII bầu 19 Ủy viên, Đại hội XIV bầu 18 Ủy viên"], "answer": "B. Đại hội XIII bầu 18 Ủy viên, Đại hội XIV bầu 19 Ủy viên", "letter": "B"}, {"id": 135, "cat": "dh14", "q": "Mốc thời gian kỷ niệm 40 năm công cuộc Đổi mới gắn liền với bối cảnh của Đại hội nào của Đảng?", "options": ["A. Đại hội XIV (2026)", "B. Đại hội XIII (2021)", "C. Đại hội XI (2011)", "D. Đại hội XII (2016)"], "answer": "A. Đại hội XIV (2026)", "letter": "A"}, {"id": 136, "cat": "dh14", "q": "Thách thức an ninh phi truyền thống nào được nhấn mạnh gia tăng nghiêm trọng trong bối cảnh thế giới tại Đại hội XIV?", "options": ["A. Chạy đua vũ trang hạt nhân thời Chiến tranh lạnh", "B. Xung đột biên giới lãnh thổ giữa các nước láng giềng", "C. Khủng hoảng nợ công châu Âu năm 2010", "D. Biến đổi khí hậu, dịch bệnh ngày càng nghiêm trọng"], "answer": "D. Biến đổi khí hậu, dịch bệnh ngày càng nghiêm trọng", "letter": "D"}, {"id": 137, "cat": "dh13", "q": "Trong kết quả nhiệm kỳ Đại hội XIII (2021–2026), lĩnh vực đối ngoại đã đạt thành tựu nổi bật nào?", "options": ["A. Nâng tầm quan hệ đối tác chiến lược toàn diện với các nước lớn, mở ra cục diện phát triển mới cho đất nước", "B. Lần đầu tiên gia nhập ASEAN và APEC", "C. Ký Hiệp định Sơ bộ và Hiệp định Paris về chấm dứt chiến tranh", "D. Bình thường hóa quan hệ lần đầu tiên với Trung Quốc và Hoa Kỳ"], "answer": "A. Nâng tầm quan hệ đối tác chiến lược toàn diện với các nước lớn, mở ra cục diện phát triển mới cho đất nước", "letter": "A"}, {"id": 138, "cat": "dh14", "q": "Điểm khác nhau về các mốc mục tiêu chiến lược được đặt ra tại Đại hội XIII và Đại hội XIV là gì?", "options": ["A. Đại hội XIII chỉ nêu mốc 2030; Đại hội XIV nêu mốc 2025 và 2050", "B. Cả hai Đại hội chỉ nêu duy nhất mốc năm 2045", "C. Đại hội XIII nêu mốc 2020 và 2030; Đại hội XIV nêu mốc 2035 và 2045", "D. Đại hội XIII nêu 3 mốc (2025, 2030, 2045); Đại hội XIV tập trung vào 2 mốc chiến lược 100 năm (2030 và 2045)"], "answer": "D. Đại hội XIII nêu 3 mốc (2025, 2030, 2045); Đại hội XIV tập trung vào 2 mốc chiến lược 100 năm (2030 và 2045)", "letter": "D"}, {"id": 139, "cat": "c1", "q": "Theo tài liệu Chương 1, sự kiện nào được xác định đã mở ra một thời đại mới, tác động sâu sắc đến phong trào yêu nước Việt Nam đầu thế kỷ XX?", "options": ["A. Chiến tranh thế giới thứ hai (1939) và sự ra đời của Liên Hợp Quốc (1945)", "B. Cách mạng tư sản Pháp (1789) và Quốc tế thứ II", "C. Thắng lợi của Cách mạng Tháng Mười Nga (1917) và sự ra đời của Quốc tế Cộng sản (1919)", "D. Cải cách Minh Trị ở Nhật Bản và phong trào Duy Tân ở Trung Quốc"], "answer": "C. Thắng lợi của Cách mạng Tháng Mười Nga (1917) và sự ra đời của Quốc tế Cộng sản (1919)", "letter": "C"}, {"id": 140, "cat": "c1", "q": "Tại sao sự ra đời của ba tổ chức cộng sản riêng lẻ năm 1929 đặt ra yêu cầu cấp bách phải hợp nhất thành một chính Đảng duy nhất?", "options": ["A. Vì Hội Việt Nam Cách mạng Thanh niên vẫn đủ sức lãnh đạo cả ba tổ chức", "B. Vì cả ba tổ chức đều theo khuynh hướng dân chủ tư sản", "C. Vì hoạt động riêng rẽ dẫn đến phân tán lực lượng và thiếu thống nhất về tổ chức trên cả nước", "D. Vì Quốc tế Cộng sản yêu cầu giải tán hoàn toàn phong trào công nhân"], "answer": "C. Vì hoạt động riêng rẽ dẫn đến phân tán lực lượng và thiếu thống nhất về tổ chức trên cả nước", "letter": "C"}, {"id": 141, "cat": "c1", "q": "Theo tài liệu Chương 1, các bài học kinh nghiệm của Cách mạng Tháng Tám năm 1945 gồm 4 nội dung chính nào?", "options": ["A. Đánh nhanh thắng nhanh; tiêu thổ kháng chiến; cải cách ruộng đất triệt để; xây dựng công nghiệp nặng", "B. Chỉ đạo chiến lược đúng đắn; xây dựng lực lượng toàn dân (liên minh công–nông, mặt trận rộng rãi); nắm vững bạo lực cách mạng (chính trị kết hợp vũ trang, khởi nghĩa từng phần lên tổng khởi nghĩa); xây dựng Đảng cách mạng tiên phong", "C. Chuyển đổi số; thu hút nhân tài; đa phương hóa đối ngoại; xóa bỏ cơ chế bao cấp", "D. Đàm phán hòa bình; dựa vào viện trợ nước ngoài; đấu tranh nghị trường; mở cửa kinh tế thị trường"], "answer": "B. Chỉ đạo chiến lược đúng đắn; xây dựng lực lượng toàn dân (liên minh công–nông, mặt trận rộng rãi); nắm vững bạo lực cách mạng (chính trị kết hợp vũ trang, khởi nghĩa từng phần lên tổng khởi nghĩa); xây dựng Đảng cách mạng tiên phong", "letter": "B"}, {"id": 142, "cat": "c1", "q": "Trong Cách mạng Tháng Tám năm 1945, nhân dân cả nước đã vùng dậy giành chính quyền thắng lợi trong khoảng thời gian bao lâu?", "options": ["A. Từ ngày 19/8 đến ngày 2/9/1945", "B. Từ ngày 9/3 đến ngày 19/8/1945", "C. Từ ngày 13/8 đến ngày 23/8/1945", "D. Từ ngày 14/8 đến ngày 28/8/1945"], "answer": "D. Từ ngày 14/8 đến ngày 28/8/1945", "letter": "D"}, {"id": 143, "cat": "c2", "q": "Theo tài liệu Chương 2, một trong những bài học kinh nghiệm quan trọng nhất của Đảng trong cuộc kháng chiến chống thực dân Pháp (1945–1954) về việc kết hợp nhiệm vụ là gì?", "options": ["A. Chỉ chống đế quốc, gác lại hoàn toàn nhiệm vụ xây dựng chế độ mới", "B. Tập trung toàn lực cho ngoại giao, hạn chế đấu tranh quân sự", "C. Chỉ xây dựng lực lượng bộ đội chủ lực, không cần dân quân du kích", "D. Kết hợp chặt chẽ hai nhiệm vụ cơ bản: vừa kháng chiến vừa kiến quốc, chống đế quốc và chống phong kiến"], "answer": "D. Kết hợp chặt chẽ hai nhiệm vụ cơ bản: vừa kháng chiến vừa kiến quốc, chống đế quốc và chống phong kiến", "letter": "D"}, {"id": 144, "cat": "c2", "q": "Theo tài liệu Chương 2, ý nghĩa của thắng lợi cuộc kháng chiến chống Pháp đối với dân tộc Việt Nam là gì?", "options": ["A. Chấm dứt ách thống trị của thực dân Pháp trong gần một thế kỷ và giải phóng hoàn toàn miền Bắc", "B. Mở ra thời kỳ công nghiệp hóa, hiện đại hóa gắn với kinh tế tri thức", "C. Hoàn thành cách mạng xã hội chủ nghĩa trên toàn lãnh thổ Việt Nam", "D. Giải phóng hoàn toàn cả hai miền Nam – Bắc ngay năm 1954"], "answer": "A. Chấm dứt ách thống trị của thực dân Pháp trong gần một thế kỷ và giải phóng hoàn toàn miền Bắc", "letter": "A"}, {"id": 145, "cat": "dh1_12", "q": "Trong cuộc kháng chiến chống Mỹ, cứu nước (1954–1975), hậu phương lớn miền Bắc và tiền tuyến lớn miền Nam thực hiện nhiệm vụ chiến lược nào theo Đại hội III (9/1960)?", "options": ["A. Miền Bắc làm cách mạng dân tộc dân chủ, miền Nam làm cách mạng XHCN", "B. Cách mạng XHCN ở miền Bắc (vai trò quyết định nhất) và cách mạng dân tộc dân chủ nhân dân ở miền Nam (vai trò quyết định trực tiếp giải phóng miền Nam)", "C. Cả hai miền tạm dừng xây dựng kinh tế để chỉ đấu tranh ngoại giao", "D. Cả hai miền cùng làm cách mạng xã hội chủ nghĩa ngay lập tức"], "answer": "B. Cách mạng XHCN ở miền Bắc (vai trò quyết định nhất) và cách mạng dân tộc dân chủ nhân dân ở miền Nam (vai trò quyết định trực tiếp giải phóng miền Nam)", "letter": "B"}, {"id": 146, "cat": "c2", "q": "Theo tài liệu Chương 2, những bài học kinh nghiệm lớn của Đảng trong thời kỳ kháng chiến chống Mỹ (1954–1975) là gì?", "options": ["A. Giương cao ngọn cờ độc lập dân tộc và CNXH; phương pháp cách mạng tổng hợp (khởi nghĩa toàn dân và chiến tranh nhân dân); tổ chức chiến đấu giỏi, giành thắng lợi từng bước; coi trọng xây dựng Đảng, lực lượng và tranh thủ ủng hộ quốc tế", "B. Tạm gác mục tiêu thống nhất đất nước để ưu tiên hội nhập WTO", "C. Chỉ sử dụng đấu tranh chính trị hòa bình kết hợp ngoại giao quốc tế", "D. Thực hiện chiến lược \"đánh nhanh thắng nhanh\" ngay từ năm 1954"], "answer": "A. Giương cao ngọn cờ độc lập dân tộc và CNXH; phương pháp cách mạng tổng hợp (khởi nghĩa toàn dân và chiến tranh nhân dân); tổ chức chiến đấu giỏi, giành thắng lợi từng bước; coi trọng xây dựng Đảng, lực lượng và tranh thủ ủng hộ quốc tế", "letter": "A"}, {"id": 147, "cat": "dh1_12", "q": "Theo tài liệu Chương 3, ý nghĩa của giai đoạn tìm tòi, thử nghiệm và cả những vấp váp trong các năm 1979–1986 là gì?", "options": ["A. Chứng minh cơ chế bao cấp vẫn là mô hình tối ưu nhất", "B. Đưa Việt Nam gia nhập ngay tổ chức ASEAN vào năm 1986", "C. Làm gián đoạn hoàn toàn quá trình thống nhất đất nước về mặt nhà nước", "D. Là quá trình chuẩn bị trực tiếp về mặt nhận thức và thực tiễn, tạo tiền đề quan trọng cho Đại hội VI (12/1986) đề ra đường lối đổi mới toàn diện đất nước"], "answer": "D. Là quá trình chuẩn bị trực tiếp về mặt nhận thức và thực tiễn, tạo tiền đề quan trọng cho Đại hội VI (12/1986) đề ra đường lối đổi mới toàn diện đất nước", "letter": "D"}, {"id": 148, "cat": "dh1_12", "q": "Theo tài liệu Chương 3, Đại hội V (3/1982) của Đảng đã có nhận thức mới nào về thời kỳ quá độ lên chủ nghĩa xã hội ở nước ta?", "options": ["A. Cho phép đảng viên làm kinh tế tư nhân trên cả nước", "B. Xác định chặng đường đầu của thời kỳ quá độ phải trải qua nhiều chặng đường, điều chỉnh một số chỉ tiêu, nhiệm vụ kinh tế cho phù hợp thực tiễn", "C. Khẳng định hoàn thành sản xuất lớn XHCN ngay trong vòng 5 năm", "D. Chính thức nêu khái niệm nền kinh tế thị trường định hướng XHCN"], "answer": "B. Xác định chặng đường đầu của thời kỳ quá độ phải trải qua nhiều chặng đường, điều chỉnh một số chỉ tiêu, nhiệm vụ kinh tế cho phù hợp thực tiễn", "letter": "B"}, {"id": 149, "cat": "c3", "q": "Theo tài liệu Chương 3, trong công cuộc Đổi mới, Đảng xác định công tác xây dựng, chỉnh đốn Đảng giữ vị trí gì?", "options": ["A. Nhiệm vụ phụ trợ", "B. Nhiệm vụ riêng của các cơ quan hành chính nhà nước", "C. Nhiệm vụ then chốt", "D. Nhiệm vụ mang tính giai đoạn trước năm 2000"], "answer": "C. Nhiệm vụ then chốt", "letter": "C"}, {"id": 150, "cat": "c3", "q": "Theo tài liệu Chương 3, một trong 6 bài học kinh nghiệm lớn của công cuộc Đổi mới về mối quan hệ giữa sức mạnh dân tộc và quốc tế là gì?", "options": ["A. Đóng cửa tự lực tuyệt đối để tránh ảnh hưởng bên ngoài", "B. Kết hợp sức mạnh dân tộc với sức mạnh thời đại, chủ động và tích cực hội nhập quốc tế toàn diện, sâu rộng", "C. Chỉ hội nhập kinh tế mà không phát triển quan hệ đối ngoại đa phương", "D. Phụ thuộc hoàn toàn vào vốn đầu tư trực tiếp nước ngoài"], "answer": "B. Kết hợp sức mạnh dân tộc với sức mạnh thời đại, chủ động và tích cực hội nhập quốc tế toàn diện, sâu rộng", "letter": "B"}, {"id": 151, "cat": "dh14", "q": "Tại Đại hội XIV (2026), tinh thần hành động mới được xác định trong mục tiêu tổng quát để tiến mạnh vào kỷ nguyên mới của dân tộc gồm những yếu tố nào?", "options": ["A. Tự chủ chiến lược, tự cường, tự tin, tiến mạnh vào kỷ nguyên mới của dân tộc", "B. Tạm dừng công nghiệp hóa để ổn định lạm phát", "C. Bao cấp, tập trung, khép kín", "D. Thụ động, chờ thời, thận trọng"], "answer": "A. Tự chủ chiến lược, tự cường, tự tin, tiến mạnh vào kỷ nguyên mới của dân tộc", "letter": "A"}, {"id": 152, "cat": "dh14", "q": "So với mức tăng trưởng GDP bình quân nhiệm kỳ XII (~6%/năm) và nhiệm kỳ XIII (~6,2%/năm), mục tiêu tăng trưởng GDP bình quân giai đoạn 2026–2030 do Đại hội XIV đề ra có bước nhảy vọt như thế nào?", "options": ["A. Tăng tốc lên từ 10%/năm trở lên", "B. Tăng nhẹ lên 7%/năm", "C. Giữ ổn định ở mức 6,5%/năm", "D. Giảm xuống 5%/năm để ưu tiên môi trường"], "answer": "A. Tăng tốc lên từ 10%/năm trở lên", "letter": "A"}, {"id": 153, "cat": "dh14", "q": "Trong nhiệm kỳ XIII (2021–2026), chỉ số nào phản ánh mức độ cải thiện mạnh mẽ chất lượng cuộc sống và sự hài lòng của người dân Việt Nam trên bảng xếp hạng toàn cầu năm 2025?", "options": ["A. Chỉ số xuất khẩu nông sản đứng thứ 1 toàn cầu", "B. Tuổi thọ trung bình đạt 95 tuổi", "C. Tỉ lệ đô thị hóa đạt 100% cả nước", "D. Chỉ số hạnh phúc tăng 33 bậc, xếp thứ 46/143 quốc gia"], "answer": "D. Chỉ số hạnh phúc tăng 33 bậc, xếp thứ 46/143 quốc gia", "letter": "D"}, {"id": 154, "cat": "dh14", "q": "Đại hội XIV (1/2026) khẳng định thành tựu xóa bỏ loại hình nhà ở nào trên phạm vi cả nước trong nhiệm kỳ Đại hội XIII?", "options": ["A. Nhà chung cư cũ ở các đô thị lớn", "B. Toàn bộ nhà trọ sinh viên", "C. Nhà ở ven sông ở Đồng bằng sông Cửu Long", "D. Hoàn thành xóa nhà tạm, nhà dột nát cả nước"], "answer": "D. Hoàn thành xóa nhà tạm, nhà dột nát cả nước", "letter": "D"}, {"id": 155, "cat": "c1", "q": "Theo tài liệu tóm tắt Chương 1, phong trào yêu nước theo khuynh hướng phong kiến tiêu biểu ở Việt Nam cuối thế kỷ XIX là phong trào nào?", "options": ["A. Phong trào Đông Du", "B. Phong trào Cần Vương", "C. Khởi nghĩa Yên Bái", "D. Phong trào Duy Tân"], "answer": "B. Phong trào Cần Vương", "letter": "B"}, {"id": 156, "cat": "c1", "q": "Theo tài liệu Chương 1, năm 1920 Nguyễn Ái Quốc đọc Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của V.I. Lênin và tìm thấy con đường cứu nước đúng đắn nào?", "options": ["A. Con đường cách mạng vô sản", "B. Con đường bạo động phong kiến", "C. Con đường quân chủ lập hiến", "D. Con đường cải cách dân chủ tư sản"], "answer": "A. Con đường cách mạng vô sản", "letter": "A"}, {"id": 157, "cat": "c1", "q": "Trong Cương lĩnh chính trị đầu tiên (2/1930), mối quan hệ giữa cách mạng Việt Nam và cách mạng thế giới được xác định như thế nào?", "options": ["A. Cách mạng Việt Nam là một bộ phận của cách mạng vô sản thế giới", "B. Cách mạng Việt Nam phụ thuộc vào cách mạng tư sản phương Tây", "C. Cách mạng Việt Nam hoàn toàn tách biệt với cách mạng thế giới", "D. Cách mạng Việt Nam chỉ liên minh với các nước thuộc địa ở châu Phi"], "answer": "A. Cách mạng Việt Nam là một bộ phận của cách mạng vô sản thế giới", "letter": "A"}, {"id": 158, "cat": "c1", "q": "Theo tài liệu Chương 1, Luận cương chính trị tháng 10/1930 xác định tính chất và hướng phát triển của cách mạng Đông Dương như thế nào?", "options": ["A. Cải cách hòa bình trong khuôn khổ chế độ thực dân Pháp", "B. Cách mạng tư sản dân quyền, phát triển bỏ qua thời kỳ tư bản chủ nghĩa tiến thẳng lên chủ nghĩa xã hội", "C. Cách mạng dân chủ tư sản kiểu cũ tiến lên chủ nghĩa tư bản", "D. Cách mạng giải phóng dân tộc tạm gác toàn bộ vấn đề giai cấp"], "answer": "B. Cách mạng tư sản dân quyền, phát triển bỏ qua thời kỳ tư bản chủ nghĩa tiến thẳng lên chủ nghĩa xã hội", "letter": "B"}, {"id": 159, "cat": "c1", "q": "Trước sự khủng bố trắng ác liệt của thực dân Pháp sau cao trào Xô viết Nghệ – Tĩnh (1930–1931), Đảng Cộng sản Đông Dương đã có hành động gì?", "options": ["A. Chuyển sang khuynh hướng dân chủ tư sản", "B. Giải tán hoàn toàn tổ chức Đảng trên cả nước", "C. Rút vào bí mật, kiên cường giữ vững ý chí và từng bước khôi phục hệ thống tổ chức", "D. Ký hòa ước thỏa hiệp với chính quyền thực dân Pháp"], "answer": "C. Rút vào bí mật, kiên cường giữ vững ý chí và từng bước khôi phục hệ thống tổ chức", "letter": "C"}, {"id": 160, "cat": "c1", "q": "Trong phong trào dân chủ 1936–1939, Đảng Cộng sản Đông Dương đã kết hợp những hình thức đấu tranh nào?", "options": ["A. Kết hợp đấu tranh công khai, hợp pháp với bí mật, bất hợp pháp", "B. Chỉ bãi công kinh tế, không tham gia báo chí", "C. Chỉ đấu tranh nghị trường, bỏ hẳn hoạt động bí mật", "D. Chỉ đấu tranh vũ trang bí mật trong rừng núi"], "answer": "A. Kết hợp đấu tranh công khai, hợp pháp với bí mật, bất hợp pháp", "letter": "A"}, {"id": 161, "cat": "c1", "q": "Phong trào quần chúng sôi nổi mở đầu thời kỳ dân chủ 1936–1939 nhằm thu thập nguyện vọng gửi tới phái đoàn Quốc hội Pháp là phong trào nào?", "options": ["A. Phong trào Xô viết Nghệ – Tĩnh", "B. Phong trào Đông Dương Đại hội", "C. Phong trào Đồng khởi", "D. Phong trào Đông Du"], "answer": "B. Phong trào Đông Dương Đại hội", "letter": "B"}, {"id": 162, "cat": "c1", "q": "Tháng 8/1945, sự kiện quốc tế nào tạo ra thời cơ \"ngàn năm có một\" cho nhân dân Việt Nam Tổng khởi nghĩa giành chính quyền?", "options": ["A. Đức tấn công Ba Lan mở màn Chiến tranh thế giới thứ hai", "B. Phát xít Nhật tiến vào Đông Dương", "C. Phát xít Nhật đầu hàng Đồng minh", "D. Chính phủ Mặt trận nhân dân Pháp lên cầm quyền"], "answer": "C. Phát xít Nhật đầu hàng Đồng minh", "letter": "C"}, {"id": 163, "cat": "c1", "q": "Theo tài liệu Chương 1, Cách mạng Tháng Tám 1945 đã lập nên nhà nước đầu tiên kiểu nào ở khu vực Đông Nam Á?", "options": ["A. Nhà nước tự trị thuộc khối Liên hiệp Pháp", "B. Nhà nước của nhân dân (dân chủ nhân dân) đầu tiên ở Đông Nam Á", "C. Nhà nước quân chủ lập hiến đầu tiên ở Đông Nam Á", "D. Nhà nước liên bang tư sản đầu tiên ở Đông Nam Á"], "answer": "B. Nhà nước của nhân dân (dân chủ nhân dân) đầu tiên ở Đông Nam Á", "letter": "B"}, {"id": 164, "cat": "c1", "q": "Trong tình thế \"ngàn cân treo sợi tóc\" ngay sau Cách mạng Tháng Tám 1945, quân Pháp đã núp bóng lực lượng nào để quay trở lại gây hấn ở miền Nam ngày 23/9/1945?", "options": ["A. Quân đội Nhật", "B. Quân đội Mỹ", "C. Quân đội Trung Hoa Dân quốc", "D. Quân đội Anh"], "answer": "D. Quân đội Anh", "letter": "D"}, {"id": 165, "cat": "c2", "q": "Để xây dựng lại Ngân khố quốc gia và từng bước chuẩn bị cho việc phát hành đồng giấy bạc Việt Nam ngay sau Cách mạng Tháng Tám 1945, Chính phủ đã dựa vào biện pháp nào?", "options": ["A. Thành lập \"Quỹ Độc lập\" và tổ chức \"Tuần lễ vàng\" quyên góp vàng, tài chính từ nhân dân", "B. Vay viện trợ không hoàn lại từ các nước Đồng minh phương Tây", "C. Tăng gấp đôi thuế thân và thuế ruộng đất thời Pháp thuộc", "D. Bán toàn bộ hầm mỏ và đồn điền cho nước ngoài"], "answer": "A. Thành lập \"Quỹ Độc lập\" và tổ chức \"Tuần lễ vàng\" quyên góp vàng, tài chính từ nhân dân", "letter": "A"}, {"id": 166, "cat": "c2", "q": "Nhờ phong trào tăng gia sản xuất và thực hành tiết kiệm (\"Hũ gạo tiết kiệm\", \"Ngày đồng tâm\"), nạn đói sau Cách mạng Tháng Tám 1945 cơ bản được đẩy lùi vào thời điểm nào?", "options": ["A. Đến đầu năm 1946", "B. Đến cuối năm 1947", "C. Ngay trong tháng 9/1945", "D. Đến năm 1950"], "answer": "A. Đến đầu năm 1946", "letter": "A"}, {"id": 167, "cat": "c2", "q": "Trong cuộc kháng chiến chống Pháp (1951–1954), để bồi dưỡng sức dân và củng cố hậu phương kháng chiến toàn diện, Đảng đã thực hiện chủ trương gì ở nông thôn?", "options": ["A. Áp dụng Khoán 10 giao đất lâu dài cho hộ nông dân", "B. Chỉnh đốn Đảng, phát triển kinh tế, văn hóa và từng bước cải cách ruộng đất", "C. Xóa bỏ hoàn toàn sản xuất nông nghiệp để chuyển sang công nghiệp nặng", "D. Thành lập các khu chế xuất và khu công nghiệp hiện đại"], "answer": "B. Chỉnh đốn Đảng, phát triển kinh tế, văn hóa và từng bước cải cách ruộng đất", "letter": "B"}, {"id": 168, "cat": "c2", "q": "Chiến thắng Điện Biên Phủ (7/5/1954) được tài liệu Chương 2 đánh giá bằng cụm từ nổi tiếng nào?", "options": ["A. \"Đòn thăm dò chiến lược quyết định\"", "B. \"Cuộc tổng diễn tập đầu tiên của cách mạng Việt Nam\"", "C. \"Lừng lẫy năm châu, chấn động địa cầu\"", "D. \"Kỷ nguyên vươn mình của dân tộc\""], "answer": "C. \"Lừng lẫy năm châu, chấn động địa cầu\"", "letter": "C"}, {"id": 169, "cat": "c2", "q": "Theo tài liệu Chương 2, thắng lợi cuộc kháng chiến chống thực dân Pháp còn gắn liền với sự ủng hộ quốc tế nào?", "options": ["A. Sự viện trợ quân sự trực tiếp của Hoa Kỳ và khối NATO", "B. Sự hỗ trợ của chính quyền thực dân Anh tại Đông Nam Á", "C. Sự giúp đỡ của Liên Xô, Trung Quốc, các nước XHCN anh em và nhân dân yêu chuộng hòa bình trên thế giới, kể cả nhân dân tiến bộ Pháp", "D. Sự tài trợ tài chính từ Quỹ Tiền tệ Quốc tế (IMF)"], "answer": "C. Sự giúp đỡ của Liên Xô, Trung Quốc, các nước XHCN anh em và nhân dân yêu chuộng hòa bình trên thế giới, kể cả nhân dân tiến bộ Pháp", "letter": "C"}, {"id": 170, "cat": "c2", "q": "Sau năm 1954, chế độ chính trị – xã hội của miền Nam Việt Nam mang đặc điểm nào theo tài liệu Chương 2?", "options": ["A. Trở thành thuộc địa kiểu mới của đế quốc Mỹ", "B. Được giải phóng hoàn toàn và tiến lên chủ nghĩa xã hội", "C. Vẫn là thuộc địa kiểu cũ do thực dân Pháp trực tiếp cai trị", "D. Là khu vực trung lập dưới sự quản lý của Liên Hợp Quốc"], "answer": "A. Trở thành thuộc địa kiểu mới của đế quốc Mỹ", "letter": "A"}, {"id": 171, "cat": "dh1_12", "q": "Đại hội III của Đảng (9/1960) đã thông qua kế hoạch phát triển kinh tế nào ở miền Bắc nhằm bước đầu xây dựng cơ sở vật chất – kỹ thuật của chủ nghĩa xã hội?", "options": ["A. Kế hoạch 5 năm lần thứ nhất (1961–1965)", "B. Kế hoạch 5 năm lần thứ hai (1976–1980)", "C. Chiến lược ổn định kinh tế – xã hội đến năm 2000", "D. Kế hoạch 3 năm (1955–1957)"], "answer": "A. Kế hoạch 5 năm lần thứ nhất (1961–1965)", "letter": "A"}, {"id": 172, "cat": "c2", "q": "Năm 1965, khi đứng trước nguy cơ phá sản của chiến lược \"Chiến tranh đặc biệt\", đế quốc Mỹ đã chuyển sang hành động leo thang nào?", "options": ["A. Trao trả lại miền Nam cho thực dân Pháp quản lý", "B. Rút toàn bộ quân đội và cố vấn khỏi miền Nam Việt Nam", "C. Ký Hiệp định Paris chấm dứt chiến tranh ngay lập tức", "D. Ồ ạt đưa quân viễn chinh vào miền Nam tiến hành \"Chiến tranh cục bộ\" đồng thời leo thang chiến tranh phá hoại miền Bắc lần thứ nhất"], "answer": "D. Ồ ạt đưa quân viễn chinh vào miền Nam tiến hành \"Chiến tranh cục bộ\" đồng thời leo thang chiến tranh phá hoại miền Bắc lần thứ nhất", "letter": "D"}, {"id": 173, "cat": "c2", "q": "Việc thành lập Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam (6/1969) có ý nghĩa quan trọng nhất đối với mặt trận nào?", "options": ["A. Mở đường cho chiến lược \"Chiến tranh đơn phương\"", "B. Đáp ứng yêu cầu phát triển của cách mạng, nhất là trong đấu tranh ngoại giao", "C. Giải phóng hoàn toàn các đô thị miền Nam ngay trong năm 1969", "D. Thay thế hoàn toàn vai trò của Quốc hội nước Việt Nam Dân chủ Cộng hòa"], "answer": "B. Đáp ứng yêu cầu phát triển của cách mạng, nhất là trong đấu tranh ngoại giao", "letter": "B"}, {"id": 174, "cat": "c2", "q": "Theo tài liệu Chương 2, thắng lợi của cuộc kháng chiến chống Mỹ, cứu nước (1954–1975) có ý nghĩa quốc tế gì?", "options": ["A. Chấm dứt hoàn toàn sự tồn tại của Liên Hợp Quốc", "B. Mở đầu Chiến tranh thế giới thứ ba", "C. Làm tan rã khối ASEAN vào năm 1975", "D. Là một trong những chiến công vĩ đại của dân tộc trong thế kỷ XX, cổ vũ mạnh mẽ phong trào giải phóng dân tộc, dân chủ và hòa bình trên thế giới"], "answer": "D. Là một trong những chiến công vĩ đại của dân tộc trong thế kỷ XX, cổ vũ mạnh mẽ phong trào giải phóng dân tộc, dân chủ và hòa bình trên thế giới", "letter": "D"}, {"id": 175, "cat": "c1", "q": "Đại hội XI của Đảng (1/2011) thông qua Chiến lược phát triển kinh tế – xã hội 2011–2020 với định hướng gắn công nghiệp hóa, hiện đại hóa với yếu tố nào?", "options": ["A. Khai thác tối đa tài nguyên thô", "B. Phát triển kinh tế tri thức", "C. Sản xuất nông nghiệp tự cung tự cấp", "D. Cơ chế bao cấp tập trung"], "answer": "B. Phát triển kinh tế tri thức", "letter": "B"}, {"id": 176, "cat": "c3", "q": "Theo tài liệu Chương 3, một trong các bài học kinh nghiệm của công cuộc Đổi mới về việc xử lý mâu thuẫn mới phát sinh trong thực tiễn là gì?", "options": ["A. Chờ đợi vấn đề tự lắng xuống rồi mới xử lý hành chính", "B. Giao toàn bộ công tác giải quyết mâu thuẫn cho các tổ chức quốc tế", "C. Tạm dừng công cuộc đổi mới khi xuất hiện khó khăn kinh tế", "D. Chủ động dự báo, kịp thời phát hiện và giải quyết những mâu thuẫn, vấn đề mới sinh; kiên quyết, kiên trì đấu tranh phòng, chống tham nhũng, tiêu cực gắn với xây dựng, chỉnh đốn Đảng"], "answer": "D. Chủ động dự báo, kịp thời phát hiện và giải quyết những mâu thuẫn, vấn đề mới sinh; kiên quyết, kiên trì đấu tranh phòng, chống tham nhũng, tiêu cực gắn với xây dựng, chỉnh đốn Đảng", "letter": "D"}, {"id": 177, "cat": "dh13", "q": "Theo tài liệu Đại hội XIII, 5 trụ cột của Chủ đề Đại hội XIII KHÔNG bao gồm nội dung nào sau đây?", "options": ["A. Đẩy mạnh toàn diện, đồng bộ công cuộc đổi mới; xây dựng, bảo vệ vững chắc Tổ quốc; phấn đấu giữa thế kỷ XXI trở thành nước phát triển định hướng XHCN", "B. Tăng cường xây dựng, chỉnh đốn Đảng và hệ thống chính trị trong sạch, vững mạnh", "C. Khơi dậy ý chí, khát vọng phát triển đất nước gắn với sức mạnh đại đoàn kết dân tộc và sức mạnh thời đại", "D. Tái lập cơ chế kế hoạch hóa tập trung bao cấp trong các ngành kinh tế trọng điểm"], "answer": "D. Tái lập cơ chế kế hoạch hóa tập trung bao cấp trong các ngành kinh tế trọng điểm", "letter": "D"}, {"id": 178, "cat": "dh13", "q": "Trong Sáu nhiệm vụ trọng tâm của Đại hội XIII, nhiệm vụ số 1 được đặt lên hàng đầu là gì?", "options": ["A. Quản lý chặt chẽ đất đai, tài nguyên và thích ứng biến đổi khí hậu", "B. Kiểm soát dịch bệnh và chuyển đổi số", "C. Xây dựng, chỉnh đốn Đảng và hệ thống chính trị trong sạch, vững mạnh toàn diện; đẩy mạnh đấu tranh phòng, chống tham nhũng, lãng phí, tiêu cực", "D. Hoàn thiện hệ thống giao thông đường bộ cao tốc"], "answer": "C. Xây dựng, chỉnh đốn Đảng và hệ thống chính trị trong sạch, vững mạnh toàn diện; đẩy mạnh đấu tranh phòng, chống tham nhũng, lãng phí, tiêu cực", "letter": "C"}, {"id": 179, "cat": "dh14", "q": "Trong Sáu nhiệm vụ trọng tâm của Đại hội XIII, nhiệm vụ về văn hóa và xã hội nhấn mạnh nội dung nào?", "options": ["A. Khơi dậy khát vọng phát triển đất nước phồn vinh, hạnh phúc; phát huy giá trị văn hóa, con người Việt Nam; bảo đảm an sinh xã hội", "B. Phổ cập đại học cho 100% dân số vào năm 2025", "C. Xóa bỏ hoàn toàn các loại hình văn hóa truyền thống địa phương", "D. Chuyển toàn bộ y tế công lập sang tư nhân hóa"], "answer": "A. Khơi dậy khát vọng phát triển đất nước phồn vinh, hạnh phúc; phát huy giá trị văn hóa, con người Việt Nam; bảo đảm an sinh xã hội", "letter": "A"}, {"id": 180, "cat": "dh13", "q": "Trong Sáu nhiệm vụ trọng tâm của Đại hội XIII, nhiệm vụ về tài nguyên và môi trường đề ra yêu cầu gì?", "options": ["A. Dừng toàn bộ các dự án năng lượng tái tạo", "B. Chuyển toàn bộ đất nông nghiệp sang đất công nghiệp", "C. Quản lý chặt chẽ, hiệu quả đất đai, tài nguyên; bảo vệ môi trường; chủ động thích ứng với biến đổi khí hậu", "D. Khai thác triệt để tài nguyên khoáng sản để tăng trưởng ngắn hạn"], "answer": "C. Quản lý chặt chẽ, hiệu quả đất đai, tài nguyên; bảo vệ môi trường; chủ động thích ứng với biến đổi khí hậu", "letter": "C"}, {"id": 181, "cat": "dh13", "q": "Trong Sáu nhiệm vụ trọng tâm của Đại hội XIII, nhiệm vụ về pháp luật và dân chủ nêu rõ điều gì?", "options": ["A. Thu hẹp quyền giám sát của Mặt trận Tổ quốc", "B. Chỉ tập trung sửa đổi luật thuế xuất nhập khẩu", "C. Áp dụng nguyên xi hệ thống pháp luật phương Tây", "D. Hoàn thiện pháp luật, phát huy dân chủ xã hội chủ nghĩa, quyền làm chủ của nhân dân; tăng cường đại đoàn kết toàn dân tộc"], "answer": "D. Hoàn thiện pháp luật, phát huy dân chủ xã hội chủ nghĩa, quyền làm chủ của nhân dân; tăng cường đại đoàn kết toàn dân tộc", "letter": "D"}, {"id": 182, "cat": "dh13", "q": "Trong Ba đột phá chiến lược của Đại hội XIII, đột phá về \"Thể chế\" xác định hoàn thiện thể chế kinh tế thị trường định hướng XHCN theo 4 tính chất nào?", "options": ["A. Tự phát, tự do, cạnh tranh tuyệt đối, phi nhà nước", "B. Đầy đủ, đồng bộ, hiện đại, hội nhập", "C. Nhanh chóng, linh hoạt, khép kín, tự cấp", "D. Tập trung, bao cấp, ổn định, dài hạn"], "answer": "B. Đầy đủ, đồng bộ, hiện đại, hội nhập", "letter": "B"}, {"id": 183, "cat": "dh13", "q": "Trong Ba đột phá chiến lược của Đại hội XIII, đột phá về \"Nguồn nhân lực & KHCN\" gắn việc phát triển nguồn nhân lực khoa học công nghệ, đổi mới sáng tạo với yếu tố nào?", "options": ["A. Mục tiêu giảm quy mô công nghiệp hóa", "B. Chiến lược đóng cửa thị trường lao động", "C. Khát vọng phát triển đất nước", "D. Cơ chế phân phối theo tem phiếu"], "answer": "C. Khát vọng phát triển đất nước", "letter": "C"}, {"id": 184, "cat": "dh13", "q": "Theo thông tin Đại hội XIII, trong giai đoạn nhiệm kỳ XII (2016–2020), lĩnh vực xã hội quốc tế nào của Việt Nam đã hoàn thành trước thời hạn?", "options": ["A. Hoàn thành chuyển đổi số 100% doanh nghiệp nhỏ", "B. Hoàn thành nhiều Mục tiêu Thiên niên kỷ trước thời hạn", "C. Hoàn thành 100% tuyến đường sắt tốc độ cao Bắc – Nam", "D. Hoàn thành mục tiêu trở thành nước thu nhập cao trước năm 2020"], "answer": "B. Hoàn thành nhiều Mục tiêu Thiên niên kỷ trước thời hạn", "letter": "B"}, {"id": 185, "cat": "dh14", "q": "Theo thông tin Đại hội XIV (1/2026), quy mô GDP của Việt Nam vượt 514 tỷ USD vào cuối nhiệm kỳ XIII tương đương gấp bao nhiêu lần so với năm 2020?", "options": ["A. Gấp 2,5 lần", "B. Gấp 1,48 lần", "C. Gấp 1,2 lần", "D. Gấp 3,0 lần"], "answer": "B. Gấp 1,48 lần", "letter": "B"}, {"id": 186, "cat": "dh14", "q": "Theo thông tin Đại hội XIV, ba đột phá chiến lược trong nhiệm kỳ XIII (thể chế, hạ tầng, nhân lực) đạt kết quả nổi bật nhất ở hai loại hình hạ tầng nào?", "options": ["A. Hạ tầng chợ truyền thống và kho lương thực bao cấp", "B. Hạ tầng giao thông và hạ tầng số phát triển bứt phá", "C. Hạ tầng thủy lợi cổ điển và hạ tầng khai khoáng than", "D. Hạ tầng sản xuất thủ công nghiệp hộ gia đình"], "answer": "B. Hạ tầng giao thông và hạ tầng số phát triển bứt phá", "letter": "B"}, {"id": 187, "cat": "dh14", "q": "Theo thông tin Đại hội XIV, tốc độ tăng trưởng GDP riêng năm 2025 đạt bao nhiêu phần trăm?", "options": ["A. 2,91%", "B. 10,0%", "C. 6,20%", "D. 8,02%"], "answer": "D. 8,02%", "letter": "D"}, {"id": 188, "cat": "dh14", "q": "Theo thông tin Đại hội XIV, tầm nhìn đến năm 2045 (kỷ niệm 100 năm thành lập nước) hướng tới xây dựng Việt Nam trở thành nước phát triển, thu nhập cao, gắn với tâm nguyện nào của Chủ tịch Hồ Chí Minh?", "options": ["A. Hoàn thành cải cách ruộng đất toàn diện", "B. Tự cấp tự túc hoàn toàn về mọi mặt", "C. Sánh vai với các cường quốc năm châu", "D. Duy trì mức thu nhập trung bình ổn định"], "answer": "C. Sánh vai với các cường quốc năm châu", "letter": "C"}, {"id": 189, "cat": "dh14", "q": "So sánh GDP bình quân đầu người cuối nhiệm kỳ XII (báo cáo tại ĐH XIII) và cuối nhiệm kỳ XIII (báo cáo tại ĐH XIV), con số này tăng từ mức nào lên mức nào?", "options": ["A. Từ 3.500 USD lên 8.500 USD", "B. Từ 2.779 USD lên 5.026 USD", "C. Từ 1.500 USD lên 3.000 USD", "D. Từ 2.000 USD lên 4.200 USD"], "answer": "B. Từ 2.779 USD lên 5.026 USD", "letter": "B"}, {"id": 190, "cat": "dh14", "q": "So sánh tỉ lệ bao phủ bảo hiểm y tế dân số tại báo cáo Đại hội XIII (cuối nhiệm kỳ XII) và báo cáo Đại hội XIV (cuối nhiệm kỳ XIII)?", "options": ["A. Tăng từ trên 70% lên 85%", "B. Tăng từ trên 90% lên 95,2%", "C. Giữ nguyên ở mức 90%", "D. Tăng từ 80% lên 90%"], "answer": "B. Tăng từ trên 90% lên 95,2%", "letter": "B"}, {"id": 191, "cat": "dh14", "q": "So sánh tỉ lệ hộ nghèo đa chiều giai đoạn 2022–2025 được nêu trong tài liệu Đại hội XIV?", "options": ["A. Giảm từ 6,5% (2022) xuống 3,0% (2025)", "B. Giảm từ 4,2% (2022) xuống 1,3% (2025)", "C. Giảm từ 8,0% (2022) xuống 4,2% (2025)", "D. Giảm từ 3,0% (2022) xuống 2,5% (2025)"], "answer": "B. Giảm từ 4,2% (2022) xuống 1,3% (2025)", "letter": "B"}, {"id": 192, "cat": "dh14", "q": "Trong Sáu nhiệm vụ trọng tâm của Đại hội XIV, nội dung nào xếp ở vị trí số 1?", "options": ["A. Xây dựng, chỉnh đốn Đảng và hệ thống chính trị trong sạch, vững mạnh toàn diện; nâng cao năng lực lãnh đạo, cầm quyền của Đảng", "B. Giảm quy mô đầu tư công cho hạ tầng giao thông", "C. Tập trung xuất khẩu nông sản thô", "D. Xóa bỏ hoàn toàn thuế thu nhập doanh nghiệp"], "answer": "A. Xây dựng, chỉnh đốn Đảng và hệ thống chính trị trong sạch, vững mạnh toàn diện; nâng cao năng lực lãnh đạo, cầm quyền của Đảng", "letter": "A"}, {"id": 193, "cat": "dh14", "q": "Theo thông tin Đại hội XIV, giai đoạn định hướng phát triển mới mà Đại hội XIV mở ra là giai đoạn nào và tầm nhìn đến năm nào?", "options": ["A. Giai đoạn 2025–2030 và tầm nhìn đến năm 2050", "B. Giai đoạn 2021–2025 và tầm nhìn đến năm 2035", "C. Giai đoạn 2026–2035 và tầm nhìn đến năm 2060", "D. Giai đoạn 2026–2030 và tầm nhìn đến năm 2045"], "answer": "D. Giai đoạn 2026–2030 và tầm nhìn đến năm 2045", "letter": "D"}, {"id": 194, "cat": "dh14", "q": "Trong bối cảnh trong nước tại Đại hội XIV, yêu cầu đặt ra để vượt qua nguy cơ tụt hậu công nghệ và bẫy thu nhập trung bình là gì?", "options": ["A. Hạn chế ứng dụng trí tuệ nhân tạo và công nghệ số", "B. Thu hẹp hội nhập quốc tế để bảo hộ doanh nghiệp nội địa", "C. Đổi mới tư duy, hành động mạnh mẽ, quyết liệt, đột phá, hiệu quả", "D. Giữ nguyên tư duy cũ và hành động thận trọng, chậm rãi"], "answer": "C. Đổi mới tư duy, hành động mạnh mẽ, quyết liệt, đột phá, hiệu quả", "letter": "C"}, {"id": 195, "cat": "dh14", "q": "Ba đột phá chiến lược của Đại hội XIV bao gồm những trụ cột nào?", "options": ["A. Thể chế phát triển; Nguồn nhân lực chất lượng cao; Kết cấu hạ tầng đồng bộ (giao thông đa phương thức, công nghệ, chuyển đổi số, chuyển đổi xanh)", "B. Quốc hữu hóa ngân hàng; Bao cấp lương thực; Cải cách hành chính cấp xã", "C. Nông nghiệp hữu cơ; Du lịch biển đảo; Xuất khẩu lao động", "D. Đầu tư công nghiệp nặng; Hạn chế kinh tế tư nhân; Phát triển hợp tác xã"], "answer": "A. Thể chế phát triển; Nguồn nhân lực chất lượng cao; Kết cấu hạ tầng đồng bộ (giao thông đa phương thức, công nghệ, chuyển đổi số, chuyển đổi xanh)", "letter": "A"}, {"id": 196, "cat": "dh14", "q": "Sự khác biệt về tổng số đại biểu tham dự giữa Đại hội XIII (2021) và Đại hội XIV (2026) theo hai tài liệu tóm tắt là bao nhiêu?", "options": ["A. Đại hội XIII có 1.587 đại biểu; Đại hội XIV có 1.586 đại biểu", "B. Đại hội XIII có 1.586 đại biểu; Đại hội XIV có 1.587 đại biểu", "C. Đại hội XIII có 1.500 đại biểu; Đại hội XIV có 1.600 đại biểu", "D. Cả hai Đại hội đều có đúng 1.587 đại biểu"], "answer": "A. Đại hội XIII có 1.587 đại biểu; Đại hội XIV có 1.586 đại biểu", "letter": "A"}, {"id": 197, "cat": "dh14", "q": "Trong nhiệm kỳ Đại hội XIV, lĩnh vực chuyển đổi kép nào được nhấn mạnh trong đột phá về kết cấu hạ tầng đồng bộ?", "options": ["A. Chuyển đổi tiền tệ và chuyển đổi thương mại", "B. Chuyển đổi số và chuyển đổi xanh", "C. Chuyển đổi giáo dục và chuyển đổi dân số", "D. Chuyển đổi cơ cấu nông nghiệp và chuyển đổi hành chính"], "answer": "B. Chuyển đổi số và chuyển đổi xanh", "letter": "B"}, {"id": 198, "cat": "dh14", "q": "Khác với Đại hội XIII nhấn mạnh \"kiểm soát dịch bệnh, phục hồi kinh tế\", nhiệm vụ kinh tế tại Đại hội XIV nhấn mạnh vai trò đột phá của thành phần kinh tế nào trong nền KTTT định hướng XHCN hiện đại?", "options": ["A. Kinh tế tập thể là động lực duy nhất", "B. Kinh tế tư nhân là động lực quan trọng nhất", "C. Kinh tế có vốn nước ngoài là nền tảng chủ đạo duy nhất", "D. Kinh tế tự cung tự cấp là trọng tâm"], "answer": "B. Kinh tế tư nhân là động lực quan trọng nhất", "letter": "B"}, {"id": 199, "cat": "dh14", "q": "Đại hội XIII và Đại hội XIV đều có đại biểu đại diện cho khoảng bao nhiêu đảng viên trên cả nước?", "options": ["A. Hơn 5 triệu đảng viên", "B. Hơn 8 triệu đảng viên", "C. Hơn 3 triệu đảng viên", "D. Hơn 4 triệu đảng viên"], "answer": "A. Hơn 5 triệu đảng viên", "letter": "A"}, {"id": 200, "cat": "nhapmon", "q": "Theo Giáo trình Lịch sử Đảng (Chương nhập môn), đối tượng nghiên cứu của khoa học Lịch sử Đảng Cộng sản Việt Nam là gì?", "options": ["A. Lịch sử phát triển các nền kinh tế thế giới từ thế kỷ XIX đến nay", "B. Lịch sử hình thành các nhà nước phong kiến Việt Nam cổ đại", "C. Quy luật vận động của các lực lượng tự nhiên và địa lý Việt Nam", "D. Sự ra đời, phát triển và hoạt động lãnh đạo của Đảng qua các thời kỳ lịch sử"], "answer": "D. Sự ra đời, phát triển và hoạt động lãnh đạo của Đảng qua các thời kỳ lịch sử", "letter": "D"}, {"id": 201, "cat": "nhapmon", "q": "Công tác xây dựng Đảng qua các thời kỳ lịch sử được Giáo trình Lịch sử Đảng nghiên cứu trên 4 mặt cơ bản nào?", "options": ["A. Công nghiệp, nông nghiệp, dịch vụ và thương mại", "B. Chính trị, tư tưởng, tổ chức và đạo đức", "C. Kinh tế, quân sự, văn hóa, ngoại giao", "D. Pháp luật, hành chính, tài chính và nhân sự"], "answer": "B. Chính trị, tư tưởng, tổ chức và đạo đức", "letter": "B"}, {"id": 202, "cat": "nhapmon", "q": "Môn học Lịch sử Đảng Cộng sản Việt Nam thực hiện 3 chức năng cơ bản nào?", "options": ["A. Chức năng quản lý, chức năng điều hành, chức năng giám sát", "B. Chức năng kinh tế, chức năng quân sự, chức năng đối ngoại", "C. Chức năng nhận thức, chức năng giáo dục, chức năng dự báo và phê phán", "D. Chức năng lập pháp, chức năng hành pháp, chức năng tư pháp"], "answer": "C. Chức năng nhận thức, chức năng giáo dục, chức năng dự báo và phê phán", "letter": "C"}, {"id": 203, "cat": "nhapmon", "q": "Phương pháp luận sử học khi nghiên cứu, học tập Lịch sử Đảng Cộng sản Việt Nam dựa trên nền tảng nào?", "options": ["A. Phương pháp thống kê toán học thuần túy", "B. Thuyết định mệnh lịch sử và chủ nghĩa thực dụng", "C. Chủ nghĩa duy vật biện chứng và chủ nghĩa duy vật lịch sử", "D. Chủ nghĩa duy tâm khách quan và kinh nghiệm chủ nghĩa"], "answer": "C. Chủ nghĩa duy vật biện chứng và chủ nghĩa duy vật lịch sử", "letter": "C"}, {"id": 204, "cat": "c1", "q": "Trong phương pháp nghiên cứu Lịch sử Đảng, việc xem xét sự kiện lịch sử cần quán triệt 4 quan điểm nào theo Giáo trình?", "options": ["A. Cảm tính, một chiều, ngắn hạn và trừu tượng", "B. Khách quan, toàn diện, phát triển và lịch sử cụ thể", "C. Chủ quan, phiến diện, tĩnh tại và khép kín", "D. Cơ học, ngẫu nhiên, biệt lập và bất biến"], "answer": "B. Khách quan, toàn diện, phát triển và lịch sử cụ thể", "letter": "B"}, {"id": 205, "cat": "nhapmon", "q": "Hai phương pháp cơ bản gắn bó chặt chẽ được sử dụng chủ yếu trong nghiên cứu, học tập Lịch sử Đảng là gì?", "options": ["A. Phương pháp định lượng và phương pháp mô phỏng", "B. Phương pháp thực nghiệm và phương pháp phỏng vấn", "C. Phương pháp quy nạp và phương pháp giả định", "D. Phương pháp lịch sử và phương pháp logic"], "answer": "D. Phương pháp lịch sử và phương pháp logic", "letter": "D"}, {"id": 206, "cat": "nhapmon", "q": "Theo Giáo trình Lịch sử Đảng (Chương nhập môn), tiêu chuẩn của chân lý trong tư duy và nhận thức lịch sử là gì?", "options": ["A. Ý chí chủ quan của cá nhân người nghiên cứu", "B. Sự suy diễn lý thuyết thuần túy tách rời thực tế", "C. Thực tiễn và kết quả của hoạt động thực tiễn", "D. Số lượng tài liệu trích dẫn từ sách nước ngoài"], "answer": "C. Thực tiễn và kết quả của hoạt động thực tiễn", "letter": "C"}, {"id": 207, "cat": "nhapmon", "q": "Theo phần Kết luận của Giáo trình Lịch sử Đảng (2021), dưới sự lãnh đạo của Đảng, cách mạng Việt Nam đã giành được mấy thắng lợi vĩ đại có ý nghĩa lịch sử và thời đại?", "options": ["A. 6 thắng lợi vĩ đại", "B. 4 thắng lợi vĩ đại", "C. 2 thắng lợi vĩ đại", "D. 3 thắng lợi vĩ đại"], "answer": "B. 4 thắng lợi vĩ đại", "letter": "B"}, {"id": 208, "cat": "nhapmon", "q": "Theo phần Kết luận của Giáo trình Lịch sử Đảng, bài học lớn hàng đầu về sự lãnh đạo của Đảng xuyên suốt lịch sử cách mạng Việt Nam là gì?", "options": ["A. Tách rời cách mạng Việt Nam khỏi cách mạng thế giới", "B. Chỉ tập trung đấu tranh ngoại giao hòa bình", "C. Nắm vững ngọn cờ độc lập dân tộc và chủ nghĩa xã hội", "D. Ưu tiên phát triển kinh tế tư nhân ngay từ năm 1930"], "answer": "C. Nắm vững ngọn cờ độc lập dân tộc và chủ nghĩa xã hội", "letter": "C"}, {"id": 209, "cat": "nhapmon", "q": "Theo phần Kết luận của Giáo trình, nhân tố hàng đầu quyết định thắng lợi của cách mạng Việt Nam là gì?", "options": ["A. Sự lãnh đạo đúng đắn của Đảng Cộng sản Việt Nam", "B. Điều kiện địa lý thuận lợi của bán đảo Đông Dương", "C. Nguồn tài nguyên thiên nhiên dồi dào", "D. Sự giúp đỡ một chiều từ các nước phương Tây"], "answer": "A. Sự lãnh đạo đúng đắn của Đảng Cộng sản Việt Nam", "letter": "A"}, {"id": 210, "cat": "nhapmon", "q": "Theo phần Kết luận Giáo trình (trang 422), mối quan hệ lớn nào phản ánh quy luật đổi mới kinh tế đi đôi với giữ vững định hướng xã hội chủ nghĩa?", "options": ["A. Giữa tuân theo các quy luật thị trường và bảo đảm định hướng xã hội chủ nghĩa", "B. Giữa đóng cửa thị trường và xuất khẩu nguyên liệu thô", "C. Giữa bao cấp tuyệt đối và tự do hóa không kiểm soát", "D. Giữa xóa bỏ sở hữu tư nhân và quốc hữu hóa toàn diện"], "answer": "A. Giữa tuân theo các quy luật thị trường và bảo đảm định hướng xã hội chủ nghĩa", "letter": "A"}, {"id": 211, "cat": "dh1_12", "q": "Đại hội đại biểu toàn quốc lần thứ I của Đảng (3/1935) diễn ra vào ngày nào, tại đâu và có bao nhiêu đại biểu tham dự?", "options": ["A. Từ 3–7/2/1935 tại Hương Cảng (Trung Quốc), có 50 đại biểu tham dự", "B. Từ 1–5/5/1935 tại Quảng Châu (Trung Quốc), có 100 đại biểu tham dự", "C. Từ 27–31/3/1935 tại Ma Cao (Trung Quốc), có 13 đại biểu tham dự", "D. Từ 10–15/3/1935 tại Cao Bằng (Việt Nam), có 30 đại biểu tham dự"], "answer": "C. Từ 27–31/3/1935 tại Ma Cao (Trung Quốc), có 13 đại biểu tham dự", "letter": "C"}, {"id": 212, "cat": "dh1_12", "q": "Tại Đại hội đại biểu toàn quốc lần thứ I của Đảng (3/1935), ai được bầu làm Tổng Bí thư và Nguyễn Ái Quốc được cử giữ nhiệm vụ gì?", "options": ["A. Trường Chinh làm Tổng Bí thư; Nguyễn Ái Quốc làm Bí thư Xứ ủy Bắc Kỳ", "B. Lê Hồng Phong làm Tổng Bí thư; Nguyễn Ái Quốc làm đại diện của Đảng bên cạnh Quốc tế Cộng sản", "C. Hà Huy Tập làm Tổng Bí thư; Nguyễn Ái Quốc làm Trưởng ban Tuyên huấn", "D. Trần Phú làm Tổng Bí thư; Nguyễn Ái Quốc làm Chủ tịch Đảng"], "answer": "B. Lê Hồng Phong làm Tổng Bí thư; Nguyễn Ái Quốc làm đại diện của Đảng bên cạnh Quốc tế Cộng sản", "letter": "B"}, {"id": 213, "cat": "dh1_12", "q": "Đại hội I của Đảng (3/1935) đề ra 3 nhiệm vụ trước mắt nào?", "options": ["A. Củng cố và phát triển Đảng; đẩy mạnh cuộc vận động tập hợp quần chúng; mở rộng tuyên truyền chống đế quốc, chống chiến tranh, ủng hộ Liên Xô", "B. Xây dựng chủ nghĩa xã hội ở miền Bắc, giải phóng miền Nam, thống nhất đất nước", "C. Đánh Pháp, đuổi Nhật, chia ruộng đất cho dân cày", "D. Đổi mới kinh tế, xóa bỏ bao cấp, gia nhập ASEAN"], "answer": "A. Củng cố và phát triển Đảng; đẩy mạnh cuộc vận động tập hợp quần chúng; mở rộng tuyên truyền chống đế quốc, chống chiến tranh, ủng hộ Liên Xô", "letter": "A"}, {"id": 214, "cat": "dh1_12", "q": "Hạn chế chủ yếu của Đại hội đại biểu toàn quốc lần thứ I của Đảng (3/1935) là gì?", "options": ["A. Tạm dừng toàn bộ cuộc đấu tranh chống đế quốc Pháp", "B. Đổi tên Đảng Cộng sản Đông Dương thành Đảng Lao động Việt Nam quá sớm", "C. Vẫn giữ đường lối cũ của Luận cương 10/1930, chưa đặt nhiệm vụ giải phóng dân tộc lên hàng đầu và chưa theo kịp chuyển biến tình hình thế giới", "D. Không chủ trương khôi phục hệ thống tổ chức của Đảng"], "answer": "C. Vẫn giữ đường lối cũ của Luận cương 10/1930, chưa đặt nhiệm vụ giải phóng dân tộc lên hàng đầu và chưa theo kịp chuyển biến tình hình thế giới", "letter": "C"}, {"id": 215, "cat": "dh1_12", "q": "Đại hội đại biểu toàn quốc lần thứ II của Đảng (2/1951) diễn ra vào thời gian nào, ở đâu và có bao nhiêu đại biểu chính thức?", "options": ["A. Từ 11–19/2/1951 tại xã Vinh Quang, huyện Chiêm Hóa, tỉnh Tuyên Quang; có 158 đại biểu chính thức (53 đại biểu dự khuyết)", "B. Từ 1–7/2/1951 tại Tân Trào, Tuyên Quang; có 13 đại biểu chính thức", "C. Từ 3–10/2/1951 tại Pác Bó, Cao Bằng; có 525 đại biểu chính thức", "D. Từ 19–25/2/1951 tại Hà Nội; có 1.008 đại biểu chính thức"], "answer": "A. Từ 11–19/2/1951 tại xã Vinh Quang, huyện Chiêm Hóa, tỉnh Tuyên Quang; có 158 đại biểu chính thức (53 đại biểu dự khuyết)", "letter": "A"}, {"id": 216, "cat": "dh1_12", "q": "Tại Đại hội đại biểu toàn quốc lần thứ II của Đảng (2/1951), hai chức danh lãnh đạo cao nhất của Đảng Lao động Việt Nam được bầu là ai?", "options": ["A. Hồ Chí Minh làm Chủ tịch Đảng; Trường Chinh làm Tổng Bí thư", "B. Tôn Đức Thắng làm Chủ tịch Đảng; Lê Duẩn làm Tổng Bí thư", "C. Phạm Văn Đồng làm Chủ tịch Đảng; Võ Nguyên Giáp làm Tổng Bí thư", "D. Hồ Chí Minh làm Chủ tịch Đảng; Lê Hồng Phong làm Tổng Bí thư"], "answer": "A. Hồ Chí Minh làm Chủ tịch Đảng; Trường Chinh làm Tổng Bí thư", "letter": "A"}, {"id": 217, "cat": "dh1_12", "q": "Tại Đại hội II (2/1951), lý do Đảng Cộng sản Đông Dương quyết định tách thành 3 Đảng riêng ở Việt Nam, Lào và Campuchia là gì?", "options": ["A. Do yêu cầu của Hiệp định Giơnevơ năm 1954", "B. Do sự can thiệp trực tiếp của quân đội Trung Hoa Dân quốc", "C. Do ba nước Đông Dương không còn liên minh chống thực dân Pháp", "D. Để phù hợp với đặc điểm phát triển của từng dân tộc và đáp ứng yêu cầu phát triển của cuộc kháng chiến ở mỗi nước"], "answer": "D. Để phù hợp với đặc điểm phát triển của từng dân tộc và đáp ứng yêu cầu phát triển của cuộc kháng chiến ở mỗi nước", "letter": "D"}, {"id": 218, "cat": "dh1_12", "q": "Trong Chính cương của Đảng Lao động Việt Nam thông qua tại Đại hội II (2/1951), tính chất xã hội Việt Nam được xác định gồm mấy yếu tố?", "options": ["A. Xã hội chủ nghĩa hoàn thiện", "B. Xã hội tư bản chủ nghĩa phát triển", "C. Thuộc địa và nửa phong kiến", "D. Dân chủ nhân dân, một phần thuộc địa và nửa phong kiến"], "answer": "D. Dân chủ nhân dân, một phần thuộc địa và nửa phong kiến", "letter": "D"}, {"id": 219, "cat": "dh1_12", "q": "Theo Chính cương của Đảng Lao động Việt Nam (Đại hội II, 2/1951), nền tảng của khối động lực cách mạng Việt Nam là liên minh nào?", "options": ["A. Tư sản dân tộc và tiểu địa chủ", "B. Công nhân, nông dân và lao động trí óc", "C. Nông dân, phú nông và tiểu tư sản thành thị", "D. Công nhân, tư sản dân tộc và địa chủ yêu nước"], "answer": "B. Công nhân, nông dân và lao động trí óc", "letter": "B"}, {"id": 220, "cat": "dh1_12", "q": "Đại hội đại biểu toàn quốc lần thứ III của Đảng (9/1960) họp tại Hà Nội trong thời gian nào và được Hồ Chí Minh đánh giá là Đại hội gì?", "options": ["A. Từ 5–10/9/1960 — \"Đại hội xây dựng chủ nghĩa xã hội ở miền Bắc và đấu tranh hòa bình thống nhất nước nhà\"", "B. Từ 11–19/9/1960 — \"Đại hội kháng chiến thắng lợi\"", "C. Từ 14–20/9/1960 — \"Đại hội toàn thắng của sự nghiệp giải phóng dân tộc\"", "D. Từ 15–18/9/1960 — \"Đại hội Đổi mới toàn diện đất nước\""], "answer": "A. Từ 5–10/9/1960 — \"Đại hội xây dựng chủ nghĩa xã hội ở miền Bắc và đấu tranh hòa bình thống nhất nước nhà\"", "letter": "A"}, {"id": 221, "cat": "dh1_12", "q": "Tại Đại hội đại biểu toàn quốc lần thứ III của Đảng (9/1960), ai được bầu làm Chủ tịch Đảng và ai được bầu làm Bí thư thứ nhất Ban Chấp hành Trung ương Đảng?", "options": ["A. Lê Duẩn làm Chủ tịch Đảng; Nguyễn Văn Linh làm Bí thư thứ nhất", "B. Tôn Đức Thắng làm Chủ tịch Đảng; Phạm Văn Đồng làm Bí thư thứ nhất", "C. Hồ Chí Minh làm Chủ tịch Đảng; Trường Chinh làm Bí thư thứ nhất", "D. Hồ Chí Minh làm Chủ tịch Đảng; Lê Duẩn làm Bí thư thứ nhất"], "answer": "D. Hồ Chí Minh làm Chủ tịch Đảng; Lê Duẩn làm Bí thư thứ nhất", "letter": "D"}, {"id": 222, "cat": "dh1_12", "q": "Đại hội III của Đảng (9/1960) đã quyết định lấy ngày nào hằng năm làm ngày kỷ niệm thành lập Đảng Cộng sản Việt Nam?", "options": ["A. Ngày 6 tháng 1", "B. Ngày 3 tháng 2", "C. Ngày 19 tháng 5", "D. Ngày 7 tháng 2"], "answer": "B. Ngày 3 tháng 2", "letter": "B"}, {"id": 223, "cat": "dh1_12", "q": "Đại hội đại biểu toàn quốc lần thứ IV của Đảng (12/1976) diễn ra vào thời gian nào, có bao nhiêu đại biểu và đổi chức danh người đứng đầu BCH Trung ương như thế nào?", "options": ["A. Từ 1–7/12/1976 tại Huế, 158 đại biểu; đổi tên Đảng thành Đảng Lao động Việt Nam", "B. Từ 15–18/12/1976 tại Hà Nội, 1.129 đại biểu; bầu Trường Chinh làm Tổng Bí thư", "C. Từ 27–31/12/1976 tại Sài Gòn, 525 đại biểu; giữ nguyên chức danh Bí thư thứ nhất", "D. Từ 14–20/12/1976 tại Hà Nội, 1.008 đại biểu; đổi chức danh Bí thư thứ nhất thành Tổng Bí thư và bầu Lê Duẩn giữ chức Tổng Bí thư"], "answer": "D. Từ 14–20/12/1976 tại Hà Nội, 1.008 đại biểu; đổi chức danh Bí thư thứ nhất thành Tổng Bí thư và bầu Lê Duẩn giữ chức Tổng Bí thư", "letter": "D"}, {"id": 224, "cat": "dh1_12", "q": "Đại hội IV của Đảng (12/1976) đã xác định ba đặc điểm lớn của cách mạng Việt Nam trong giai đoạn mới, trong đó đặc điểm lớn nhất là gì?", "options": ["A. Nước ta có nền công nghiệp hiện đại và tích lũy tư bản dồi dào", "B. Nước ta đang ở trong quá trình từ một xã hội mà nền kinh tế còn phổ biến là sản xuất nhỏ tiến thẳng lên chủ nghĩa xã hội, bỏ qua giai đoạn phát triển tư bản chủ nghĩa", "C. Cuộc cách mạng khoa học kỹ thuật chưa tác động đến Việt Nam", "D. Đất nước vẫn đang bị chia cắt thành hai miền với hai chế độ chính trị khác nhau"], "answer": "B. Nước ta đang ở trong quá trình từ một xã hội mà nền kinh tế còn phổ biến là sản xuất nhỏ tiến thẳng lên chủ nghĩa xã hội, bỏ qua giai đoạn phát triển tư bản chủ nghĩa", "letter": "B"}, {"id": 225, "cat": "dh1_12", "q": "Trong đường lối xây dựng chủ nghĩa xã hội do Đại hội IV (12/1976) đề ra, Đảng chủ trương tiến hành đồng thời 3 cuộc cách mạng nào và cuộc cách mạng nào là then chốt?", "options": ["A. Cách mạng hành chính, cách mạng tài chính, cách mạng giáo dục — giáo dục là then chốt", "B. Cách mạng chính trị, cách mạng quân sự, cách mạng ngoại giao — quân sự là then chốt", "C. Cách mạng nông nghiệp, cách mạng công nghiệp, cách mạng thương mại — công nghiệp là then chốt", "D. Cách mạng về quan hệ sản xuất, cách mạng khoa học – kỹ thuật, cách mạng tư tưởng và văn hóa — cách mạng khoa học – kỹ thuật là then chốt"], "answer": "D. Cách mạng về quan hệ sản xuất, cách mạng khoa học – kỹ thuật, cách mạng tư tưởng và văn hóa — cách mạng khoa học – kỹ thuật là then chốt", "letter": "D"}, {"id": 226, "cat": "dh1_12", "q": "Hạn chế mang tính chủ quan, duy ý chí của Đại hội IV (12/1976) trong dự báo thời gian xây dựng cơ sở vật chất – kỹ thuật của chủ nghĩa xã hội là gì?", "options": ["A. Chủ trương xóa bỏ hoàn toàn công nghiệp nặng trong kế hoạch 5 năm 1976–1980", "B. Dự kiến mất tới 100 năm mới hoàn thành khôi phục kinh tế sau chiến tranh", "C. Dự kiến hoàn thành quá trình đưa nền kinh tế từ sản xuất nhỏ lên sản xuất lớn XHCN trong khoảng 20 năm", "D. Từ chối mọi nguồn viện trợ từ các nước xã hội chủ nghĩa"], "answer": "C. Dự kiến hoàn thành quá trình đưa nền kinh tế từ sản xuất nhỏ lên sản xuất lớn XHCN trong khoảng 20 năm", "letter": "C"}, {"id": 227, "cat": "dh1_12", "q": "Đại hội đại biểu toàn quốc lần thứ V của Đảng (3/1982) diễn ra vào thời gian nào, có bao nhiêu đại biểu và bầu ai làm Tổng Bí thư?", "options": ["A. Từ 24–27/3/1982 tại Hà Nội, 1.176 đại biểu; bầu đồng chí Đỗ Mười làm Tổng Bí thư", "B. Từ 15–18/3/1982 tại Hà Nội, 1.129 đại biểu; bầu đồng chí Nguyễn Văn Linh làm Tổng Bí thư", "C. Từ 14–20/3/1982 tại TP. Hồ Chí Minh, 1.008 đại biểu; bầu đồng chí Trường Chinh làm Tổng Bí thư", "D. Từ 27–31/3/1982 tại Hà Nội, 1.033 đại biểu; bầu đồng chí Lê Duẩn làm Tổng Bí thư"], "answer": "D. Từ 27–31/3/1982 tại Hà Nội, 1.033 đại biểu; bầu đồng chí Lê Duẩn làm Tổng Bí thư", "letter": "D"}, {"id": 228, "cat": "dh1_12", "q": "Hai nhiệm vụ chiến lược có quan hệ mật thiết được Đại hội V của Đảng (3/1982) xác định cho cách mạng Việt Nam là gì?", "options": ["A. Phát triển công nghiệp nặng và mở rộng thương mại tự do", "B. Xây dựng thành công chủ nghĩa xã hội và bảo vệ vững chắc Tổ quốc Việt Nam xã hội chủ nghĩa", "C. Cải cách ruộng đất và xóa nạn mù chữ", "D. Giải phóng miền Nam và xây dựng miền Bắc XHCN"], "answer": "B. Xây dựng thành công chủ nghĩa xã hội và bảo vệ vững chắc Tổ quốc Việt Nam xã hội chủ nghĩa", "letter": "B"}, {"id": 229, "cat": "dh1_12", "q": "Điểm mới nổi bật trong nội dung công nghiệp hóa chặng đường đầu tiên do Đại hội V (3/1982) đề ra so với Đại hội IV (1976) là gì?", "options": ["A. Tạm dừng phát triển nông nghiệp để tập trung hoàn toàn vào dịch vụ du lịch", "B. Coi nông nghiệp là mặt trận hàng đầu, đưa nông nghiệp một bước lên sản xuất lớn XHCN, kết hợp công nghiệp nhẹ và công nghiệp nặng hợp lý", "C. Xóa bỏ hoàn toàn kinh tế quốc doanh và kinh tế tập thể", "D. Đặt công nghiệp nặng lên vị trí duy nhất trong kế hoạch 5 năm"], "answer": "B. Coi nông nghiệp là mặt trận hàng đầu, đưa nông nghiệp một bước lên sản xuất lớn XHCN, kết hợp công nghiệp nhẹ và công nghiệp nặng hợp lý", "letter": "B"}, {"id": 230, "cat": "c3", "q": "Theo Giáo trình (trang 260), sau khi Tổng Bí thư Lê Duẩn qua đời ngày 10/7/1986, Hội nghị bất thường BCH Trung ương ngày 14/7/1986 đã bầu ai giữ chức Tổng Bí thư của Đảng?", "options": ["A. Đồng chí Đỗ Mười", "B. Đồng chí Nguyễn Văn Linh", "C. Đồng chí Phạm Văn Đồng", "D. Đồng chí Trường Chinh"], "answer": "D. Đồng chí Trường Chinh", "letter": "D"}, {"id": 231, "cat": "c3", "q": "Theo Giáo trình (trang 260), ba bước đột phá tư duy kinh tế hình thành đường lối Đổi mới trước Đại hội VI diễn ra vào các mốc thời gian nào?", "options": ["A. Tháng 12/1976, tháng 3/1982 và tháng 12/1986", "B. Tháng 1/1981, tháng 4/1988 và tháng 6/1991", "C. Tháng 7/1976, tháng 2/1979 và tháng 7/1986", "D. Tháng 8/1979 (HNTW 6 khóa IV), tháng 6/1985 (HNTW 8 khóa V) và tháng 8/1986 (Hội nghị Bộ Chính trị khóa V)"], "answer": "D. Tháng 8/1979 (HNTW 6 khóa IV), tháng 6/1985 (HNTW 8 khóa V) và tháng 8/1986 (Hội nghị Bộ Chính trị khóa V)", "letter": "D"}, {"id": 232, "cat": "dh1_12", "q": "Đại hội đại biểu toàn quốc lần thứ VI của Đảng diễn ra vào ngày tháng năm nào, tại đâu và bầu ai làm Tổng Bí thư?", "options": ["A. Từ 28/6–1/7/1986 tại Hà Nội; bầu đồng chí Lê Khả Phiêu làm Tổng Bí thư", "B. Từ 14–20/12/1986 tại TP. Hồ Chí Minh; bầu đồng chí Trường Chinh làm Tổng Bí thư", "C. Từ 24–27/6/1986 tại Hà Nội; bầu đồng chí Đỗ Mười làm Tổng Bí thư", "D. Từ 15–18/12/1986 tại Hà Nội; bầu đồng chí Nguyễn Văn Linh làm Tổng Bí thư"], "answer": "D. Từ 15–18/12/1986 tại Hà Nội; bầu đồng chí Nguyễn Văn Linh làm Tổng Bí thư", "letter": "D"}, {"id": 233, "cat": "dh1_12", "q": "Bốn bài học quý báu được Đại hội VI (12/1986) rút ra từ thực tiễn xây dựng chủ nghĩa xã hội gồm những nội dung nào?", "options": ["A. Đánh nhanh thắng nhanh; tiêu thổ kháng chiến; dựa vào sức mình; lập ba thứ quân", "B. Ưu tiên công nghiệp nặng; giữ cơ chế bao cấp; tập trung kế hoạch hóa; đóng cửa thị trường", "C. Chuyển đổi số; chuyển đổi xanh; kinh tế tư nhân là động lực nhất; thu hút nhân tài", "D. Quán triệt tư tưởng \"lấy dân làm gốc\"; xuất phát từ thực tế, tôn trọng và hành động theo quy luật khách quan; kết hợp sức mạnh dân tộc với sức mạnh thời đại; chăm lo xây dựng Đảng ngang tầm nhiệm vụ"], "answer": "D. Quán triệt tư tưởng \"lấy dân làm gốc\"; xuất phát từ thực tế, tôn trọng và hành động theo quy luật khách quan; kết hợp sức mạnh dân tộc với sức mạnh thời đại; chăm lo xây dựng Đảng ngang tầm nhiệm vụ", "letter": "D"}, {"id": 234, "cat": "dh1_12", "q": "Đại hội VI (12/1986) đề ra \"Ba chương trình kinh tế lớn\" để tập trung sức người, sức của giải quyết khủng hoảng kinh tế – xã hội là gì?", "options": ["A. Lương thực – thực phẩm, hàng tiêu dùng và hàng xuất khẩu", "B. Tài chính – ngân hàng, bất động sản và du lịch biển", "C. Giao thông cao tốc, hàng không và viễn thông", "D. Công nghiệp nặng, năng lượng hạt nhân, hạ tầng số"], "answer": "A. Lương thực – thực phẩm, hàng tiêu dùng và hàng xuất khẩu", "letter": "A"}, {"id": 235, "cat": "c3", "q": "Luật Đầu tư nước ngoài tại Việt Nam được Quốc hội ban hành lần đầu tiên vào thời gian nào (ngay sau Đại hội VI)?", "options": ["A. Tháng 12/1986", "B. Tháng 7/1995", "C. Tháng 6/1991", "D. Tháng 12/1987"], "answer": "D. Tháng 12/1987", "letter": "D"}, {"id": 236, "cat": "dh1_12", "q": "Đại hội đại biểu toàn quốc lần thứ VII của Đảng diễn ra vào thời gian nào, tại đâu và bầu ai làm Tổng Bí thư?", "options": ["A. Từ 24–27/6/1991 tại Hà Nội; bầu đồng chí Đỗ Mười làm Tổng Bí thư", "B. Từ 15–18/6/1991 tại Hà Nội; bầu đồng chí Nguyễn Văn Linh làm Tổng Bí thư", "C. Từ 19–22/4/1991 tại Hà Nội; bầu đồng chí Nông Đức Mạnh làm Tổng Bí thư", "D. Từ 28/6–1/7/1991 tại Hà Nội; bầu đồng chí Lê Khả Phiêu làm Tổng Bí thư"], "answer": "A. Từ 24–27/6/1991 tại Hà Nội; bầu đồng chí Đỗ Mười làm Tổng Bí thư", "letter": "A"}, {"id": 237, "cat": "dh1_12", "q": "Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên CNXH (Cương lĩnh 1991) thông qua tại Đại hội VII xác định bao nhiêu đặc trưng cơ bản và bao nhiêu phương hướng cơ bản?", "options": ["A. 8 đặc trưng cơ bản và 8 phương hướng cơ bản", "B. 4 đặc trưng cơ bản và 5 phương hướng cơ bản", "C. 6 đặc trưng cơ bản và 7 phương hướng cơ bản", "D. 5 đặc trưng cơ bản và 6 phương hướng cơ bản"], "answer": "C. 6 đặc trưng cơ bản và 7 phương hướng cơ bản", "letter": "C"}, {"id": 238, "cat": "dh1_12", "q": "Theo Giáo trình (trang 275), Cương lĩnh 1991 xác định nguyên tắc tổ chức cơ bản của Đảng Cộng sản Việt Nam là gì?", "options": ["A. Hiệp thương đa nguyên chính trị", "B. Phân quyền tuyệt đối cho địa phương", "C. Tập trung dân chủ", "D. Bổ nhiệm hành chính từ trên xuống không qua bầu cử"], "answer": "C. Tập trung dân chủ", "letter": "C"}, {"id": 239, "cat": "dh1_12", "q": "Theo Giáo trình (trang 275), mục tiêu định lượng về GDP đến năm 2000 trong \"Chiến lược ổn định và phát triển kinh tế – xã hội đến năm 2000\" tại Đại hội VII (1991) là gì?", "options": ["A. GDP năm 2000 tăng 10% so với năm 1990", "B. GDP năm 2000 tăng gấp 5 lần so với năm 1990", "C. GDP năm 2000 tăng gấp đôi so với năm 1990", "D. GDP năm 2000 đạt 500 tỷ USD"], "answer": "C. GDP năm 2000 tăng gấp đôi so với năm 1990", "letter": "C"}, {"id": 240, "cat": "dh1_12", "q": "Lần đầu tiên Đảng chỉ ra \"4 nguy cơ\" lớn đối với cách mạng Việt Nam (tụt hậu kinh tế, chệch hướng XHCN, tham nhũng – quan liêu, \"diễn biến hòa bình\") tại Hội nghị nào?", "options": ["A. Hội nghị đại biểu toàn quốc giữa nhiệm kỳ khóa VII (1/1994)", "B. Đại hội IX của Đảng (4/2001)", "C. Hội nghị Trung ương 4 khóa XI (1/2012)", "D. Đại hội VI của Đảng (12/1986)"], "answer": "A. Hội nghị đại biểu toàn quốc giữa nhiệm kỳ khóa VII (1/1994)", "letter": "A"}, {"id": 241, "cat": "c3", "q": "Sự kiện ngoại giao quan trọng nào diễn ra ngày 11/7/1995 (trong nhiệm kỳ Đại hội VII) mở ra chương mới trong quan hệ giữa Việt Nam với phương Tây?", "options": ["A. Việt Nam chính thức gia nhập WTO", "B. Việt Nam và Hoa Kỳ chính thức thiết lập quan hệ ngoại giao (bình thường hóa quan hệ)", "C. Việt Nam ký Hiệp định thương mại tự do với EU", "D. Việt Nam và Trung Quốc bình thường hóa quan hệ"], "answer": "B. Việt Nam và Hoa Kỳ chính thức thiết lập quan hệ ngoại giao (bình thường hóa quan hệ)", "letter": "B"}, {"id": 242, "cat": "c3", "q": "Mỹ chính thức tuyên bố bãi bỏ lệnh cấm vận thương mại đối với Việt Nam vào thời gian nào?", "options": ["A. Tháng 11/1998", "B. Tháng 7/1995", "C. Tháng 2/1994", "D. Tháng 11/1991"], "answer": "C. Tháng 2/1994", "letter": "C"}, {"id": 243, "cat": "dh1_12", "q": "Đại hội đại biểu toàn quốc lần thứ VIII của Đảng (28/6–1/7/1996) đã bầu ai tiếp tục giữ chức Tổng Bí thư và đến Hội nghị nào của khóa VIII thì bầu đồng chí Lê Khả Phiêu?", "options": ["A. ĐH VIII bầu Lê Khả Phiêu; đến Hội nghị Trung ương 4 khóa VIII bầu Nông Đức Mạnh", "B. ĐH VIII bầu Đỗ Mười; đến Hội nghị Trung ương 4 khóa VIII (12/1997) bầu Lê Khả Phiêu", "C. ĐH VIII bầu Nguyễn Văn Linh; đến Hội nghị Trung ương 2 khóa VIII bầu Đỗ Mười", "D. ĐH VIII bầu Đỗ Mười; đến Hội nghị Trung ương 8 khóa VIII bầu Nông Đức Mạnh"], "answer": "B. ĐH VIII bầu Đỗ Mười; đến Hội nghị Trung ương 4 khóa VIII (12/1997) bầu Lê Khả Phiêu", "letter": "B"}, {"id": 244, "cat": "dh1_12", "q": "Đại hội VIII (6/1996) xác định mấy bài học chủ yếu qua 10 năm đổi mới (1986–1996) và mấy quan điểm về công nghiệp hóa, hiện đại hóa?", "options": ["A. 6 bài học chủ yếu qua 10 năm đổi mới và 6 quan điểm về CNH, HĐH", "B. 3 bài học qua 10 năm đổi mới và 5 quan điểm về CNH, HĐH", "C. 8 bài học qua 10 năm đổi mới và 8 quan điểm về CNH, HĐH", "D. 4 bài học qua 10 năm đổi mới và 3 quan điểm về CNH, HĐH"], "answer": "A. 6 bài học chủ yếu qua 10 năm đổi mới và 6 quan điểm về CNH, HĐH", "letter": "A"}, {"id": 245, "cat": "dh1_12", "q": "Hội nghị Trung ương 2 khóa VIII (12/1996) ban hành hai nghị quyết quan trọng khẳng định hai lĩnh vực nào là \"quốc sách hàng đầu\"?", "options": ["A. Nông nghiệp và du lịch", "B. Công nghiệp nặng và khai khoáng", "C. Thương mại điện tử và tài chính ngân hàng", "D. Giáo dục – đào tạo và khoa học – công nghệ"], "answer": "D. Giáo dục – đào tạo và khoa học – công nghệ", "letter": "D"}, {"id": 246, "cat": "dh1_12", "q": "Theo Giáo trình (trang 290), Hội nghị Trung ương 3 khóa VIII (6/1997) đã thông qua chiến lược quan trọng nào?", "options": ["A. Chiến lược phát triển kinh tế – xã hội 2011–2020", "B. Chiến lược bảo vệ Tổ quốc trong tình hình mới", "C. Chiến lược biển Việt Nam đến năm 2020", "D. Chiến lược cán bộ thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước"], "answer": "D. Chiến lược cán bộ thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước", "letter": "D"}, {"id": 247, "cat": "dh1_12", "q": "Hội nghị Trung ương 5 khóa VIII (7/1998) ban hành Nghị quyết lịch sử về lĩnh vực nào và khẳng định vị trí của lĩnh vực đó ra sao?", "options": ["A. Xây dựng và phát triển nền văn hóa Việt Nam tiên tiến, đậm đà bản sắc dân tộc — văn hóa là nền tảng tinh thần của xã hội, vừa là mục tiêu vừa là động lực thúc đẩy phát triển KT-XH", "B. Đổi mới căn bản, toàn diện giáo dục và đào tạo", "C. Cải cách chính sách bảo hiểm xã hội và tiền lương công chức", "D. Xây dựng nền kinh tế thị trường định hướng XHCN — kinh tế tư nhân là chủ đạo"], "answer": "A. Xây dựng và phát triển nền văn hóa Việt Nam tiên tiến, đậm đà bản sắc dân tộc — văn hóa là nền tảng tinh thần của xã hội, vừa là mục tiêu vừa là động lực thúc đẩy phát triển KT-XH", "letter": "A"}, {"id": 248, "cat": "dh1_12", "q": "Đại hội đại biểu toàn quốc lần thứ IX của Đảng diễn ra vào thời gian nào, tại đâu và bầu ai làm Tổng Bí thư?", "options": ["A. Từ 18–25/4/2001 tại Hà Nội; bầu đồng chí Lê Khả Phiêu làm Tổng Bí thư", "B. Từ 12–19/1/2001 tại Hà Nội; bầu đồng chí Nguyễn Phú Trọng làm Tổng Bí thư", "C. Từ 19–22/4/2001 tại Hà Nội; bầu đồng chí Nông Đức Mạnh làm Tổng Bí thư", "D. Từ 28/6–1/7/2001 tại Hà Nội; bầu đồng chí Đỗ Mười làm Tổng Bí thư"], "answer": "C. Từ 19–22/4/2001 tại Hà Nội; bầu đồng chí Nông Đức Mạnh làm Tổng Bí thư", "letter": "C"}, {"id": 249, "cat": "dh1_12", "q": "Nhận thức lý luận mới, sâu sắc của Đại hội IX (4/2001) về con đường \"bỏ qua chế độ tư bản chủ nghĩa\" đi lên chủ nghĩa xã hội là gì?", "options": ["A. Phủ định sạch trơn mọi thành tựu khoa học, công nghệ của nhân loại dưới chế độ tư bản chủ nghĩa", "B. Không cần xây dựng lực lượng sản xuất hiện đại trong thời kỳ quá độ", "C. Bỏ qua việc xác lập vị trí thống trị của quan hệ sản xuất và kiến trúc thượng tầng tư bản chủ nghĩa, nhưng tiếp thu, kế thừa những thành tựu nhân loại đạt được dưới chế độ tư bản chủ nghĩa, đặc biệt về khoa học và công nghệ", "D. Phải trải qua đầy đủ giai đoạn chủ nghĩa tư bản độc quyền rồi mới quá độ lên CNXH"], "answer": "C. Bỏ qua việc xác lập vị trí thống trị của quan hệ sản xuất và kiến trúc thượng tầng tư bản chủ nghĩa, nhưng tiếp thu, kế thừa những thành tựu nhân loại đạt được dưới chế độ tư bản chủ nghĩa, đặc biệt về khoa học và công nghệ", "letter": "C"}, {"id": 250, "cat": "dh1_12", "q": "Đại hội IX (4/2001) xác định động lực chủ yếu để phát triển đất nước là gì?", "options": ["A. Độc quyền nhà nước trong tất cả các ngành dịch vụ", "B. Phát triển nông nghiệp truyền thống dựa vào lao động thủ công", "C. Nguồn vốn vay ưu đãi nước ngoài", "D. Đại đoàn kết toàn dân trên cơ sở liên minh giữa công nhân với nông dân và trí thức do Đảng lãnh đạo"], "answer": "D. Đại đoàn kết toàn dân trên cơ sở liên minh giữa công nhân với nông dân và trí thức do Đảng lãnh đạo", "letter": "D"}, {"id": 251, "cat": "dh1_12", "q": "Hội nghị Trung ương 8 khóa IX (7/2003) ban hành nghị quyết quan trọng nào về quốc phòng – an ninh?", "options": ["A. Chiến lược bảo vệ Tổ quốc trong tình hình mới", "B. Nghị quyết về phòng, chống tham nhũng, lãng phí", "C. Chiến lược biển Việt Nam đến năm 2020", "D. Nghị quyết về công tác đối với người Việt Nam ở nước ngoài"], "answer": "A. Chiến lược bảo vệ Tổ quốc trong tình hình mới", "letter": "A"}, {"id": 252, "cat": "dh1_12", "q": "Nghị quyết số 36-NQ/TW ngày 26/3/2004 của Bộ Chính trị khóa IX đề cập đến công tác nào?", "options": ["A. Chiến lược phát triển bền vững kinh tế biển Việt Nam", "B. Đổi mới căn bản, toàn diện giáo dục và đào tạo", "C. Cải cách chính sách bảo hiểm xã hội", "D. Công tác đối với người Việt Nam ở nước ngoài (khẳng định là bộ phận không tách rời và là nguồn lực của cộng đồng dân tộc Việt Nam)"], "answer": "D. Công tác đối với người Việt Nam ở nước ngoài (khẳng định là bộ phận không tách rời và là nguồn lực của cộng đồng dân tộc Việt Nam)", "letter": "D"}, {"id": 253, "cat": "dh1_12", "q": "Đại hội đại biểu toàn quốc lần thứ X của Đảng (18–25/4/2006) bổ sung nhận thức mới nào về bản chất giai cấp của Đảng Cộng sản Việt Nam?", "options": ["A. Đảng chỉ là đội tiên phong của riêng giai cấp công nhân", "B. Đảng là tổ chức liên hiệp của các đảng phái chính trị", "C. Đảng là đội tiên phong của giai cấp công nhân, đồng thời là đội tiên phong của nhân dân lao động và của dân tộc Việt Nam", "D. Đảng chỉ đại diện cho tầng lớp trí thức và doanh nhân"], "answer": "C. Đảng là đội tiên phong của giai cấp công nhân, đồng thời là đội tiên phong của nhân dân lao động và của dân tộc Việt Nam", "letter": "C"}, {"id": 254, "cat": "dh1_12", "q": "Điểm mới đột phá về công tác xây dựng Đảng và kinh tế được thông qua tại Đại hội X (4/2006) là gì?", "options": ["A. Lần đầu đặt xây dựng, chỉnh đốn Đảng lên hàng đầu trong chủ đề Đại hội và chính thức cho phép đảng viên làm kinh tế tư nhân", "B. Lần đầu ban hành Luật Đầu tư nước ngoài tại Việt Nam", "C. Lần đầu nêu ra khái niệm Tư tưởng Hồ Chí Minh trong Cương lĩnh", "D. Lần đầu thông qua Cương lĩnh 8 đặc trưng"], "answer": "A. Lần đầu đặt xây dựng, chỉnh đốn Đảng lên hàng đầu trong chủ đề Đại hội và chính thức cho phép đảng viên làm kinh tế tư nhân", "letter": "A"}, {"id": 255, "cat": "dh1_12", "q": "Hội nghị Trung ương 4 khóa X (2/2007) đã ban hành chiến lược lớn nào về biển đảo?", "options": ["A. Chiến lược biển Việt Nam đến năm 2020 (phấn đấu trở thành quốc gia mạnh về biển, làm giàu từ biển)", "B. Quy hoạch tổng thể phát triển du lịch vùng Tây Nguyên", "C. Chiến lược bảo vệ biên giới trên bộ đến năm 2030", "D. Chiến lược phát triển bền vững kinh tế biển đến năm 2030, tầm nhìn 2045"], "answer": "A. Chiến lược biển Việt Nam đến năm 2020 (phấn đấu trở thành quốc gia mạnh về biển, làm giàu từ biển)", "letter": "A"}, {"id": 256, "cat": "dh1_12", "q": "Hội nghị Trung ương 7 khóa X (8/2008) đã ban hành Nghị quyết quan trọng về vấn đề \"Tam nông\" gồm 3 trụ cột nào?", "options": ["A. Nông dân, công nhân và trí thức", "B. Nông lâm, ngư nghiệp và thủy sản", "C. Nông trường, nông sản, nông cụ", "D. Nông nghiệp, nông dân và nông thôn"], "answer": "D. Nông nghiệp, nông dân và nông thôn", "letter": "D"}, {"id": 257, "cat": "dh1_12", "q": "Đại hội đại biểu toàn quốc lần thứ XI của Đảng diễn ra vào thời gian nào, tại đâu và bầu ai làm Tổng Bí thư?", "options": ["A. Từ 25/1–1/2/2011 tại TP. Hồ Chí Minh; bầu đồng chí Trương Tấn Sang làm Tổng Bí thư", "B. Từ 12–19/1/2011 tại Hà Nội; bầu đồng chí Nguyễn Phú Trọng làm Tổng Bí thư", "C. Từ 18–25/4/2011 tại Hà Nội; bầu đồng chí Nông Đức Mạnh làm Tổng Bí thư", "D. Từ 20–28/1/2011 tại Hà Nội; bầu đồng chí Nguyễn Tấn Dũng làm Tổng Bí thư"], "answer": "B. Từ 12–19/1/2011 tại Hà Nội; bầu đồng chí Nguyễn Phú Trọng làm Tổng Bí thư", "letter": "B"}, {"id": 258, "cat": "dh1_12", "q": "So với Cương lĩnh 1991 (6 đặc trưng), Cương lĩnh xây dựng đất nước (bổ sung, phát triển năm 2011) tại Đại hội XI xác định xã hội XHCN có mấy đặc trưng cơ bản và bổ sung đặc trưng bao trùm nào ở vị trí đầu tiên?", "options": ["A. 10 đặc trưng cơ bản; bổ sung đặc trưng nền kinh tế bao cấp hiện đại", "B. 6 đặc trưng cơ bản; giữ nguyên toàn bộ câu chữ của Cương lĩnh 1991", "C. 7 đặc trưng cơ bản; xóa bỏ đặc trưng về văn hóa dân tộc", "D. 8 đặc trưng cơ bản; bổ sung đặc trưng \"Dân giàu, nước mạnh, dân chủ, công bằng, văn minh\" và đặc trưng \"Nhà nước pháp quyền xã hội chủ nghĩa của nhân dân, do nhân dân, vì nhân dân do Đảng Cộng sản lãnh đạo\""], "answer": "D. 8 đặc trưng cơ bản; bổ sung đặc trưng \"Dân giàu, nước mạnh, dân chủ, công bằng, văn minh\" và đặc trưng \"Nhà nước pháp quyền xã hội chủ nghĩa của nhân dân, do nhân dân, vì nhân dân do Đảng Cộng sản lãnh đạo\"", "letter": "D"}, {"id": 259, "cat": "dh1_12", "q": "Cương lĩnh bổ sung, phát triển năm 2011 (Đại hội XI) xác định bao nhiêu phương hướng cơ bản và bao nhiêu mối quan hệ lớn cần nắm vững, giải quyết tốt?", "options": ["A. 10 phương hướng cơ bản và 10 mối quan hệ lớn", "B. 6 phương hướng cơ bản và 6 mối quan hệ lớn", "C. 8 phương hướng cơ bản và 8 mối quan hệ lớn", "D. 5 phương hướng cơ bản và 4 mối quan hệ lớn"], "answer": "C. 8 phương hướng cơ bản và 8 mối quan hệ lớn", "letter": "C"}, {"id": 260, "cat": "dh1_12", "q": "Chiến lược phát triển kinh tế – xã hội 2011–2020 thông qua tại Đại hội XI (1/2011) lần đầu tiên xác định \"Ba đột phá chiến lược\" nào?", "options": ["A. Cải cách ruộng đất; phát triển công nghiệp nặng; xóa nạn mù chữ", "B. Hoàn thiện thể chế KTTT định hướng XHCN; phát triển nhanh nguồn nhân lực (nhất là nhân lực chất lượng cao); xây dựng hệ thống kết cấu hạ tầng đồng bộ", "C. Khoán 100; cải cách giá – lương – tiền; mở rộng quyền tự chủ xí nghiệp", "D. Gia nhập ASEAN; gia nhập APEC; gia nhập WTO"], "answer": "B. Hoàn thiện thể chế KTTT định hướng XHCN; phát triển nhanh nguồn nhân lực (nhất là nhân lực chất lượng cao); xây dựng hệ thống kết cấu hạ tầng đồng bộ", "letter": "B"}, {"id": 261, "cat": "dh1_12", "q": "Theo Giáo trình (trang 355), Hội nghị Trung ương 4 khóa XI ban hành Nghị quyết số 12-NQ/TW ngày 16/1/2012 về nội dung gì và xác định vấn đề nào là \"trọng tâm, xuyên suốt và cấp bách nhất\"?", "options": ["A. \"Chiến lược kinh tế biển\" — đánh bắt xa bờ là cấp bách nhất", "B. \"Đổi mới căn bản giáo dục\" — phổ cập mầm non là cấp bách nhất", "C. \"Một số vấn đề cấp bách về xây dựng Đảng hiện nay\" — vấn đề thứ nhất (kiên quyết đấu tranh ngăn chặn, đẩy lùi tình trạng suy thoái về tư tưởng chính trị, đạo đức, lối sống của một bộ phận không nhỏ cán bộ, đảng viên) là trọng tâm, xuyên suốt và cấp bách nhất", "D. \"Cải cách tiền lương\" — tăng lương tối thiểu là cấp bách nhất"], "answer": "C. \"Một số vấn đề cấp bách về xây dựng Đảng hiện nay\" — vấn đề thứ nhất (kiên quyết đấu tranh ngăn chặn, đẩy lùi tình trạng suy thoái về tư tưởng chính trị, đạo đức, lối sống của một bộ phận không nhỏ cán bộ, đảng viên) là trọng tâm, xuyên suốt và cấp bách nhất", "letter": "C"}, {"id": 262, "cat": "dh1_12", "q": "Hội nghị Trung ương 8 khóa XI (11/2013) ban hành Nghị quyết số 29-NQ/TW về chủ trương lớn nào trong lĩnh vực giáo dục?", "options": ["A. Đổi mới căn bản, toàn diện giáo dục và đào tạo, đáp ứng yêu cầu công nghiệp hóa, hiện đại hóa trong điều kiện KTTT định hướng XHCN và hội nhập quốc tế", "B. Xóa mù chữ theo phong trào Bình dân học vụ", "C. Giảm thời gian học phổ thông xuống còn 9 năm", "D. Chuyển toàn bộ các trường công lập sang mô hình trường tư thục"], "answer": "A. Đổi mới căn bản, toàn diện giáo dục và đào tạo, đáp ứng yêu cầu công nghiệp hóa, hiện đại hóa trong điều kiện KTTT định hướng XHCN và hội nhập quốc tế", "letter": "A"}, {"id": 263, "cat": "dh1_12", "q": "Hội nghị Trung ương 9 khóa XI (5/2014) ban hành Nghị quyết số 33-NQ/TW về nội dung trọng tâm nào?", "options": ["A. Cải cách chính sách bảo hiểm xã hội", "B. Chiến lược phát triển công nghiệp ô tô đến năm 2030", "C. Xây dựng và phát triển văn hóa, con người Việt Nam đáp ứng yêu cầu phát triển bền vững đất nước", "D. Hoàn thiện thể chế quản lý đất đai"], "answer": "C. Xây dựng và phát triển văn hóa, con người Việt Nam đáp ứng yêu cầu phát triển bền vững đất nước", "letter": "C"}, {"id": 264, "cat": "dh1_12", "q": "Đại hội đại biểu toàn quốc lần thứ XII của Đảng diễn ra vào thời gian nào, tại đâu và mang khẩu hiệu hành động gì?", "options": ["A. Từ 18–25/4/2016 tại TP. Hồ Chí Minh; khẩu hiệu \"Dân giàu – Nước mạnh – Công bằng – Văn minh\"", "B. Từ 20–28/1/2016 tại Hà Nội; khẩu hiệu \"Đoàn kết – Dân chủ – Kỷ cương – Đổi mới\"", "C. Từ 25/1–1/2/2016 tại Hà Nội; khẩu hiệu \"Đoàn kết – Dân chủ – Kỷ cương – Đột phá – Phát triển\"", "D. Từ 12–19/1/2016 tại Hà Nội; khẩu hiệu \"Đoàn kết – Dân chủ – Kỷ cương – Sáng tạo – Phát triển\""], "answer": "B. Từ 20–28/1/2016 tại Hà Nội; khẩu hiệu \"Đoàn kết – Dân chủ – Kỷ cương – Đổi mới\"", "letter": "B"}, {"id": 265, "cat": "dh1_12", "q": "Hội nghị Trung ương 4 khóa XII (10/2016) ban hành Nghị quyết số 04-NQ/TW về xây dựng, chỉnh đốn Đảng đã chỉ rõ bao nhiêu biểu hiện suy thoái về tư tưởng chính trị, đạo đức, lối sống và \"tự diễn biến\", \"tự chuyển hóa\"?", "options": ["A. 27 biểu hiện", "B. 10 biểu hiện", "C. 18 biểu hiện", "D. 36 biểu hiện"], "answer": "A. 27 biểu hiện", "letter": "A"}, {"id": 266, "cat": "dh1_12", "q": "Hội nghị Trung ương 5 khóa XII (5/2017) đã đánh dấu bước tiến nhận thức quan trọng nào về vai trò của kinh tế tư nhân?", "options": ["A. Hạn chế quy mô doanh nghiệp tư nhân trong lĩnh vực dịch vụ", "B. Coi kinh tế tư nhân giữ vai trò chủ đạo thay thế kinh tế nhà nước", "C. Coi kinh tế tư nhân chỉ là thành phần phụ trợ tạm thời", "D. Phát triển kinh tế tư nhân trở thành một động lực quan trọng của nền kinh tế thị trường định hướng xã hội chủ nghĩa"], "answer": "D. Phát triển kinh tế tư nhân trở thành một động lực quan trọng của nền kinh tế thị trường định hướng xã hội chủ nghĩa", "letter": "D"}, {"id": 267, "cat": "dh14", "q": "So sánh nhận thức về vai trò của kinh tế tư nhân giữa Hội nghị Trung ương 5 khóa XII (5/2017) và Đại hội XIV (1/2026)?", "options": ["A. TW 5 khóa XII xác định là \"một động lực quan trọng\"; Đại hội XIV nâng tầm khẳng định kinh tế tư nhân là \"động lực quan trọng nhất\"", "B. TW 5 khóa XII coi là động lực quan trọng nhất; Đại hội XIV giảm vai trò xuống thứ yếu", "C. Cả hai đều xác định kinh tế tư nhân giữ vai trò chủ đạo tuyệt đối", "D. TW 5 khóa XII cấm kinh tế tư nhân; Đại hội XIV mới cho phép hoạt động"], "answer": "A. TW 5 khóa XII xác định là \"một động lực quan trọng\"; Đại hội XIV nâng tầm khẳng định kinh tế tư nhân là \"động lực quan trọng nhất\"", "letter": "A"}, {"id": 268, "cat": "dh1_12", "q": "Hội nghị Trung ương 6 khóa XII (10/2017) ban hành Nghị quyết số 18-NQ/TW tập trung giải quyết vấn đề lớn nào của hệ thống chính trị?", "options": ["A. Xây dựng Chiến lược bảo vệ Tổ quốc trong tình hình mới", "B. Tiếp tục đổi mới, sắp xếp tổ chức bộ máy của hệ thống chính trị tinh gọn, hoạt động hiệu lực, hiệu quả", "C. Phổ cập giáo dục mầm non cho trẻ 5 tuổi", "D. Cải cách thuế xuất nhập khẩu khu vực ASEAN"], "answer": "B. Tiếp tục đổi mới, sắp xếp tổ chức bộ máy của hệ thống chính trị tinh gọn, hoạt động hiệu lực, hiệu quả", "letter": "B"}, {"id": 269, "cat": "dh1_12", "q": "Hội nghị Trung ương 8 khóa XII (22/10/2018) ban hành Nghị quyết số 36-NQ/TW về chiến lược nào?", "options": ["A. Chiến lược phát triển bền vững kinh tế biển Việt Nam đến năm 2030, tầm nhìn đến năm 2045", "B. Chiến lược phát triển công nghiệp bán dẫn đến năm 2040", "C. Công tác đối với người Việt Nam ở nước ngoài", "D. Chiến lược ổn định kinh tế – xã hội đến năm 2000"], "answer": "A. Chiến lược phát triển bền vững kinh tế biển Việt Nam đến năm 2030, tầm nhìn đến năm 2045", "letter": "A"}, {"id": 270, "cat": "dh13", "q": "So sánh chuỗi phương châm hành động của ba kỳ Đại hội liên tiếp XII (2016), XIII (2021) và XIV (2026)?", "options": ["A. ĐH XII: \"...Sáng tạo\" → ĐH XIII: \"...Đột phá\" → ĐH XIV: \"...Đổi mới\"", "B. Cả ba kỳ Đại hội XII, XIII, XIV đều dùng chung một phương châm duy nhất", "C. ĐH XII: \"...Đột phá\" → ĐH XIII: \"...Đổi mới\" → ĐH XIV: \"...Sáng tạo\"", "D. ĐH XII: \"...Đổi mới\" → ĐH XIII: \"...Sáng tạo – Phát triển\" → ĐH XIV: \"...Đột phá – Phát triển\""], "answer": "D. ĐH XII: \"...Đổi mới\" → ĐH XIII: \"...Sáng tạo – Phát triển\" → ĐH XIV: \"...Đột phá – Phát triển\"", "letter": "D"}, {"id": 271, "cat": "dh1_12", "q": "Sự phát triển trong đường lối đối ngoại của Đảng qua các kỳ Đại hội VII (1991), IX (2001) và XI (2011) thể hiện rõ nhất qua sự bổ sung nào?", "options": ["A. Đường lối đối ngoại không có bất kỳ bổ sung nào từ năm 1991 đến 2011", "B. ĐH VII: \"đối tác chiến lược\" → ĐH IX: \"thành viên WTO\" → ĐH XI: \"bình thường hóa quan hệ\"", "C. ĐH VII: \"đóng cửa tự chủ\" → ĐH IX: \"chỉ quan hệ Đông Nam Á\" → ĐH XI: \"muốn là bạn\"", "D. ĐH VII: \"muốn là bạn\" → ĐH IX: \"sẵn sàng là bạn, đối tác tin cậy\" → ĐH XI: \"là bạn, đối tác tin cậy và thành viên có trách nhiệm trong cộng đồng quốc tế\""], "answer": "D. ĐH VII: \"muốn là bạn\" → ĐH IX: \"sẵn sàng là bạn, đối tác tin cậy\" → ĐH XI: \"là bạn, đối tác tin cậy và thành viên có trách nhiệm trong cộng đồng quốc tế\"", "letter": "D"}, {"id": 272, "cat": "dh1_12", "q": "Ba kỳ Đại hội nào của Đảng đã ban hành hoặc bổ sung, phát triển các bản Cương lĩnh mang tầm chiến lược của Đảng từ năm 1930 đến nay (ngoài Cương lĩnh 2/1930 và Luận cương 10/1930)?", "options": ["A. Đại hội III (1960), Đại hội V (1982), Đại hội X (2006)", "B. Đại hội VIII (1996), Đại hội IX (2001), Đại hội XII (2016)", "C. Đại hội II (1951 — Chính cương ĐLĐVN), Đại hội VII (1991 — Cương lĩnh 1991), Đại hội XI (2011 — Cương lĩnh bổ sung, phát triển 2011)", "D. Đại hội I (1935), Đại hội IV (1976), Đại hội VI (1986)"], "answer": "C. Đại hội II (1951 — Chính cương ĐLĐVN), Đại hội VII (1991 — Cương lĩnh 1991), Đại hội XI (2011 — Cương lĩnh bổ sung, phát triển 2011)", "letter": "C"}, {"id": 273, "cat": "dh1_12", "q": "Sự thay đổi tên gọi chính thức của Đảng qua các mốc lịch sử từ 1930 đến 1976 theo đúng trình tự thời gian là gì?", "options": ["A. Đảng Cộng sản Việt Nam (2/1930) → Hội nghiên cứu CN Mác (1951) → Đảng Lao động Việt Nam (1976)", "B. Đảng Cộng sản Việt Nam (2/1930) → Đảng Cộng sản Đông Dương (10/1930) → Đảng Lao động Việt Nam (2/1951) → Đảng Cộng sản Việt Nam (12/1976)", "C. Đảng Cộng sản Đông Dương (2/1930) → Đảng Cộng sản Việt Nam (10/1930) → Đảng Lao động Việt Nam (1951)", "D. Đảng Lao động Việt Nam (2/1930) → Đảng Cộng sản Đông Dương (1945) → Đảng Cộng sản Việt Nam (1954)"], "answer": "B. Đảng Cộng sản Việt Nam (2/1930) → Đảng Cộng sản Đông Dương (10/1930) → Đảng Lao động Việt Nam (2/1951) → Đảng Cộng sản Việt Nam (12/1976)", "letter": "B"}, {"id": 274, "cat": "dh14", "q": "Thứ tự đúng của các Tổng Bí thư (hoặc Bí thư thứ nhất) được bầu tại các kỳ Đại hội từ Đại hội V (1982) đến Đại hội XIV (2026) là gì?", "options": ["A. Lê Duẩn (ĐH V, VI) → Nguyễn Văn Linh (ĐH VII) → Đỗ Mười (ĐH VIII) → Nông Đức Mạnh (ĐH IX, X, XI) → Nguyễn Phú Trọng (ĐH XII, XIII) → Tô Lâm (ĐH XIV)", "B. Trường Chinh (ĐH V) → Đỗ Mười (ĐH VI) → Nguyễn Văn Linh (ĐH VII) → Lê Khả Phiêu (ĐH VIII) → Nông Đức Mạnh (ĐH IX, X) → Nguyễn Phú Trọng (ĐH XI–XIII)", "C. Phạm Văn Đồng (ĐH V) → Nguyễn Văn Linh (ĐH VI) → Lê Khả Phiêu (ĐH VII) → Đỗ Mười (ĐH VIII) → Nông Đức Mạnh (ĐH IX, X) → Tô Lâm (ĐH XI–XIV)", "D. Lê Duẩn (ĐH V) → Nguyễn Văn Linh (ĐH VI) → Đỗ Mười (ĐH VII, VIII; TW 4 khóa VIII: Lê Khả Phiêu) → Nông Đức Mạnh (ĐH IX, X) → Nguyễn Phú Trọng (ĐH XI, XII, XIII) → Tô Lâm (ĐH XIV)"], "answer": "D. Lê Duẩn (ĐH V) → Nguyễn Văn Linh (ĐH VI) → Đỗ Mười (ĐH VII, VIII; TW 4 khóa VIII: Lê Khả Phiêu) → Nông Đức Mạnh (ĐH IX, X) → Nguyễn Phú Trọng (ĐH XI, XII, XIII) → Tô Lâm (ĐH XIV)", "letter": "D"}, {"id": 275, "cat": "c1", "q": "Năm 1919, Nguyễn Ái Quốc thay mặt những người Việt Nam yêu nước tại Pháp gửi bản \"Yêu sách của nhân dân An Nam\" (gồm 8 điểm) tới hội nghị quốc tế nào?", "options": ["A. Hội nghị Giơnevơ về Đông Dương", "B. Hội nghị Quốc tế Cộng sản lần thứ V", "C. Hội nghị Ianta của ba nước Đồng minh", "D. Hội nghị hòa bình Vécxây (Versailles)"], "answer": "D. Hội nghị hòa bình Vécxây (Versailles)", "letter": "D"}, {"id": 276, "cat": "c1", "q": "Phong trào \"Vô sản hóa\" được Hội Việt Nam Cách mạng Thanh niên phát động vào năm 1928 có mục đích chính là gì?", "options": ["A. Đưa toàn bộ nông dân ra thành thị làm thương nghiệp", "B. Tổ chức tổng khởi nghĩa vũ trang ngay trong năm 1928", "C. Thành lập các xí nghiệp tư bản của người Việt Nam", "D. Đưa cán bộ, hội viên vào các nhà máy, hầm mỏ, đồn điền cùng lao động với công nhân để rèn luyện lập trường vô sản và truyền bá chủ nghĩa Mác – Lênin"], "answer": "D. Đưa cán bộ, hội viên vào các nhà máy, hầm mỏ, đồn điền cùng lao động với công nhân để rèn luyện lập trường vô sản và truyền bá chủ nghĩa Mác – Lênin", "letter": "D"}, {"id": 277, "cat": "c1", "q": "Tờ báo \"Thanh niên\" — cơ quan ngôn luận của Hội Việt Nam Cách mạng Thanh niên, đánh dấu sự ra đời của báo chí cách mạng Việt Nam — phát hành số đầu tiên vào ngày nào?", "options": ["A. Ngày 2/9/1925", "B. Ngày 21/6/1925", "C. Ngày 19/5/1925", "D. Ngày 3/2/1925"], "answer": "B. Ngày 21/6/1925", "letter": "B"}, {"id": 278, "cat": "c1", "q": "Năm 1943, Đảng Cộng sản Đông Dương ban hành \"Đề cương về văn hóa Việt Nam\" do Tổng Bí thư Trường Chinh soạn thảo, xác định ba nguyên tắc vận động văn hóa nào?", "options": ["A. Độc lập – Tự do – Hạnh phúc", "B. Tiên tiến – Hiện đại – Hội nhập", "C. Dân tộc – Khoa học – Đại chúng", "D. Truyền thống – Sáng tạo – Phát triển"], "answer": "C. Dân tộc – Khoa học – Đại chúng", "letter": "C"}, {"id": 279, "cat": "c1", "q": "Tác phẩm \"Tự chỉ trích\" xuất bản tháng 7/1939 góp phần đấu tranh tự phê bình, phê bình trong nội bộ Đảng do Tổng Bí thư nào biên soạn?", "options": ["A. Trường Chinh", "B. Nguyễn Văn Cừ", "C. Lê Hồng Phong", "D. Trần Phú"], "answer": "B. Nguyễn Văn Cừ", "letter": "B"}, {"id": 280, "cat": "c1", "q": "Lãnh tụ Nguyễn Ái Quốc trực tiếp trở về nước (tại Pác Bó, Cao Bằng) để lãnh đạo phong trào cách mạng Việt Nam sau 30 năm bôn ba vào ngày tháng năm nào?", "options": ["A. Ngày 19/5/1941", "B. Ngày 19/5/1940", "C. Ngày 28/1/1941", "D. Ngày 22/12/1944"], "answer": "C. Ngày 28/1/1941", "letter": "C"}, {"id": 281, "cat": "c1", "q": "Tiến trình giành chính quyền tại ba trung tâm đô thị lớn nhất cả nước trong Cách mạng Tháng Tám 1945 diễn ra theo thứ tự thời gian nào?", "options": ["A. Huế (19/8) → Hà Nội (23/8) → Sài Gòn (25/8)", "B. Hà Nội (19/8) → Huế (23/8) → Sài Gòn (25/8)", "C. Sài Gòn (19/8) → Hà Nội (23/8) → Huế (25/8)", "D. Hà Nội (14/8) → Sài Gòn (19/8) → Huế (28/8)"], "answer": "B. Hà Nội (19/8) → Huế (23/8) → Sài Gòn (25/8)", "letter": "B"}, {"id": 282, "cat": "c1", "q": "Vua Bảo Đại tuyên bố thoái vị, chấm dứt hoàn toàn chế độ quân chủ phong kiến hàng nghìn năm ở Việt Nam vào ngày tháng năm nào?", "options": ["A. Ngày 30/8/1945", "B. Ngày 19/8/1945", "C. Ngày 2/9/1945", "D. Ngày 25/8/1945"], "answer": "A. Ngày 30/8/1945", "letter": "A"}, {"id": 283, "cat": "c2", "q": "Trong cuộc Tổng tuyển cử đầu tiên ngày 6/1/1946 bầu Quốc hội khóa I, tinh thần dân chủ của chế độ mới thể hiện rõ nhất ở điểm nào?", "options": ["A. Mọi công dân Việt Nam từ 18 tuổi trở lên không phân biệt nam nữ, giàu nghèo, dân tộc, tôn giáo đều có quyền bầu cử theo nguyên tắc phổ thông, bình đẳng, trực tiếp và bỏ phiếu kín", "B. Chỉ những người có tài sản lớn mới được quyền bầu cử", "C. Chỉ tổ chức bầu cử tại các tỉnh miền Bắc", "D. Quốc hội do các nước Đồng minh chỉ định thành phần"], "answer": "A. Mọi công dân Việt Nam từ 18 tuổi trở lên không phân biệt nam nữ, giàu nghèo, dân tộc, tôn giáo đều có quyền bầu cử theo nguyên tắc phổ thông, bình đẳng, trực tiếp và bỏ phiếu kín", "letter": "A"}, {"id": 284, "cat": "c2", "q": "Điểm khác biệt cốt lõi giữa phương châm tác chiến ban đầu \"đánh nhanh, thắng nhanh\" với quyết định chuyển sang \"đánh chắc, tiến chắc\" của Đại tướng Võ Nguyên Giáp tại chiến dịch Điện Biên Phủ (1954) có ý nghĩa gì?", "options": ["A. Tránh được tổn thất lớn do tập đoàn cứ điểm của địch quá mạnh, bảo đảm chắc thắng cho chiến dịch lịch sử Điện Biên Phủ", "B. Chuyển toàn bộ chiến dịch sang đấu tranh chính trị hòa bình", "C. Cho phép quân Pháp rút lui an toàn về Hà Nội", "D. Kéo dài chiến tranh sang năm 1956"], "answer": "A. Tránh được tổn thất lớn do tập đoàn cứ điểm của địch quá mạnh, bảo đảm chắc thắng cho chiến dịch lịch sử Điện Biên Phủ", "letter": "A"}, {"id": 285, "cat": "c2", "q": "Đường lối đánh Mỹ nổi tiếng trong Thơ chúc Tết Xuân Kỷ Dậu (1969) của Chủ tịch Hồ Chí Minh xác định hai bước thắng lợi liên hoàn nào?", "options": ["A. \"Đánh cho Pháp cút, đánh cho Nhật nhào\"", "B. \"Vừa đánh vừa đàm, giữ nguyên giới tuyến\"", "C. \"Hòa để tiến, trường kỳ kháng chiến\"", "D. \"Đánh cho Mỹ cút, đánh cho ngụy nhào\""], "answer": "D. \"Đánh cho Mỹ cút, đánh cho ngụy nhào\"", "letter": "D"}, {"id": 286, "cat": "c2", "q": "Cuộc tập kích chiến lược bằng máy bay B-52 của Mỹ vào Hà Nội, Hải Phòng cuối tháng 12/1972 (chiến thắng \"Điện Biên Phủ trên không\") kéo dài bao nhiêu ngày đêm?", "options": ["A. 56 ngày đêm (13/3–7/5/1972)", "B. 7 ngày đêm (20–27/12/1972)", "C. 30 ngày đêm (1–30/12/1972)", "D. 12 ngày đêm (18–29/12/1972)"], "answer": "D. 12 ngày đêm (18–29/12/1972)", "letter": "D"}, {"id": 287, "cat": "c2", "q": "Chiến dịch Điện Biên Phủ năm 1954 diễn ra liên tục trong bao nhiêu ngày đêm (từ 13/3 đến 7/5/1954)?", "options": ["A. 12 ngày đêm", "B. 75 ngày đêm", "C. 56 ngày đêm", "D. 30 ngày đêm"], "answer": "C. 56 ngày đêm", "letter": "C"}, {"id": 288, "cat": "c2", "q": "Trong cuộc kháng chiến chống Mỹ, chiến thắng Ấp Bắc (1/1963) đã mở đầu đánh bại hai chiến thuật quân sự mới nào của Mỹ – Ngụy trong \"Chiến tranh đặc biệt\"?", "options": ["A. \"Đánh điểm diệt viện\" và \"vây lấn\"", "B. \"Đánh nhanh thắng nhanh\" và \"vết dầu loang\"", "C. \"Trực thăng vận\" và \"thiết xa vận\"", "D. \"Chiến tranh phá hoại bằng B-52\" và \"phong tỏa cảng biển\""], "answer": "C. \"Trực thăng vận\" và \"thiết xa vận\"", "letter": "C"}, {"id": 289, "cat": "c2", "q": "Hội nghị nào vào tháng 9/1956 đã thẳng thắn kiểm điểm, công khai thừa nhận và đề ra chủ trương kiên quyết sửa chữa những sai lầm trong cải cách ruộng đất và chỉnh đốn tổ chức ở miền Bắc?", "options": ["A. Hội nghị Trung ương 15 khóa II (1/1959)", "B. Hội nghị Trung ương 10 khóa II (9/1956)", "C. Hội nghị Trung ương 6 khóa IV (8/1979)", "D. Đại hội đại biểu toàn quốc lần thứ II (2/1951)"], "answer": "B. Hội nghị Trung ương 10 khóa II (9/1956)", "letter": "B"}, {"id": 290, "cat": "c3", "q": "Hội nghị Bộ Chính trị đầu năm 1975 (sau chiến thắng Phước Long) và cuộc họp Bộ Chính trị ngày 18/3/1975 đã điều chỉnh kế hoạch giải phóng miền Nam như thế nào?", "options": ["A. Tạm hoãn chiến dịch Tây Nguyên để đàm phán lại Hiệp định Paris", "B. Từ kế hoạch cơ bản giải phóng miền Nam trong hai năm 1975–1976 chuyển sang quyết tâm giải phóng miền Nam ngay trong năm 1975", "C. Từ kế hoạch giải phóng miền Nam trong 5 năm rút xuống 2 năm", "D. Kéo dài kế hoạch giải phóng miền Nam sang năm 1977"], "answer": "B. Từ kế hoạch cơ bản giải phóng miền Nam trong hai năm 1975–1976 chuyển sang quyết tâm giải phóng miền Nam ngay trong năm 1975", "letter": "B"}, {"id": 291, "cat": "c2", "q": "Cuộc Tổng tiến công và nổi dậy mùa Xuân 1975 thực hiện phương châm tác chiến thần tốc nào do Đại tướng Võ Nguyên Giáp truyền đạt?", "options": ["A. \"Vừa sản xuất vừa chiến đấu\"", "B. \"Thần tốc, thần tốc hơn nữa; táo bạo, táo bạo hơn nữa\"", "C. \"Đánh chắc, tiến chắc, chắc thắng mới đánh\"", "D. \"Tiêu thổ kháng chiến, trường kỳ tự lực\""], "answer": "B. \"Thần tốc, thần tốc hơn nữa; táo bạo, táo bạo hơn nữa\"", "letter": "B"}, {"id": 292, "cat": "dh1_12", "q": "Tại Đại hội VII (6/1991), Cương lĩnh 1991 lần đầu tiên bổ sung yếu tố tư tưởng nào đặt ngang hàng với Chủ nghĩa Mác – Lênin làm nền tảng tư tưởng và kim chỉ nam cho hành động của Đảng?", "options": ["A. Chủ nghĩa dân tộc tư sản", "B. Tư tưởng cải cách Minh Trị", "C. Tư tưởng Hồ Chí Minh", "D. Lý thuyết kinh tế tự do mới"], "answer": "C. Tư tưởng Hồ Chí Minh", "letter": "C"}, {"id": 293, "cat": "dh1_12", "q": "Tại Đại hội VIII (6/1996), Đảng nhận định đất nước ta bước sang thời kỳ phát triển mới nào sau 10 năm đổi mới?", "options": ["A. Thời kỳ khôi phục kinh tế sau chiến tranh", "B. Thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước", "C. Thời kỳ thực hiện cơ chế tập trung quan liêu bao cấp", "D. Thời kỳ hoàn thành cải tạo xã hội chủ nghĩa đối với tư sản"], "answer": "B. Thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước", "letter": "B"}, {"id": 294, "cat": "dh1_12", "q": "Đại hội VIII (6/1996) xác định yếu tố nào vừa là mục tiêu, vừa là động lực của phát triển kinh tế – xã hội và xác định yếu tố nào là động lực của CNH–HĐH?", "options": ["A. Xuất khẩu nông sản thô là mục tiêu; vốn vay nước ngoài là động lực", "B. Phát huy nguồn lực con người là yếu tố cơ bản cho sự phát triển nhanh và bền vững; khoa học và công nghệ là động lực của CNH, HĐH", "C. Cơ chế bao cấp là mục tiêu; độc quyền nhà nước là động lực", "D. Tài nguyên là mục tiêu; lao động giản đơn là động lực"], "answer": "B. Phát huy nguồn lực con người là yếu tố cơ bản cho sự phát triển nhanh và bền vững; khoa học và công nghệ là động lực của CNH, HĐH", "letter": "B"}, {"id": 295, "cat": "dh1_12", "q": "Tại Đại hội X (4/2006), mục tiêu tổng quát của công nghiệp hóa, hiện đại hóa gắn với kinh tế tri thức nhằm tạo nền tảng đưa Việt Nam đạt mốc nào vào năm 2020?", "options": ["A. Hoàn thành 100% quá trình đô thị hóa nông thôn", "B. Trở thành nước phát triển có thu nhập cao nhất châu Á", "C. Chấm dứt hoàn toàn hoạt động sản xuất nông nghiệp", "D. Cơ bản trở thành nước công nghiệp theo hướng hiện đại"], "answer": "D. Cơ bản trở thành nước công nghiệp theo hướng hiện đại", "letter": "D"}, {"id": 296, "cat": "dh1_12", "q": "Hội nghị Trung ương 5 khóa IX (3/2002) đã thống nhất nhận thức quan trọng nào về vai trò của kinh tế tư nhân?", "options": ["A. Kinh tế tư nhân chỉ được hoạt động trong lĩnh vực nông nghiệp", "B. Kinh tế tư nhân cần thu hẹp dần để xóa bỏ hoàn toàn", "C. Kinh tế tư nhân giữ vai trò chủ đạo thay cho kinh tế nhà nước", "D. Kinh tế tư nhân là bộ phận cấu thành quan trọng của nền kinh tế quốc dân, phát triển rộng khắp và đóng góp quan trọng vào phát triển kinh tế"], "answer": "D. Kinh tế tư nhân là bộ phận cấu thành quan trọng của nền kinh tế quốc dân, phát triển rộng khắp và đóng góp quan trọng vào phát triển kinh tế", "letter": "D"}, {"id": 297, "cat": "dh1_12", "q": "Hội nghị Trung ương 7 khóa XII (5/2018) đã ban hành ba nghị quyết cải cách quan trọng về những lĩnh vực nào?", "options": ["A. Khoán 100, Khoán 10 và cải cách giá – lương – tiền", "B. Kinh tế biển (NQ 36), giáo dục (NQ 29) và văn hóa (NQ 33)", "C. Phòng chống tham nhũng (NQ 04), kiểm tra giám sát (NQ 14) và người Việt ở nước ngoài (NQ 36)", "D. Công tác cán bộ (NQ 26), cải cách chính sách tiền lương (NQ 27) và cải cách chính sách bảo hiểm xã hội (NQ 28)"], "answer": "D. Công tác cán bộ (NQ 26), cải cách chính sách tiền lương (NQ 27) và cải cách chính sách bảo hiểm xã hội (NQ 28)", "letter": "D"}, {"id": 298, "cat": "c3", "q": "Sự kiện đối ngoại nào vào tháng 11/1998 đánh dấu bước tiến mới của Việt Nam trong hội nhập kinh tế khu vực châu Á – Thái Bình Dương?", "options": ["A. Việt Nam gia nhập Hiệp hội các quốc gia Đông Nam Á (ASEAN)", "B. Việt Nam trở thành Ủy viên không thường trực Hội đồng Bảo an Liên Hợp Quốc lần đầu tiên", "C. Việt Nam chính thức trở thành thành viên Diễn đàn Hợp tác Kinh tế châu Á – Thái Bình Dương (APEC)", "D. Việt Nam chính thức trở thành thành viên thứ 150 của WTO"], "answer": "C. Việt Nam chính thức trở thành thành viên Diễn đàn Hợp tác Kinh tế châu Á – Thái Bình Dương (APEC)", "letter": "C"}, {"id": 299, "cat": "c3", "q": "Phương châm \"16 chữ vàng\" định hướng quan hệ Việt Nam – Trung Quốc được lãnh đạo cấp cao hai nước thống nhất năm 1999 là gì?", "options": ["A. \"Láng giềng hữu nghị, hợp tác toàn diện, ổn định lâu dài, hướng tới tương lai\"", "B. \"Đoàn kết, dân chủ, kỷ cương, đột phá, phát triển\"", "C. \"Láng giềng tốt, bạn bè tốt, đồng chí tốt, đối tác tốt\"", "D. \"Độc lập, tự chủ, hòa bình, hợp tác và phát triển\""], "answer": "A. \"Láng giềng hữu nghị, hợp tác toàn diện, ổn định lâu dài, hướng tới tương lai\"", "letter": "A"}, {"id": 300, "cat": "dh13", "q": "Phương châm thực hiện dân chủ cơ sở được bổ sung hoàn chỉnh tại Đại hội XIII (2021) thêm hai nội dung mới nào so với trước đó?", "options": ["A. Thêm \"dân đóng góp\" và \"dân điều hành\"", "B. Thêm \"dân giám sát\" và \"dân thụ hưởng\" (thành: Dân biết, dân bàn, dân làm, dân kiểm tra, dân giám sát, dân thụ hưởng)", "C. Thêm \"dân lãnh đạo\" và \"dân phê duyệt\"", "D. Thêm \"dân quyết định\" và \"dân quản lý\""], "answer": "B. Thêm \"dân giám sát\" và \"dân thụ hưởng\" (thành: Dân biết, dân bàn, dân làm, dân kiểm tra, dân giám sát, dân thụ hưởng)", "letter": "B"}, {"id": 301, "cat": "dh13", "q": "Tại Đại hội XIII (2021), khi tổng kết 35 năm Đổi mới, Đảng đưa ra nhận định nổi tiếng khẳng định vị thế lịch sử của đất nước như thế nào?", "options": ["A. \"Đất nước ta chưa bao giờ có được cơ đồ, tiềm lực, vị thế và uy tín quốc tế như ngày nay\"", "B. \"Việt Nam đã bước vào nhóm các nước phát triển thu nhập cao hàng đầu thế giới\"", "C. \"Nước ta đã chấm dứt hoàn toàn mọi nguy cơ tụt hậu và tham nhũng\"", "D. \"Nước ta đã hoàn thành toàn bộ thời kỳ quá độ lên chủ nghĩa xã hội\""], "answer": "A. \"Đất nước ta chưa bao giờ có được cơ đồ, tiềm lực, vị thế và uy tín quốc tế như ngày nay\"", "letter": "A"}, {"id": 302, "cat": "c3", "q": "Theo Giáo trình Lịch sử Đảng, sự khác biệt cơ bản giữa nền kinh tế thị trường định hướng xã hội chủ nghĩa ở Việt Nam với kinh tế thị trường tư bản chủ nghĩa thể hiện ở mục tiêu và sự quản lý như thế nào?", "options": ["A. Chỉ cho phép duy nhất thành phần kinh tế nhà nước tồn tại", "B. Xóa bỏ hoàn toàn vai trò điều tiết vĩ mô của Nhà nước", "C. Không tuân theo quy luật cung – cầu và quy luật cạnh tranh", "D. Nhằm mục tiêu \"dân giàu, nước mạnh, dân chủ, công bằng, văn minh\"; có nhiều hình thức sở hữu, nhiều thành phần kinh tế, trong đó kinh tế nhà nước giữ vai trò chủ đạo, do Nhà nước pháp quyền XHCN quản lý dưới sự lãnh đạo của Đảng"], "answer": "D. Nhằm mục tiêu \"dân giàu, nước mạnh, dân chủ, công bằng, văn minh\"; có nhiều hình thức sở hữu, nhiều thành phần kinh tế, trong đó kinh tế nhà nước giữ vai trò chủ đạo, do Nhà nước pháp quyền XHCN quản lý dưới sự lãnh đạo của Đảng", "letter": "D"}, {"id": 303, "cat": "c3", "q": "Theo Giáo trình Lịch sử Đảng, vì sao Hội nghị Trung ương 6 khóa IV (8/1979) được đánh giá là \"bước đột phá đầu tiên\" về đổi mới kinh tế?", "options": ["A. Vì đã thông qua Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên CNXH", "B. Vì đã chủ trương khắc phục những khuyết điểm, sai lầm trong quản lý kinh tế và cải tạo XHCN, phá bỏ các rào cản để \"làm cho sản xuất bung ra\"", "C. Vì đã xóa bỏ ngay hoàn toàn cơ chế bao cấp trong năm 1979", "D. Vì đã cho phép đảng viên làm kinh tế tư nhân trên cả nước"], "answer": "B. Vì đã chủ trương khắc phục những khuyết điểm, sai lầm trong quản lý kinh tế và cải tạo XHCN, phá bỏ các rào cản để \"làm cho sản xuất bung ra\"", "letter": "B"}, {"id": 304, "cat": "dh1_12", "q": "So sánh Đại hội IV (1976), Đại hội VI (1986), Đại hội VIII (1996) và Đại hội IX (2001) về các bước ngoặt lớn của kinh tế Việt Nam?", "options": ["A. ĐH IV: Kinh tế tri thức → ĐH VI: CNH–HĐH → ĐH VIII: Đổi mới → ĐH IX: Cương lĩnh 2011", "B. ĐH IV: Cả nước quá độ CNXH → ĐH VI: Khởi xướng Đổi mới (xóa bao cấp) → ĐH VIII: Đẩy mạnh CNH–HĐH → ĐH IX: Chính thức xác định mô hình KTTT định hướng XHCN", "C. ĐH IV: Nông nghiệp hàng đầu → ĐH VI: Gia nhập WTO → ĐH VIII: Cương lĩnh 1991 → ĐH IX: Khoán 10", "D. ĐH IV: Khởi xướng Đổi mới → ĐH VI: Xác định KTTT định hướng XHCN → ĐH VIII: Đổi tên ĐCS VN → ĐH IX: Đẩy mạnh CNH–HĐH"], "answer": "B. ĐH IV: Cả nước quá độ CNXH → ĐH VI: Khởi xướng Đổi mới (xóa bao cấp) → ĐH VIII: Đẩy mạnh CNH–HĐH → ĐH IX: Chính thức xác định mô hình KTTT định hướng XHCN", "letter": "B"}, {"id": 305, "cat": "dh1_12", "q": "Theo tổng hợp lịch sử các kỳ Đại hội Đảng từ 1935 đến 2026, duy nhất kỳ Đại hội nào diễn ra ở ngoài lãnh thổ Việt Nam và duy nhất kỳ Đại hội kháng chiến nào diễn ra tại chiến khu Tuyên Quang?", "options": ["A. Đại hội I (3/1935) tại Liên Xô và Đại hội II (2/1951) tại Cao Bằng", "B. Đại hội II (2/1951) tại Quảng Châu và Đại hội IV (12/1976) tại Tuyên Quang", "C. Đại hội I (3/1935) tại Hương Cảng và Đại hội III (9/1960) tại Tuyên Quang", "D. Đại hội I (3/1935) tại Ma Cao (Trung Quốc) và Đại hội II (2/1951) tại Chiêm Hóa, Tuyên Quang"], "answer": "D. Đại hội I (3/1935) tại Ma Cao (Trung Quốc) và Đại hội II (2/1951) tại Chiêm Hóa, Tuyên Quang", "letter": "D"}];
